(window.GIM_TS=window.GIM_TS||{})["Keritot.1"]={"from":24,"a":[["ושואלים: \u0003נימא אית ליה\u0004 \u0005[האם נאמר שיש לו,\u0006 שסבור\u0005] ר'\u0006 \u0003מאיר\u0004 ש\u0003איסור חל על איסור?\u0004 ודוחים: \u0003נהי\u0004 \u0005[אם אמנם]\u0006 שאיסור \u0003חל על איסור לית ליה\u0004 \u0005[אין לו],\u0006 אבל כשיש \u0003איסור כולל,\u0004 כאשר האיסור הנוסף כולל פרטים נוספים, וכן \u0003אסור מוסיף,\u0004 כאשר יש באיסור החדש תוספת איסור, \u0003אית ליה\u0004 \u0005[יש לו,\u0006 סבור הוא\u0005]\u0006 שאיסור חל על איסור.","וכך במשנתנו: מי שהיה \u0003טהור, מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לא\u0004 היה \u0003אסור\u0004 בחתיכה זו \u0003אלא ב\u0004איסור \u0003חלב, הוה ליה\u0004 \u0005[נעשה]\u0006 אותו אדם \u0003טמא, מיגו\u0004 \u0005[מתוך]\u0006 שהוא \u0003אסור\u0004 מעתה גם \u0003בחתיכות\u0004 בשר \u0003טהורות\u0004 (של קודש) — \u0003איתוסף ביה נמי איסורא עילוי\u0004 \u0005[נוסף בו גם כן איסור על]\u0006 \u0003חלב,\u0004 מכח האיסור הכולל.","\u0003ו\u0004כן \u0003חלב\u0004 זה \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003לא\u0004 היה \u0003אסור אלא באכילה, אקדשיה\u0004 \u0005[הקדיש אותו],\u0006 ובכך נאסר ליהנות מן ההקדש בכל דרך, ולא רק באכילה, \u0003מיגו דאיתוסף ביה איסורא\u0004 \u0005[מתוך שנוסף בו\u0006 באדם זה \u0005איסור]\u0006 הנאה מן ההקדש — \u0003איתוסף ביה\u0004 \u0005[נוסף בו]\u0006 איסור זה \u0003לגבי חלב,\u0004 וחייב על כך אשם מעילה.","\u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003להדיוט\u0004 (לאדם) \u0003הוא\u0004 ש\u0003אסור\u0004 חלב של הקדש, \u0003אבל לגבוה\u0004 (למזבח) \u0003שרי\u0004 \u0005[מותר],\u0006 כאשר \u0003הוה ליה\u0004 \u0005[נעשה לו]\u0006 \u0003נותר,\u0004 שעבר זמן הקרבתו, \u0003מיגו דאיתוסף איסורא\u0004 \u0005[מתוך שנוסף\u0006 בו \u0005איסור]\u0006 גם \u0003לגבי גבוה,\u0004 שהרי עכשיו אסור גם להקריב ממנו (איסור מוסיף) — \u0003איתוסף ביה\u0004 \u0005[נוסף בו]\u0006 גם איסור \u0003לגבי הדיוט.\u0004 אם \u0003חל עליה\u0004 \u0005[עליו]\u0006 \u0003יום הכפורים,\u0004 ואותו אדם נאסר מלאכול כל דבר, \u0003מיגו דאיתוסף ביה\u0004 \u0005[מתוך שנוסף בו]\u0006 לאדם \u0003איסור\u0004 גם \u0003לגבי\u0004 אכילת \u0003חולין\u0004 (איסור כולל) — \u0003איתוסף ביה\u0004 \u0005[נוסף בו]\u0006 גם כן איסור \u0003לגבי\u0004 דבר שנאסר כבר ל\u0003גבוה.\u0004","ומקשים, \u0003ונתני\u0004 \u0005[ושישנה]:\u0006 יש אוכל אכילה אחת וחייב עליה \u0003חמש חטאות,\u0004 ולא רק ארבע, \u0003ונוקמה\u0004 \u0005[ויעמיד אותה]\u0006 \u0003כגון\u0004 שאכל גם \u0003כזית\u0004 מקרבן שנעשה \u0003פיגול,\u0004 כגון ששחטוהו או זרקו את דמו של הקרבן על מנת להקריבו או לאוכלו לאחר זמנו! ומשיבים: \u0003בחדא בהמה קמיירי\u0004 \u0005[בבהמה אחת מדובר],\u0006 \u0003בשתי בהמות לא קמיירי\u0004 \u0005[לא מדובר],\u0006 \u0003ונותר ופיגול בחדא בהמה לא משכחת לה\u0004 \u0005[בבהמה אחת אין אתה מוצא אותה],\u0006 שמשעה שנעשה הקרבן פיגול שוב אינו ראוי להקרבה או לאכילה, וממילא אינו נאסר כנותר.","ושואלים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 ייתכן שיאכל נותר ופיגול מאותה בהמה? \u0003משכחת לה\u0004 \u0005[מוצא\u0006 אתה \u0005אותה]\u0006 \u0003כגון שהעלה אבר\u0004 אחר של \u0003פיגול\u0004 מאותה בהמה \u0003לגבי מזבח,\u0004 שהרי מאותה שעה \u0003פקע פיגוליה מיניה\u0004 \u0005[פיגולו ממנו],\u0006 \u0003ו\u0004משעבר זמן הקרבתו \u0003הוה ליה\u0004 \u0005[נעשה לו]\u0006 \u0003נותר,\u0004","\u0003וכדאמר\u0004 \u0005[וכמו שאמר]\u0006 \u0003עולא: קומץ\u0004 של מנחה שהוא \u0003פיגול שהעלה\u0004 אותו \u0003לגבי מזבח\u0004 — \u0003פקע פיגולו ממנו והוה ליה\u0004 \u0005[ונעשה לו]\u0006 \u0003נותר.\u0004 ונמצא שעל האיבר שהעלה חייב משום נותר, ועל האיבר שלא העלה חייב משום פיגול! ודוחים: \u0003באבר אחד קא מיירי\u0004 \u0005[הוא עוסק],\u0006 \u0003בשני אברים לא קמיירי\u0004 \u0005[לא מדובר],\u0006 \u0003ונותר ופיגול בחד אבר לא משכחת לה\u0004 \u0005[באבר אחד אין אתה מוצא אותה].\u0006","ומקשים: \u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא? משכחת לה\u0004 \u0005[מוצא\u0006 אתה \u0005אותה]\u0006 \u0003כגון שהעלה אבר פיגול לגבי מזבח, דפלגיה אנחיה\u0004 \u0005[שאת חציו הניח]\u0006 \u0003על גבי מזבח ופלגיה מאבראי\u0004 \u0005[וחציו\u0006 מונח \u0005מחוץ]\u0006 למזבח, \u0003דההוא\u0004 \u0005[שאותו\u0006 חלק\u0005]\u0006 שהיה על המזבח \u0003פקע פיגול\u0004 ממנו \u0003והוה ליה\u0004 \u0005[ונעשה]\u0006 \u0003נותר, וכדאמר\u0004 \u0005[וכמו שאמר]\u0006 \u0003עולא: קומץ פיגול שהעלה על המזבח\u0004 — \u0003פקע פיגולו ממנו והוי ליה\u0004 \u0005[ונעשה לו]\u0006 \u0003נותר,\u0004 והחלק שמחוץ למזבח נשאר בפיגולו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אי אפשר לומר כן, כי \u0003אי רובא\u0004 \u0005[אם רובו\u0006 של האבר\u0005]\u0006 על המזבח — \u0003שדייה\u0004 \u0005[השלך אותו],\u0006 כלומר, שייך אותו כולו \u0003למזבח,\u0004 אם \u0003רובא דבראי\u0004 \u0005[רובו\u0006 הוא החלק \u0005שבחוץ]\u0006 \u0003שדייה לבראי\u0004 \u0005[השלך אותו\u0006 כולו \u0005לחוץ].\u0006","ומקשים: אם כן, \u0003תפשוט\u0004 \u0005[תפתור מכאן]\u0006 אותה שאלה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רמי בר חמא\u0004 ולא פתר אותה מכאן: האם \u0003הלכו באברים אחר הרוב או לא,\u0004 שהרי אתה מניח כי לפי משנתנו הולכים אחר הרוב! \u0003אלא\u0004 טעם הדבר שלא שנה גם איסור פיגול, כי \u0003ב\u0004אכילת \u0003כזית אחד\u0004 של חלב \u0003קמיירי\u0004 \u0005[מדובר],\u0006 \u0003בשני זיתים לא קא מיירי\u0004 \u0005[לא מדובר].\u0006","ומקשים: \u0003ולא,\u0004 וכי אין הוא עוסק ביותר מכזית? \u0003והקתני\u0004 \u0005[והרי הוא שונה]\u0006 שחייב על אכילה זו אם אכלה ב\u0003יום הכפורים, וביום הכפורים\u0004 רק באכילת שיעור \u0003כותבת\u0004 (תמרה מיובשת) הוא \u0003דמחייב\u0004 \u0005[שמתחייב]\u0006 בחטאת, \u0003וכותבת אית ביה\u0004 \u0005[יש בו שיעור]\u0006 \u0003שני זיתים!\u0004","\u0003אמר ר' זירא:\u0004 ייתכן שיתחייב על אכילת כזית חלב משום כל האיסורים, \u0003כגון שאכל כוליא\u0004 (כליה) \u0003בחלבה,\u0004 עם החלב שעליה, וביחד היה שם ככותבת. \u0003רב פפא אמר: כגון דמלייה\u0004 \u0005[שמילאו]\u0006 את השיעור של כותבת \u0003בתמרי\u0004 \u0005[בתמרים].\u0006","ומעירים: \u0003רב אדא בר אחא מתני\u0004 \u0005[היה שונה]\u0006 שחייב על אכילה אחת \u0003חמש חטאות,\u0004 ולא רק ארבע כמשנתנו, \u0003ומתריץ לה\u0004 \u0005[ומתרץ אותה]\u0006 \u0003כגון\u0004 ש\u0003אכל\u0004 יחד עם כזית חלב גם \u0003כזית פיגול\u0004 מבהמה אחרת, \u0003ולא משני כהני שינויי דקא משנינן\u0004 \u0005[ואינו מתרץ כאותם תירוצים שתירצנו],\u0006 בשם ר' זירא ורב פפא.","ושואלים: \u0003ונתני\u0004 \u0005[ושישנה]:\u0006 \u0003שש חטאות, ונוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 \u0003כגון\u0004 שאכל בנוסף לאותם שני זיתים גם \u0003כזית דם!\u0004 ומשיבים: \u0003בחדא אכילה קא מיירי\u0004 \u0005[באכילה אחת מדובר],\u0006 \u0003בשתי אכילות לא קא מיירי\u0004 \u0005[לא מדובר],\u0006 \u0003ושיערו חכמים\u0004 שאין \u0003בית הבליעה מחזיק\u0004 בשעת אכילה \u0003יותר משני זיתים.\u0004","שנינו במשנה, ר' מאיר \u0003אומר:\u0004 אם היתה שבת והוציאו בפיו — חייב. ושואלים: \u0003ונתני\u0004 \u0005[ושישנה]:\u0006 \u0003אם הוציאו\u0004 — \u0003חייב,\u0004 שהרי מדובר ביום הכיפורים, שגם הוא אסור במלאכה, \u0003מאי טעמא קתני\u0004 \u0005[מה טעם הוא שונה]\u0006 בלשון \u0003\"אם היתה שבת\"? אמר רפרם:\u0004 הדגשה \u0003זאת אומרת\u0004 שיש דין \u0003עירוב ו\u0004איסור \u0003הוצאה לשבת, ואין עירוב והוצאה ליום הכפורים.\u0004","ושואלים: \u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מסיק זאת? \u0003דלמא\u0004 \u0005[שמא]\u0006 אמור כך: \u0003יש\u0004 גם \u0003עירוב והוצאה ליום הכפורים, והכי קתני\u0004 \u0005[וכך הוא שונה]:\u0006 \u0003אם היתה שבת והוציאו\u0004 — \u0003חייב אף משום שבת ו\u0004אף משום \u0003יום הכפורים!\u0004","\u0003אלא אי איתמר\u0004 \u0005[אם נאמר]\u0006 דבר זה של \u0003רפרם על הדא איתמר\u0004 \u0005[זה נאמר],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין שעיר המשתלח ביום הכיפורים: \u0003\"ושלח ביד איש עתי\"\u0004 (ויקרא טז, כא), \"\u0003איש\"\u0004 — להכשיר את הזר, שאינו כהן, \"\u0003עתי\"\u0004 — שצריך שייעשה הדבר במועדו, \u0003אפילו בטומאה,\u0004 שהוא יכול להיכנס לעזרה כשהוא טמא ולקחתו משם, \u0003ואפילו בשבת, \"עתי\"\u0004 — \u0003ב\u0004איש ש\u0003מזומן\u0004 לכך מאתמול.","ועל מה שהוא \u0003קתני\u0004 \u0005[שונה]: \"\u0006\u0003עתי\"\u0004 — \u0003אפילו בשבת, אמר רפרם: זאת אומרת\u0004 שדין \u0003עירוב והוצאה לשבת, ואין עירוב והוצאה ליום הכפורים.\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה\u0006 אתה מוכיח\u0005]\u0006\u0003? שאני\u0004 \u0005[שונה]\u0006 \u0003שעיר המשתלח,\u0004 שהכשירו \u0003ביום הכפורים בכך,\u0004 וגם אם היה איסור הוצאה ביום הכפורים — מותר הדבר! \u0003אלא\u0004 יש לומר שזו של \u0003רפרם ברותא\u0004 \u0005[חיצונית]\u0006 \u0003היא,\u0004 כלומר, לא נאמרה בבית המדרש.","\u0003יש בא ביאה אחת וחייב עליה שש חטאות, כיצד? הבא על בתו\u0004 יכול שיהא \u0003חייב עליה משום בתו, ואחותו,\u0004 וכגון שבא על אמו וממנה נולדה בת זו, וכן יתחייב עליה משום \u0003אשת אחיו,\u0004 אם נשאה אחיו. \u0003ו\u0004משום \u0003אשת אחי אביו,\u0004 אם מת אחיו או נתגרשה ממנו ונישאה לאחי אביו, \u0003ו\u0004משום \u0003אשת איש,\u0004 שהיא אשתו של אחיו, \u0003ו\u0004משום \u0003נדה,\u0004 אם בא עליה בנידתה."],["שואלים: כיצד יכול אדם להתחייב כל כך הרבה חטאות? \u0003והא לית ליה\u0004 \u0005[והרי אין לו] לר'\u0006 \u0003מאיר,\u0004 לדעתו אין \u0003איסור חל על איסור!\u0004 ומשיבים: \u0003נהי\u0004 \u0005[אף]\u0006 שבסתם \u0003איסור חל על איסור לית ליה\u0004 \u0005[אין לו],\u0006 אבל ב\u0003איסור מוסיף ואיסור כולל אית ליה\u0004 \u0005[יש לו]\u0006 איסור חל על איסור. וכיצד מתקיים הדבר במשנתנו?","\u0003כגון שבא על אמו והוליד\u0004 ממנה \u0003בת,\u0004 ש\u0003איסור בתו ואחותו\u0004 בבת זו \u0003בהדי הדדי אתי\u0004 \u0005[בבת אחת הם באים].\u0006 אם אותה בת \u0003נשאת לאחיו, מיגו דאיתוסף\u0004 \u0005[מתוך שנוסף בה]\u0006 \u0003איסור לגבי\u0004 כל ה\u0003אחין\u0004 משום אשת אח — \u0003איתוסף איסורא לגבי דידיה\u0004 \u0005[נוסף\u0006 ה\u0005איסור\u0006 גם \u0005לגביו].\u0006","\u0003נשאת לאחי אביו, מיגו דאיתוסף איסורא\u0004 \u0005[מתוך שנוסף\u0006 בה \u0005איסור]\u0006 \u0003לגבי שאר\u0004 בני \u0003אחי אביו\u0004 — \u0003איתוסף\u0004 \u0005[נוסף]\u0006 איסור זה גם \u0003לגבי דידיה\u0004 \u0005[לגביו].\u0006 \u0003הויא לה\u0004 \u0005[נעשתה]\u0006 אותה אשה \u0003אשת איש, מיגו דאיתוסף\u0004 \u0005[מתוך שנוסף\u0006 בה\u0005]\u0006 \u0003איסור לגבי עלמא\u0004 \u0005[העולם,\u0006 כל האנשים\u0005]\u0006 — \u0003איתוסף נמי לגבי דידיה\u0004 \u0005[נוסף גם כן\u0006 לגביו\u0005].\u0006 \u0003הויא לה\u0004 \u0005[נעשתה]\u0006 \u0003נדה, מיגו דאיתוסף\u0004 \u0005[מתוך שנוסף\u0006 בה\u0005]\u0006 \u0003איסור לגבי בעלה\u0004 — \u0003איתוסף נמי לגבי דידיה\u0004 \u0005[נוסף גם כן לגביו].\u0006","\u0003הבא על בת בתו\u0004 — פעמים שחייב \u0003עליה\u0004 בביאה אחת \u0003משום בת בתו, וכלתו,\u0004 כגון שנשאה בנו. ויכול להיות חייב עליה גם משום \u0003אשת אחיו,\u0004 אם נישאה לאחיו, \u0003ו\u0004משום \u0003אשת אחי אביו,\u0004 אם גירשה אחיו או מת ונישאה לאחי אביו, \u0003ו\u0004משום \u0003אחות אשתו,\u0004 אם היתה אחותה נשואה לו, \u0003ו\u0004משום \u0003אשת איש, ו\u0004משום \u0003נדה,\u0004 אם בא עליה בנידתה. \u0003ר' יוסי אומר: אם עבר זקן,\u0004 אביו של זה, \u0003ונשאה\u0004 — \u0003חייב עליה\u0004 הבן גם \u0003משום אשת אב.\u0004","\u0003וכן הבא על בת אשתו\u0004 יש שחייב עליה שש חטאות, בדומה לבא על בתו: משום בת אשתו, ואחותו, ואשת אחיו, ואשת אחי אביו, ואשת איש, ונדה. \u0003ו\u0004כן הבא \u0003על בת בתה\u0004 של אשתו חייב עליה שבע חטאות, בדומה לבא על בת בתו: משום בת בת אשתו, וכלתו, ואחות אשתו, ואשת אחיו, ואשת אחי אביו, ואשת איש, ונדה.","\u0003קתני\u0004 \u0005[הריהו שונה\u0006 במשנה\u0005],\u0006 ר' יוסי אומר: אם עבר זקן (אביו) ונשאה \u0003חייב עליה משום אשת אב.\u0004 ושואלים: \u0003מי שריא ליה\u0004 \u0005[האם\u0006 אשה זו \u0005מותרת לו]\u0006 לאביו של זה? והלוא היתה נשואה לאחיו של האב, ואין קידושין תופסים בה, שתהא קרויה אשתו! \u0003אמר ר' יוחנן: כגון שנפלה לו\u0004 לאביו \u0003ליבום,\u0004 שמת אחי אביו בלא בנים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שנפלה לו ליבום, \u0003מאי\u0004 \u0005[מה]\u0006 פשר הלשון \u0003\"עבר\u0004 זקן ונשאה\"? \u0003אמר ר' יעקב: שעבר\u0004 עליה \u0003משום כלת בנו,\u0004 שהיא \u0003שניה\u0004 לעריות.","שאף על פי שאינה אסורה עליו מן התורה, מכל מקום היא אסורה מדברי סופרים, ואסור לו לייבמה, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006\u0003: כלתו\u0004 אסורה עליו משום איסור \u0003ערוה, כלת בנו\u0004 אסורה משום \u0003שניה. וכן אתה מוצא בבת בנו\u0004 שהיא ערוה, \u0003ובבת בן בנו\u0004 שהיא שניה. ואיסור זה הוא \u0003עד סוף כל הדורות,\u0004 כגון בת בן בן בנו, ובת בת בת בן בנו, שכולן אסורות משום שניות.","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0005לר' י\u0006 \u0003וסי איסור חל על איסור? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה]: \u0003עבר עבירה שיש בה שתי מיתות\u0004 — \u0003נידון ב\u0004מיתה ה\u0003חמורה\u0004 שבהם, ר' \u0003יוסי אומר: נידון בזיקה ראשונה שבאה עליו,\u0004 כלומר לפי האיסור הראשון שחל עליו.","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006\u0003: כיצד אמר ר' יוסי נידון בזיקה ראשונה?\u0004 כגון \u0003חמותו,\u0004 שהיתה אלמנה \u0003ונעשת אשת איש,\u0004 אם בא עליה — הרי הוא \u0003נידון\u0004 עליה \u0003משום חמותו,\u0004 בשריפה, משום שאיסור חמותו חל עליו בראשונה.","ואם היתה \u0003אשת איש ונעשת חמותו\u0004 — \u0003נידון משום אשת איש,\u0004 בחנק, למרות ששריפה חמורה יותר. הרי שלדעת ר' יוסי אין איסור חל על איסור!","\u0003אמר ר' אבהו: מודה ר' יוסי באיסור מוסיף\u0004 שאיסור חל איסור, ולכן הוא מחייב במשנתנו גם משום אשת האב. \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם ר' \u0003יוחנן: מודה ר' יוסי באיסור מוסיף.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003איסור מוסיף איכא הכא\u0004 \u0005[יש כאן]?\u0006 ומשיבים: \u0003דאיכא ברא לסבא\u0004 \u0005[שיש בן\u0006 נוסף \u0005לזקן,\u0006 לאביו\u0005],\u0006 \u0003מיגו דאיתוסף איסורא לגבי בריה\u0004 \u0005[מתוך שנוסף איסור לגבי בנו\u0006 הנוסף של אביו\u0005]\u0006 משום אשת אביו — \u0003איתוסף איסורא לגבי דידיה\u0004 \u0005[נוסף איסור\u0006 זה \u0005לגביו].\u0006","\u0003הבא על חמותו\u0004 בשוגג פעמים שחייב \u0003עליה\u0004 בביאה אחת שבע חטאות: \u0003משום חמותו, וכלתו, ואשת אחיו, ואשת אחי אביו, ואחות אשתו, ואשת איש, ונדה. וכן הבא על אם חמיו, ועל אם חמותו\u0004 יכול שיתחייב שבע חטאות על ביאה אחת.","\u0003ר' יוחנן בן נורי אומר: הבא על חמותו\u0004 בשוגג יש ש\u0003חייב עליה\u0004 בביאה זו שלוש חטאות, \u0003משום חמותו, ואם חמותו, ואם חמיו. אמרו לו: שלשתן שם אחד\u0004 של איסור \u0003הן,\u0004 שנלמדו מכתוב אחד, שנאמר: \"ערות אשה ובתה לא תגלה את בת בנה ואת בת בתה לא תקח\" (ויקרא יח, יז), ולפיכך אין חילוק חטאות ביניהם.","\u0003אמר ר' אלעזר אמר ר' הושעיא: ר' יוחנן בן נורי וסומכוס אמרו דבר אחד. ר' יוחנן בן נורי\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בענין הבא על חמותו, שמתחייב עליה גם משום אם חמותו ואם חמיו. \u0003סומכוס מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006"],["\u0003שחטה\u0004 לבהמה ושחט באותו יום \u0003את בת בתה, ואחר כך שחט\u0004 באותו יום \u0003את בתה\u0004 של הראשונה — הרי זה \u0003סופג את הארבעים,\u0004 משום איסור שחיטת אותו ואת בנו ביום אחד (ויקרא כב, כח). סומכוס אמר משום ר' \u0003מאיר: סופג שמונים,\u0004 שחייב על שחיטת הבת גם משום אמה שנשחטה באותו יום, וגם משום בתה שנשחטה באותו יום. הרי שגם לדעת סומכוס, כאשר במעשה אחד עובר על שני איסורים הבאים מכתוב אחד — חייב משום שניהם.","\u0003אמר רבא: דלמא\u0004 \u0005[שמא]\u0006 \u0003לא היא,\u0004 אין ההשוואה נכונה, ויש מקום לחלק בין השיטות: \u0003עד כאן לא קאמר\u0004 \u0005[\u0006שמענו ש\u0005אומר]\u0006\u0003 ר' יוחנן בן נורי הכא\u0004 \u0005[כאן]\u0006 שחייב על חמותו גם משום אם חמותו וגם משום אם חמיו, \u0003אלא משום\u0004 שיש באשה זו שלושה \u0003שמות מוחלקין, דמיקריא\u0004 \u0005[ש\u0006היא \u0005נקראת]\u0006 \u0003חמותו, ומיקריא\u0004 \u0005[ונקראת]\u0006 \u0003אם חמותו, ומיקריא\u0004 \u0005[ונקראת]\u0006 \u0003אם חמיו,\u0004 ויש בתורה איסור ביחס לכל אחת מהן.","\u0003אבל גבי\u0004 האיסור של \u0003אותו ואת בנו, דכולהו\u0004 \u0005[שכולן]\u0006 \u0003\"אותו ואת בנו\" מיקריין\u0004 \u0005[נקראות]\u0006 בתורה, גם האם ואחר כך הבת, וגם הבת ואחר כך האם, ש\u0003אין\u0004 כאן \u0003שמות מוחלקין\u0004 — \u0003לא\u0004 מחייב ר' יוחנן בן נורי משום שני איסורים.","וכן \u0003אמר רב נחמן בר יצחק\u0004 מן הצד האחר: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003עד כאן לא קאמר\u0004 \u0005[\u0006שמענו ש\u0005אומר]\u0006 \u0003סומכוס\u0004 שיש לחלק במעשה אחד \u0003אלא גבי אותו ואת בנו,\u0004 שהרי יש פה שני \u0003גופין מוחלקין,\u0004 ששחט מתחילה אותה ואת בת בתה, ולכן כשהוא שוחט לאחר מכן את בתה יש לומר שמתחייב משום שני האיסורים.","\u0003אבל הכא\u0004 \u0005[כאן],\u0006 במקרה של חמותו, ש\u0003אין גופין מוחלקין,\u0004 שהרי יש כאן רק ביאה על אשה אחת, \u0003אימא\u0004 \u0005[אמור]\u0006 שכר' \u0003אבהו אמר ר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 ממה שנאמר בסוף הפסוק המלמד על איסור חמותו ואם חמותו ואם חמיו: \u0003\"שארה הנה זמה היא\"\u0004 (שם יח, ז), אתה למד כי \u0003הכתוב עשאן לכולן זמה אחת,\u0004 עבירה אחת, אף על פי שיש כאן שמות שונים.","\u0003אמר רבי עקיבא: שאלתי את רבן גמליאל ואת ר' יהושע באיטליס\u0004 (שוק) \u0003של עימאום,\u0004 בשעה \u0003שהלכו ליקח\u0004 (לקנות) \u0003בהמה למשתה\u0004 חתונתו של \u0003בנו של רבן גמליאל, הבא\u0004 בשוגג \u0003על אחותו ועל אחות אביו ועל אחות אמו\u0004 בהעלם אחד, \u0003מהו,\u0004 מה הדין? האם \u0003חייב\u0004 חטאת \u0003אחת על כולן, או חייב על כל אחת ואחת?\u0004","\u0003אמרו לו:\u0004 דבר זה בפירוש \u0003לא שמענו\u0004 מרבותינו, \u0003אבל שמענו\u0004 ש\u0003הבא\u0004 בשוגג \u0003על חמש נשיו\u0004 כשהיו \u0003נדות בהעלם אחת,\u0004 כגון שלא נודע לו בין הביאות שיש איסור בדבר, \u0003שהוא חייב\u0004 חטאת \u0003על כל אחת ואחת, ורואה אני שהדברים קל וחומר\u0004 לענין אחותו ואחות אביו ואחות אמו, שהרי הם שלושה איסורים שונים.","ומתקשים בשאלתו של ר' עקיבא: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]?\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם תאמר\u0006 בדיוק \u0005כפי שהוא שונה],\u0006 שבא על אחותו ועל אחות אביו ועל אחות אמו, \u0003מאי תיבעי ליה\u0004 \u0005[מדוע נשאלה לו]\u0006 שאלה זו? \u0003הרי\u0004 יש כאן \u0003שמות\u0004 (לאוים) \u0003מוחלקין\u0004 של איסור: איסור אחותו, ואיסור אחות אביו, ואיסור אחות אמו, וכן \u0003הרי גופין מוחלקין,\u0004 שבא על שלוש נשים נפרדות, ובמקרה זה פשוט הדבר שחייב על כל אחת ואחת!","\u0003אלא הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 כך שאל ר' עקיבא: \u0003הבא על\u0004 אחותו שהיא גם \u0003אחות אביו, שהיא\u0004 גם \u0003אחות אמו,\u0004 האם \u0003חייב\u0004 חטאת \u0003אחת על כולן,\u0004 על כל האיסורים שיש בה, \u0003או חייב על כל אחת ואחת, מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003הרי\u0004 יש כאן \u0003שמות מוחלקין, או דלמא\u0004 \u0005[שמא]\u0006 \u0003הרי אין גופין מוחלקין?\u0004","על כך \u0003אמרו לו\u0004 רבן גמליאל ור' יהושע: דבר זה \u0003לא שמענו, אבל שמענו: הבא על חמש נשיו נדות בבת אחת\u0004 (בהעלם אחד), \u0003שהוא שם אחד, שחייב על כל אחת ואחת משום נדה,\u0004","\u0003וראינו שהדברים קל וחומר: ומה הבא על חמש נשיו נדות בבת אחת,\u0004 למרות \u0003שהיא שם אחת,\u0004 שעבר על כולן משום אותו איסור — \u0003חייב על כל אחת ואחת,\u0004 הבא על \u0003אחותו שהיא אחות אביו שהיא אחות אמו, שהן שלשה שמות\u0004 שונים של איסור — \u0003אינו דין שיהא חייב על כל אחת ואחת?\u0004","ומקשים, \u0003איכא למיפרך\u0004 \u0005[יש לפרוך]\u0006 קל וחומר זה: \u0003מה לחמש נדות\u0004 שחייב על כל אחת — \u0003שכן גופין מוחלקין\u0004 הן, שאף על פי שאיסור אחד הוא, מכל מקום בא על חמש נשים. ואילו הבא על אחותו שהיא אחות אביו ואחות אמו — בא על אשה אחת!","\u0003אלא\u0004 זהו טעמו של דבר, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"ואיש אשר יקח את אחותו... ונכרתו לעיני בני עמם \u0003ערות אחתו גלה\"\u0004 (שם כ, יז), ותוספת זו באה \u0003לחייב\u0004 כריתות (וחטאות) נפרדות אם בא \u0003על אחותו שהיא אחות אביו שהיא אחות אמו. וכיצד ייתכן שתהא לו אחות שהיא גם אחות אביו וגם אחות אמו?\u0004","\u0003אמר רב אדא בר אהבה: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003ברשיעא בר רשיעא\u0004 \u0005[ברשע בן רשע],\u0006 כיצד? כגון \u0003שבא\u0004 אדם \u0003על אמו והוליד\u0004 ממנה \u0003שתי בנות, וחזר ובא על אחת מהן\u0004 מהבנות \u0003והוליד\u0004 ממנה \u0003בן, ובא בנו על אחות אמו, שהיא אחותו\u0004 מאביו, \u0003שהיא\u0004 גם \u0003אחות אביו, דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003רשיעא בר רשיעא\u0004 \u0005[רשע בן רשע],\u0006 שכשם שאביו הרשיע ובא על אמו — כך הוא מרשיע שבא על אחותו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בא עליה\u0004 על אשה האסורה לו באיסור כרת, \u0003וחזר ובא עליה, וחזר ובא עליה\u0004 בהעלם אחד — \u0003חייב\u0004 חטאת \u0003על כל אחת ואחת\u0004 מן הביאות, אלו \u0003דברי ר' אליעזר. וחכמים אומרים: אינו חייב אלא\u0004 חטאת \u0003אחת.\u0004","\u0003ו\u0004בכל זאת \u0003מודים חכמים לר' אליעזר, בבא על חמש נשיו נדות בבת אחת\u0004 (בהעלם אחד) — \u0003שהוא חייב על כל אחת ואחת, הואיל והוא גרם להן,\u0004 לכל אחת מהן, להביא חטאת על שגגתה.","\u0003אמר רבא לרב נחמן: מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 משתמשים בנימוק \u0003\"הואיל והוא גרם להן\"\u0004 כדי לחייבו בחטאת? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 הבא על אשה אסורה לו, \u0003הוא בהעלם אחת והיא בחמש העלמות,\u0004 שבכל פעם נודע לה האיסור וחזרה ושכחה — \u0003הוא אינו חייב אלא אחת, והיא חייבת על כל אחת ואחת,\u0004 אף על פי שהוא גרם לה!","\u0003אלא אימא\u0004 \u0005[אמור]:\u0006 טעם הדבר שחייב על כל אחת ואחת — \u0003הואיל וגופין מוחלקין\u0004 הן.","בעקבות דברי ר' אליעזר, שהבא על אשה וחזר ובא עליה — חייב חטאת על כל ביאה, גם אם היה זה בהעלם אחד, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006\u0003: קצר\u0004 תבואה בשבת בשיעור כגרוגרת (תאנה מיובשת), שהוא השיעור המחייב בחטאת, \u0003ו\u0004חזר \u0003וקצר,\u0004 והיה זה בהעלם אחד, \u0003מה לי אמר ר' אליעזר?\u0004 מה דעתו?","האם \u0003טעמא\u0004 \u0005[טעמו]\u0006 של ר' \u0003אליעזר התם\u0004 \u0005[שם,\u0006 בעריות\u0005]\u0006 \u0003משום דהוא דעבד תרתין\u0004 \u0005[שעשה שתים],\u0006 שתי עבירות, \u0003ואמטול להכי אמר\u0004 \u0005[ומשום כך\u0006 הוא \u0005אומר]\u0006 ש\u0003חייב על כל אחת ואחת, והכא נמי דעבד תרתין\u0004 \u0005[וכאן גם כן\u0006 חייב שתים, \u0005ש\u0006הרי \u0005עשה שתים].\u0006","\u0003או דלמא טעמיה\u0004 \u0005[שמא טעמו]\u0006 של ר' \u0003אליעזר התם\u0004 \u0005[שם]\u0006 \u0003משום\u0004 ש\u0003אי אפשר לו לערבן לביאות זו בזו\u0004 — \u0003אמטול להכי\u0004 \u0005[\u0006ודווקא \u0005משום כך]\u0006 \u0003אמר ר' אליעזר: חייב על כל אחת ואחת, אבל קצר כגרוגרת וחזר וקצר כגרוגרת בהעלם אחת, כיון\u0004 ש\u0003אפשר לו לערב,\u0004 שיכול לקצור \u0003שתי גרוגרות בבת אחת\u0004 — \u0003אינו חייב אלא אחת, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","\u0003אמר רבה: טעמא\u0004 \u0005[טעמו]\u0006 של ר' \u0003אליעזר התם\u0004 \u0005[שם]\u0006 בבא על אשה ביאות הרבה — \u0003משום דעבד תרתי\u0004 \u0005[שעשה שתים],\u0006 \u0003הכא נמי הא עבד תרתי\u0004 \u0005[כאן גם כן,\u0006 כשקצר וחזר וקצר, הרי \u0005עשה שתים].\u0006 \u0003ורב יוסף אמר: טעמא\u0004 \u0005[טעמו]\u0006 של ר' \u0003אליעזר התם\u0004 \u0005[שם]\u0006 שמחייב על כל ביאה — מפני ש\u0003אי אפשר לו לערבן, אבל אפשר לו לערבן,\u0004 וכגון בקצירה של גרוגרת ועוד גרוגרת — \u0003אינו חייב אלא אחת.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבה\u0004 ממה ששנינו בברייתא: \u0003ר' אליעזר מחייב\u0004 חטאת נפרדת \u0003על ולדי מלאכות במקום אבות מלאכות,\u0004 שאם עשה אב מלאכה בשוגג, ובאותו העלם עשה ולד של אותה מלאכה (וכגון שזרע תבואה והשקה את השדה) מביא שתי חטאות.","ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003אב ואב,\u0004 שחזר על אותו אב מלאכה עצמו \u0003בבת אחת\u0004 (בהעלם אחד) — \u0003פטור. ואי אמרת טעמא\u0004 \u0005[ואם אומר אתה\u0006 כי \u0005טעמו]\u0006 של ר' \u0003אליעזר\u0004 שמחייב על שתי ביאות באשה אחת, הוא \u0003משום דקעבד תרתי\u0004 \u0005[שעושה שתים],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור?\u0004 הלא עשה שתי פעולות איסור!","\u0003אמר מר בריה דרבנן, אנא\u0004 \u0005[אני]\u0006 \u0003ורב נחומי בר זכריה תרגימנא\u0004 \u0005[תרגמנו,\u0006 הסברנו\u0005]\u0006 את הדבר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 שיתחייב שתי חטאות על אב ותולדה —","\u0003בדלית\u0004 (גפן מטפסת) \u0003המודלית על גבי תאינה, וקצצן בבת אחת\u0004 (בהעלם אחד), את שריגי הגפן ואת התאנים, שחייב על התאנים משום אב מלאכה קוצר, ועל קציצת שריגי הגפן משום זמירה, שהיא תולדת קוצר, \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מחייב ר' אליעזר\u0004 שתי חטאות, \u0003הואיל ושמות מוחלקין\u0004 הם (אב ותולדה) \u0003ו\u0004גם \u0003גופין מוחלקין\u0004 (גפן ותאנה).","\u0003דכוותה\u0004 \u0005[שכמוה]\u0006 \u0003קצר\u0004 וחזר \u0003וקצר היכי משכחת לה דמיפטר\u0004 \u0005[כיצד מוצא אתה שהוא פטור],\u0006 וחייב רק חטאת אחת? \u0003כגון שקצר שתי גרוגרות בבת אחת,\u0004 שעשה מעשה אחד של איסור. \u0003אבל קצר כגרוגרת וחזר וקצר כגרוגרת\u0004 — \u0003חייב,\u0004 משום שעשה שתים.","\u0003ועוד שאל רבי עקיבא\u0004 את רבן גמליאל ור' יהושע באיטליס של עימאום: \u0003אבר המדולדלת בבהמה,\u0004 שנחתך ומחובר במקצת לגופה, \u0003מהו?\u0004 האם הוא מטמא כדין איבר מן החי? \u0003אמרו לו: לא שמענו\u0004 מרבותינו תשובה לכך, \u0003אבל שמענו\u0004 לגבי \u0003אבר המדולדלת באדם שהוא טהור, וכך היו\u0004"],["\u0003מוכי שחין עושין בירושלים,\u0004 שאם בגלל מחלתו היה לו איבר מדולדל \u0003הולך לו ערב פסח אצל הרופא, ו\u0004הרופא \u0003חותכו\u0004 את האיבר מגופו, \u0003עד שמניח בו\u0004 חיבור דק \u0003כשערה, ותוחבו\u0004 את האיבר \u0003בסירא\u0004 (קוץ) המחובר לקרקע או לכותל, \u0003ו\u0004כשהחולה הולך \u0003נמשך\u0004 האיבר \u0003ממנו\u0004 וניתק,","\u0003ו\u0004כך \u0003הלה,\u0004 מוכה השחין \u0003עושה פסחו\u0004 בטהרה, שלא נטמא מחמת האיבר משנתלש, כדין הנוגע באיבר מן החי, \u0003ו\u0004גם \u0003הרופא עושה פסחו,\u0004 שלא נגע באיבר משנתלש. ומכל מקום בעודו מחובר ומדולדל — לא טימא האיבר את הנוגעים בו. \u0003ורואה אני שהדברים קל וחומר,\u0004 שאם איבר המדולדל באדם, שטומאתו חמורה, אינו מטמא — קל וחומר איבר המדולדל בבהמה.","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003המוחק\u0004 (מקנח בכח) \u0003את הכרישה\u0004 ממי הגשמים שנפלו עליה, \u0003והסוחט\u0004 משקים שנספגו \u0003בשערו ובכסותו\u0004 — \u0003משקה\u0004 (משקים) \u0003ש\u0004נשארו \u0003בתוכו אינם ב\"כי יותן\",\u0004 כלומר, אינם נחשבים כמשקה להכשיר אוכל לקבלת טומאה (ראה ויקרא יא, לח), והמשקים \u0003היוצאין ממנו הרי הן ב\"כי יותן\",\u0004 שאם נפלו על אוכל — הוכשר לקבלת טומאה, שהרי החשיבם.","\u0003אמר שמואל: וכרישה עצמה הוכשרה\u0004 לקבל טומאה, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]? בשעת פרישה\u0006 של המים \u0003ממנו הוכשרה\u0004 על ידם. ומקשים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006\u0003: ערב פסח הולך לו\u0004 מוכה השחין","\u0003אצל\u0004 הרופא, \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003בשעת פרישתן הוכשר\u0004 הכרישה, \u0003הא איכא נמי ההוא\u0004 \u0005[הרי יש גם כן אותו]\u0006 \u0003אבר המדולדל, בשעת פרישתו מאדם,\u0004 כאשר הוא נעשה איבר מן החי — \u0003נטמייה\u0004 \u0005[יטמאנו]\u0006 \u0003לאדם\u0004 במגעו!","ומשיבים: \u0003כדקאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב יוסף\u0004 לענין אחר, שמדובר \u0003בניתזין בכל כחן, הכא נמי\u0004 \u0005[כאן גם כן],\u0006 באיבר המדולדל, יש להסביר כי מדובר \u0003בניתזין בכל כחן,\u0004 שהאיבר נמשך בבת אחת, ואין האדם נחשב כנוגע בו. אבל כשמוחק את הכרישה — אין המים ניתזים ממנה בבת אחת, ולכן תוך כדי פרישה הריהם מכשירים אותה.","\u0003והיכא איתמר\u0004 \u0005[והיכן,\u0006 על מה \u0005נאמר]\u0006 הסברו של \u0003רב יוסף? אהא\u0004 \u0005[על זו]\u0006 ששנינו: \u0003זב וטמא מת שהיו מהלכים וירדו עליהם גשמים, אף על פי שסוחטין זה את זה\u0004 את בגדיהם, שמחליקים את המים מעליהם — \u0003משקין היורדין מצד העליון\u0004 של הבגד \u0003לצד התחתון\u0004 — \u0003טהורים, ש\u0004אינם טמאים מחמת מגע הטמא או בגדיו, לפי \u0003שאין\u0004 הם \u0003מחשבין\u0004 (נחשבים) משקה \u0003אלא\u0004 לאחר \u0003שיצאו מכולן,\u0004 מן הבגד כולו.","\u0003יצאו מכולן,\u0004 מכל הבגד — \u0003הרי\u0004 הם \u0003מכשירין\u0004 אוכלים לקבל טומאה, שהרי החשיבם, אבל לא נטמאו, לפי \u0003שאין\u0004 הם \u0003נחשבין\u0004 כמשקים לקבל טומאה \u0003אלא לאחר ש\u0004כבר \u0003יצאו מגופו\u0004 של הבגד. \u0003אמר רב יוסף:\u0004 טעם הדבר שאינם נטמאים מן הבגד בשעה שהם פורשים ממנו — מפני שמדובר \u0003בניתזין בכל כחן.\u0004","\u0003ועוד שאלו ר' עקיבא\u0004 את רבן גמליאל ור' יהושע: \u0003השוחט חמשה זבחים בחוץ\u0004 (מחוץ למקדש) בשוגג, ושחט כולם \u0003בהעלם אחת,\u0004 שלא נודע לו האיסור בין שחיטה לשחיטה, \u0003מהו?\u0004 האם \u0003חייב\u0004 חטאת \u0003על כל אחת ואחת או אחת על כולן? אמרו לו: לא שמענו\u0004 מרבותינו.","\u0003אמר ר' יהושע: שמעתי באוכל מזבח אחד מחמשה תמחויין\u0004 (כלים) שונים \u0003בהעלם אחת, שהוא חייב על כל אחת ואחת\u0004 קרבן אשם \u0003משום מעילה, ורואה אני שהדברים קל וחומר.\u0004","\u0003אמר ר' שמעון: לא כך שאלו ר' עקיבא,\u0004 על השוחט חמישה זבחים בחוץ, \u0003אלא באוכל נותר מחמשה זבחים בהעלם אחת, מהו,\u0004 האם \u0003חייב אחת על כולן או חייב על כל אחת ואחת? אמרו לו: לא שמענו.\u0004","\u0003אמר ר' יהושע: שמעתי באוכל מזבח אחד בחמשה תמחויין בהעלם אחת, שהוא חייב על כל אחת ואחת משום מעילה, ורואה אני שהדברים קל וחומר.\u0004","\u0003אמר לו ר' עקיבא: אם הלכה\u0004 מקובלת היא, בענין האוכל נותר מחמישה זבחים — \u0003נקבל,\u0004 אבל \u0003אם לדין,\u0004 שאתה סבור כן מתוך הקל וחומר ממעילה — \u0003יש\u0004 על כך \u0003תשובה. אמר לו: השב.\u0004","\u0003אמר: ולא,\u0004 אין זה קל וחומר, \u0003אם אמרת\u0004 כן \u0003במעילה,\u0004 שיש בה צדדים של חומרה — \u0003שעשה בה את המאכיל כאוכל,\u0004 שהנותן לחבירו בשר קודש לאכול חייב קרבן מעילה כאילו אכלו בעצמו, \u0003ואת המהנה\u0004 את חבירו משל הקדש (בדבר שאינו בר אכילה) \u0003כ\u0004אילו \u0003נהנה\u0004 בעצמו, וכן","\u0003צירף את המעילה לזמן מרובה,\u0004 שאפילו נהנה היום בכחצי פרוטה ולמחר בכחצי פרוטה — חייב על כך קרבן מעילה, \u0003תאמר בנותר שאין בו אחת מאלו?\u0004","ושואלים: \u0003מאי קשיא ליה\u0004 \u0005[מה\u0006 היה \u0005קשה לו]\u0006 \u0003לר' שמעון,\u0004 שלדעתו לא שאל ר' עקיבא על השוחט חמישה זבחים בחוץ, אלא על האוכל נותר מחמישה זבחים? ומשיבים: \u0003הכי קא קשיא ליה\u0004 \u0005[כך קשה לו]:\u0006 והרי ר' יהושע הביא לו ראיה מן האוכל, ואם בשוחט שאל ר' עקיבא \u0003מה ראיה לשוחט מאוכל? מה לאוכל שכן נהנה!\u0004","\u0003אלא כך שאלו: האוכל נותר מחמשה זבחים בהעלם אחת, מהו? חייב בכל אחת ואחת או אחת על כולן? אמרו לו: לא שמענו.\u0004","ועל כך \u0003אמר ר' יהושע: שמעתי באוכל מזבח אחד מחמשה תמחויין בהעלם אחת, שחייב על כל אחת ואחת משום מעילה, ורואה אני שהדברים קל וחומר: מה\u0004 האוכל \u0003מזבח אחד\u0004 למרות \u0003שאין\u0004 שם \u0003גופין מוחלקין\u0004 — \u0003חייב על כל אחת ואחת משום\u0004 שאכל ב\u0003תמחויין מוחלקין,\u0004 השוחט \u0003חמשה זבחים\u0004 ש\u0003גופין מוחלקין\u0004 הם — \u0003לא כל שכן\u0004 שיהא חייב על כל אחד ואחד?","שנינו במשנה: \u0003אמר ר' שמעון: לא כך שאלו, אלא באוכל מזבח אחד נותר מחמשה זבחים בהעלם אחת, מהו? חייב אחת על כולן או חייב על כל אחת ואחת? אמרו לו: לא שמענו;\u0004","\u0003ר' יהושע אומר: שמעתי באוכל מזבח אחד בחמשה תמחויין, שהוא חייב על כל אחת ואחת משום מעילה, ורואה אני שהדברים קל וחומר. אמר לו ר' עקיבא: אם הלכה נקבל\u0004 אם לדין יש תשובה","\u0003כו'.\u0004 ושואלים: האם \u0003קיבלה ר' יהושע להא תשובה\u0004 \u0005[לתשובה זו]\u0006 \u0003מר' עקיבא או לא?\u0004 ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003: אכל חמש חתיכות נותר מזבח אחד בהעלם אחת בחמשה תמחויין\u0004 — \u0003אינו מביא אלא חטאת אחת, ועל לא הודע שלהן,\u0004 כלומר, אם היה לו ספק אם היה זה נותר — \u0003אינו מביא אלא אשם תלוי אחת.\u0004","אכל נותר מזבח אחד \u0003מחמשה תמחויין,\u0004 אבל לא בהעלם אחד, אלא \u0003בחמש העלמות,\u0004 שאכל מתמחוי אחד ונודע לו חטאו, ושוב שכח ואכל מתמחוי אחר — \u0003מביא חטאת על כל אחת ואחת, ועל לא הודע שלהן\u0004 — \u0003מביא אשם תלוי על כל אחת ואחת.\u0004 אכל חמש חתיכות נותר \u0003מחמשה זבחים\u0004 שונים \u0003בהעלם אחת\u0004 — \u0003חייב\u0004 חטאת על כל אחת ואחת, שאכל מגופים חלוקים.","\u0003ר' יוסי בר' יהודה אומר: אפילו אכל חמש חתיכות\u0004 נותר \u0003מחמשה זבחים בהעלם אחת\u0004 — \u0003אינו מביא אלא חטאת אחת,\u0004 שאין גופים מחלקים באיסור אחד בהעלם אחד, \u0003ועל ספיקן\u0004 — \u0003אין מביא אלא אשם תלוי אחת. כללו של דבר: כל שחלוקין בחטאות\u0004 — \u0003חלוקין באשמות.\u0004 עד כאן בדין האוכל נותר.","אבל \u0003אכל חמש חתיכות בחמשה תמחויין מזבח אחד לפני זריקת דמים\u0004 על המזבח, קודם שהותר הבשר באכילה, \u0003אפילו\u0004 אכלן \u0003בהעלם אחת\u0004 — \u0003חייב על כל אחת ואחת משום מעילה.\u0004"],["ויש לדייק: \u0003ואילו על ספיקו\u0004 של דין זה העוסק במעילה, \u0003מביא אשם תלוי לא קתני\u0004 \u0005[אינו שונה].\u0006 ויש לשאול: \u0003מני הא\u0004 \u0005[כשיטת מי\u0006 ברייתא \u0005זו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' עקיבא\u0004 — \u0003ליתני נמי סיפא\u0004 \u0005[שישנה גם כן בסופה]:\u0006 \u0003ועל ספיקן מביא אשם תלוי, דהתנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006\u0003: ר' עקיבא מחייב\u0004 גם \u0003על ספק מעילה אשם תלוי!\u0004","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 שיטת \u0003ר' יהושע היא\u0004 הברייתא, שהוא סבור כחכמים החולקים על ר' עקיבא, \u0003וקתני\u0004 \u0005[ו\u0006הרי \u0005הוא שונה]\u0006 בה שהאוכל נותר מחמישה תמחויים \u0003בחמש העלמות\u0004 — \u0003מביא חמש חטאות,\u0004 ונדייק: דווקא אם אכל בחמש העלמות הדין כן, אבל אם היה זה בהעלם אחד, אפילו אכל מחמשה תמחויים (או זבחים) — מביא חטאת אחת, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי ר' יהושע \u0003קיבלה מיניה\u0004 \u0005[ממנו],\u0006 מר' עקיבא.","ודוחים: \u0003אלא אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מסיפא דקתני\u0004 \u0005[מסופה,\u0006 מהמשכה של הברייתא, \u0005שהוא שונה]:\u0006 \u0003מחמשה זבחים אפילו בהעלם אחת חייב על כל אחת ואחת\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לא קיבלה מיניה\u0004 \u0005[ממנו]\u0006 ר' יהושע!","\u0003ואלא מאי אית למימר\u0004 \u0005[מה יש\u0006 לך \u0005לומר]\u0006 ליישב את חלקי הברייתא לשיטת ר' יהושע — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דאיכא\u0004 \u0005[שיש]\u0006 \u0003תנא\u0004 הסבור ש\u0003קיבלה, ואיכא\u0004 \u0005[ויש]\u0006 \u0003תנא\u0004 הסבור ש\u0003לא קיבלה;\u0004 אם כן יש לפרש את הברייתא","\u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת ר' עקיבא היא, \u0003והאי תנא סבר לה כותיה בחדא ופליג עליה בחדא\u0004 \u0005[ותנא זה סבור כמוהו באחת וחלוק עליו באחת],\u0006 \u0003סבר לה כותיה\u0004 \u0005[סבור כמוהו]\u0006 \u0003בהעלמה,\u0004 שאם אכל מחמישה זבחים בהעלם אחד — חייב חטאת אחת, \u0003ופליג עליה\u0004 \u0005[וחלוק עליו]\u0006 \u0003ב\u0004ספק \u0003מעילות,\u0004 ולדעתו אין מביאים על ספק מעילה אשם תלוי.","על מה ששנינו במשנה שאם אכל מזבח אחד בחמישה תמחויים יתחייב חמש קרבנות של מעילה, שואלים: \u0003היכי דמי\u0004 \u0005[כיצד מדובר]\u0006 שיתחייב \u0003חמש מעילות? אמר שמואל,\u0004 צריך שיהיו אלו דברים שונים לחלוטין כדי שייקראו \"חמישה תמחויים\" \u0003כאותה ששנינו\u0004 לענין אחר: \u0003חמשה דברים ב\u0004קרבן \u0003עולה מצטרפין\u0004 לכזית, להתחייב משום הקרבה בחוץ: \u0003הבשר, והחלב, והיין\u0004 של נסכי העולה, \u0003והסלת\u0004 של מנחת הנסכים, \u0003והשמן\u0004 שבוללים בו את המנחה.","\u0003חזקיה אמר: כגון שאכל מחמשה אברים\u0004 שונים של בהמה אחת. \u0003ריש לקיש אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר \u0003באבר אחד, משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בכתף,\u0004 שיש בה חלקים שונים. \u0003ר' יצחק נפחא אמר: כגון שאכל\u0004 מן הבשר \u0003בחמשה מיני קדירה,\u0004 בחמישה אופנים של בישול (תוספות). \u0003ר' יוחנן אמר: כגון שאכל\u0004 את הבשר \u0003בחמשה טעמים,\u0004 עם תבלינים שונים.","\u0003אמר ר' עקיבא, שאלתי את ר' אליעזר בעושה מלאכות הרבה בשבתות הרבה,\u0004 וכל אותן מלאכות היו \u0003מעין\u0004 (תולדות של) \u0003מלאכה אחת,\u0004 ועשאן כולן \u0003בהעלם אחת, מהו?\u0004 האם \u0003חייב\u0004 חטאת \u0003אחת על כולן, או חייב על כל אחת ואחת?\u0004","\u0003אמר לו: חייב על כל אחת ואחת, מקל וחומר, ומה נדה שאין בה תוצאות הרבה וחטאות הרבה,\u0004 שאין בה אלא איסור אחד של ביאה — \u0003חייב על כל אחת ואחת\u0004 מן הביאות, למרות שנעשו בהעלם אחד. \u0003שבת שיש בה תוצאות\u0004 (עניינים) \u0003הרבה ומיתות הרבה,\u0004 שיש בה מלאכות רבות ותולדותיהם, שעל כל אחת מהן חייב מיתה (במזיד, וחטאת בשוגג) — \u0003אינו דין שיהא חייב על כל אחת ואחת\u0004 בפני עצמה?","\u0003אמרתי לו:\u0004 לא, \u0003אם אמרת בנדה שיש בה שתי אזהרות, שהוא מוזהר על הנדה ו\u0004גם \u0003הנדה מוזהרת עליו, תאמר בשבת שאין בה אלא אזהרה אחת?\u0004","\u0003אמר לי: הבא על הקטנות\u0004 בנידתן \u0003יוכיח, שאין בה אלא אזהרה אחת,\u0004 שרק הוא מוזהר, אבל הקטנה פטורה מן המצוות, \u0003ו\u0004מכל מקום \u0003חייב על כל אחת ואחת!\u0004","\u0003אמרתי לו: אם אמרת בקטנות, שאף על פי שאין בהן\u0004 שתי אזהרות \u0003עכשיו\u0004 — \u0003יש בהן לאחר זמן,\u0004 לכשיגדלו, \u0003תאמר בשבת שאין בה\u0004 שתי אזהרות, לא \u0003עכשיו ולא לאחר זמן?\u0004","\u0003אמר לי: הבא על הבהמה יוכיח,\u0004 שאין בה לעולם שתי אזהרות, וחייב על כל ביאה וביאה! \u0003אמרתי לו: הבהמה כשבת,\u0004 גם לגביה קיים ספק זה.","ושואלים: \u0003מאי קבעי מיניה\u0004 \u0005[מה\u0006 בדיוק \u0005שאל אותו]\u0006 ר' עקיבא את ר' אליעזר? \u0003אי\u0004 \u0005[אם]\u0006 לגבי \u0003שבתות, כגופין דמיין ואי לא בעי מיניה\u0004 \u0005[\u0006האם \u0005כגופים\u0006 שונים הן \u0005נחשבות או לא שאל אותו]\u0006 כלומר, האם העושה מלאכה אחת בשבתות הרבה בהעלם אחד נחשב כאילו בא על חמש נשים נדות בהעלם אחד — \u0003ניבעי\u0004 \u0005[שישאל]\u0006 בלשון זו: \u0003העושה מלאכה אחת בשבתות הרבה\u0004 בהעלם אחד מהו!","\u0003אלא\u0004 תאמר שלגבי \u0003ולדי מלאכות\u0004 של אב אחד, \u0003אי כאבות דמיין ואי לא בעי מיניה\u0004 \u0005[האם כאבות\u0006 הם \u0005נחשבים\u0006 לחייב חטאת על כל אחד \u0005או לא שאל אותו]\u0006 — \u0003ניבעי מיניה\u0004 \u0005[שישאל אותו]\u0006 בלשון זו: \u0003העושה מלאכות הרבה מעין מלאכה אחת בשבת\u0004 בהעלם אחד מהו!","\u0003אמר רבא: אמרי בי\u0004 \u0005[אומרים בבית\u0006 מדרשו של\u0005]\u0006 \u0003רב, תרתי בעא מיניה\u0004 \u0005[שתים שאל אותו]:\u0006 האם \u0003שבתות כגופין\u0004 נפרדים \u0003דמיין ואי לא בעא מיניה\u0004 \u0005[\u0006האם \u0005כגופים\u0006 שונים הן \u0005נחשבות או לא שאל אותו].\u0006 ועוד, האם \u0003ולדי מלאכות כמלאכות דמיין אי לא\u0004 \u0005[נחשבים או לא].\u0006 ועל שתיהן השיב לו, ששבתות כגופים נפרדים הם, ושוולדי מלאכות דינם כמלאכות.","ועוד שואלים: \u0003ו\u0004עושה מלאכה ב\u0003שבתות\u0004 הרבה בהעלם אחד, \u0003היכי מיבעי ליה\u0004 \u0005[כיצד\u0006 בדיוק \u0005נשאלה לו]?\u0006 האם במקרה של \u0003שגגת שבת וזדון מלאכות,\u0004 שידע שהמלאכה אסורה, אלא שבכל שבת סבר שאין זו שבת (ולא נודע לו בינתיים) \u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003ימים שבינתיים הויין\u0004 \u0005[הריהם\u0006 נחשבים\u0005]\u0006 \u0003ידיעה לחלק,\u0004 וחייב על כל שבת, כאילו עשה מלאכה בשני העלמות,","\u0003ו\u0004דווקא \u0003זדון שבת ושגגת מלאכות,\u0004 שלא ידע שמלאכה זו אסורה, וחזר ועשאה שבת אחר שבת \u0003הוא דבעי מיניה אי כגופין דמיין אי לא\u0004 \u0005[הוא ששאל אותו האם\u0006 השבתות שעשה בהן מלאכה זו \u0005כגופים\u0006 נפרדים הן \u0005נחשבות או לא].\u0006","\u0003או דלמא\u0004 \u0005[שמא]\u0006 להיפך, לענין \u0003זדון שבת ושגגת מלאכות\u0004 — \u0003פשיטא ליה דכגופין דמיין\u0004 \u0005[פשוט לו ש\u0006השבתות \u0005כגופים\u0006 נפרדים \u0005נחשבות],\u0006 \u0003ושגגת שבת וזדון מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו],\u0006 לגבי \u0003ימים שבינתים אי הויין\u0004 \u0005[האם הם]\u0006 נחשבים \u0003ידיעה לחלק\u0004 בין השבתות \u0003אי\u0004 \u0005[או]\u0006 \u0003לא?\u0004","\u0003אמר רבה:\u0004"],["\u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003שגגת שבת וזדון מלאכות פשיטא ליה\u0004 \u0005[פשוט\u0006 היה \u0005לו]\u0006 לר' עקיבא, ש\u0003ימים שבינתיים הויין\u0004 \u0005[הריהם]\u0006 נחשבים \u0003ידיעה לחלק\u0004 בין שגגת שבת זו לשגגת שבת אחרת, וחייב על כל שבת ושבת. \u0003וזדון שבת ושגגת מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו]\u0006 האם השבתות \u0003כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[\u0006הן \u0005נחשבות]\u0006 לגבי שגגת המלאכה, \u0003או לאו.\u0004","\u0003ופשיט ליה\u0004 \u0005[ופשט לו]\u0006 ר' אליעזר לענין \u0003זדון שבת ושגגת מלאכות\u0004 שהשבתות \u0003כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות],\u0006 \u0003ולא קביל מיניה\u0004 \u0005[ולא קיבל ממנו]\u0006 ר' עקיבא. וחזר \u0003ופשט ליה\u0004 \u0005[לו]\u0006 ר' אליעזר את שאלתו השניה, ש\u0003ולדי מלאכות כמלאכות דמיין\u0004 \u0005[נחשבים],\u0006 \u0003ולא קביל מיניה\u0004 \u0005[ולא קיבל ממנו].\u0006","\u0003אמר רבה: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]?\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003כלל גדול אמרו בשבת: כל השוכח עיקר שבת,\u0004 שאינו יודע כלל שיש איסור מלאכה בשבת, \u0003ועשה מלאכות הרבה בשבתות הרבה\u0004 — \u0003אינו חייב אלא\u0004 חטאת \u0003אחת,\u0004 שאין כאן אלא העלם אחד.","\u0003היודע עיקר\u0004 איסור מלאכה ב\u0003שבת, ועשה מלאכות הרבה בשבתות הרבה,\u0004 מפני שלא ידע שהיום שבת — \u0003חייב\u0004 חטאת \u0003על כל שבת ושבת,\u0004 שהימים שבינתיים נחשבים ידיעה לחלק. \u0003היודע שהוא שבת ועשה מלאכות הרבה,\u0004 שלא ידע שהן אסורות, ועשאן \u0003בשבתות הרבה\u0004 — \u0003חייב על כל אב מלאכה ומלאכה;\u0004","\u0003ואילו \"חייב על כל אב מלאכה של כל שבת ושבת\" לא קתני\u0004 \u0005[אינו שונה]\u0006 בהלכה זו, שאין רואים את השבתות שחטא בהן כגופים נפרדים.","ויש לשאול: \u0003מני הא\u0004 \u0005[\u0006כשיטת \u0005מי\u0006 משנה \u0005זו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שיטת \u0003ר' אליעזר, אימא סיפא\u0004 \u0005[אמור את סופה]:\u0006 \u0003העושה מלאכות הרבה\u0004 וכולן \u0003מעין מלאכה אחת,\u0004 כלומר, ולדות — \u0003אין חייב אלא אחת, ואי\u0004 \u0005[ואם]\u0006 לשיטת \u0003ר' אליעזר\u0004 — הרי \u0003חייב על כל ולדי מלאכות כמלאכות!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שמשנה זו שיטת ר' \u0003עקיבא היא, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003שגגת שבת וזדון מלאכות פשיטא ליה\u0004 \u0005[פשוט\u0006 היה \u0005לו]\u0006 ש\u0003ימים שבינתיים הויין\u0004 \u0005[נחשבים]\u0006 \u0003ידיעה לחלק\u0004 בין שבת לשבת, כפי ששנינו בה שהיודע עיקר שבת ועשה מלאכות הרבה בשבתות הרבה — חייב על כל אחת ואחת.","ולפי זה, לגבי \u0003זדון שבת ושגגת מלאכות הוא דבעי אי כגופין דמיין\u0004 \u0005[הוא ששאל\u0006 במשנתנו \u0005האם\u0006 השבתות שחטא בהן \u0005כגופים\u0006 נפרדים \u0005נחשבות],\u0006 \u0003ופשט ליה\u0004 \u0005[לו]\u0006 ר' אליעזר ש\u0003כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[\u0006הן \u0005נחשבות],\u0006 וחייב על כל אחת ואחת, וכן פשט לו ש\u0003ולדי מלאכות כמלאכות דמיין\u0004 \u0005[נחשבים],\u0006 \u0003ותרוייהו לא קביל מיניה\u0004 \u0005[ושניהם לא קיבל ממנו]\u0006 ר' עקיבא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 כיצד מוכח הדבר מן המשנה? \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003זדון שבת ושגגת מלאכות פשיטא ליה\u0004 \u0005[פשוט\u0006 היה \u0005לו]\u0006 \u0003לר' עקיבא\u0004 ש\u0003שבתות לאו כגופין דמיין\u0004 \u0005[לא כגופים\u0006 נפרדים הן \u0005נחשבות],\u0006 כפי שדייקנו מסוף משנה זו, שאינו חייב על אב מלאכה של כל שבת, \u0003ושגגת שבת וזדון מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו]\u0006 לגבי \u0003ימים שבינתיים מי הויין\u0004 \u0005[האם הם]\u0006 נחשבים \u0003ידיעה לחלק או לא.\u0004","\u0003ופשיט ליה\u0004 \u0005[ופשט לו]\u0006 ר' אליעזר ש\u0003ימים שבינתיים\u0004 נחשבים כידיעה \u0003לחלק, וקביל מיניה\u0004 \u0005[וקיבל ממנו]\u0006 ר' עקיבא, כפי ששנינו במשנה זו, שהיודע עיקר שבת ועשה מלאכות הרבה בשבתות הרבה חייב על כל שבת ושבת. ועוד \u0003פשט ליה\u0004 \u0005[לו]\u0006 כי \u0003ולדי מלאכות כמלאכות דמיין\u0004 \u0005[נחשבים],\u0006 \u0003ולא קביל מיניה\u0004 \u0005[ולא קיבל ממנו]!\u0006","\u0003רב חסדא אמר:\u0004 לענין \u0003זדון שבת ושגגת מלאכות\u0004 — \u0003אפילו ר' עקיבא סבירא ליה\u0004 \u0005[סבור]\u0006 ש\u0003כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות]\u0006 השבתות, \u0003וכי בעי מיניה\u0004 \u0005[וכאשר שאל אותו],\u0006 על \u0003שגגת שבת וזדון מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו],\u0006 לגבי \u0003ימים שבינתיים אי הויין\u0004 \u0005[האם הם\u0006 נחשבים\u0005]\u0006 \u0003ידיעה לחלק.\u0004","\u0003ופשט ליה\u0004 \u0005[ופשט לו]\u0006 ר' אליעזר כי \u0003ימים שבינתיים הויין\u0004 \u0005[הריהם]\u0006 \u0003ידיעה לחלק, וקביל מיניה\u0004 \u0005[וקיבל ממנו],\u0006 כפי ששנינו במשנה במסכת שבת, בענין היודע עיקר שבת ועשה מלאכות הרבה בשבתות הרבה, שחייב על כל שבת ושבת.","\u0003ו\u0004עוד \u0003פשט ליה\u0004 \u0005[לו]\u0006 ש\u0003ולדי מלאכות כמלאכות דמיין\u0004 \u0005[נחשבים],\u0006 \u0003ולא קביל מיניה\u0004 \u0005[ולא קיבל ממנו],\u0006 כפי ששנינו בסוף אותה משנה: העושה מלאכות הרבה מעין מלאכה אחת אינו חייב אלא אחת.","\u0003אמר רב חסדא: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 שלדעת ר' עקיבא שבתות נחשבות כגופים? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003הכותב שתי אותיות\u0004 בשבת \u0003בהעלם אחת\u0004 — \u0003חייב,\u0004 שכך הוא שיעור מלאכת כתיבה. כתב שתי אותיות \u0003בשתי העלמות,\u0004 שכתב אות בשגגה ונודע לו האיסור, וחזר ושכח וכתב אות נוספת לידה — \u0003רבן גמליאל מחייב,\u0004 כאילו עשאן בהעלם אחד, שידיעה על שגגת חצי שיעור אינה נחשבת ידיעה לחלק בין שגגה לשגגה, \u0003וחכמים פוטרין; ומודה רבן גמליאל, שאם כתב אות אחת בשבת זו ואות אחת בשבת אחרת\u0004 — \u0003פטור.\u0004","\u0003ותניא אחריתי\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הכותב שתי אותיות בשתי שבתות, אחד בשבת זו ואחד בשבת זו\u0004 — \u0003רבן גמליאל מחייב, וחכמים פוטרין.\u0004 ומסבירים: \u0003קא סלקא דעתך\u0004 \u0005[עולה על דעתך,\u0006 מניחים אנו\u0005],\u0006 ש\u0003רבן גמליאל כר' עקיבא סבירא ליה\u0004 \u0005[סבור הוא].\u0006","וכך אומר רב חסדא: \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 שלענין \u0003זדון שבת ושגגת מלאכות אפילו ר' עקיבא אומר\u0004 ש\u0003שבתות כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנויה]\u0006 שרבן גמליאל מודה שאם כתב אות אחת בשבת זו ואות אחת בשבת אחרת \u0003פטור\u0004 — מדובר \u0003בזדון שבת ושגגת מלאכות,\u0004 שאף שהיה זה בהעלם אחד של מלאכה, שהרי אין ידיעה לחצי שיעור, מכל מקום \u0003שבתות כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות],\u0006 והואיל ובכל פעם עשה חצי מלאכה — פטור."],["\u0003והא דתניא\u0004 \u0005[וזו ששנויה]\u0006 ש\u0003חייב\u0004 על אות אחת בשבת זו ואות אחת בשבת אחרת — עוסקת בשגגת שבת וזדון מלאכות (דשבתות כגופין \u0003דמיין),\u0004 שאף על פי שלשיטתו ימים שבין השבתות נחשבים ידיעה לחלק — כאן אין הידיעה זו מחלקת בין שתי השבתות, מפני \u0003דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003אין ידיעה לחצי שיעור,\u0004 וכאילו לא נודע לו בינתיים. \u0003אלא ל\u0004שיטת \u0003רבא דאמר\u0004 \u0005[שאומר]\u0006 כי \u0003סבירא ליה\u0004 \u0005[סבור]\u0006 \u0003לר' עקיבא\u0004 ש\u0003שבבוות כגוף אחד הן\u0004 (ואנו מניחים שרבן גמליאל סבור כמותו),","","\u0003בשלמא הא דתניא\u0004 \u0005[נניח\u0006 לגבי ברייתא \u0005זו ששנויה]\u0006 שאם כתב שתי אותיות בשתי שבתות \u0003חייב,\u0004 שכן \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בין בזדון שבת ושגגת מלאכות\u0004 — \u0003מפני\u0004 שלדעתו \u0003שבתות כגוף אחד הן, ובין בשגגת שבת וזדון מלאכות,\u0004 שאף שהימים שבינתיים נחשבים ידיעה לחלק — כאן אינם מחלקים, מפני \u0003דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003אין ידיעה לחצי שיעור.\u0004","\u0003ואלא הדתניא\u0004 \u0005[זו ששנויה]\u0006 ש\u0003פטור, במאי מוקמת לה\u0004 \u0005[במה\u0006 הוא \u0005מעמיד אותה]?\u0006 \u0003לא בחדא ולא בחדא\u0004 \u0005[לא בזו ולא בזו],\u0006 לא בשגגת מלאכות — שהרי לשיטת ר' עקיבא, שרבן גמליאל סבור כמותו, השבתות כגוף אחד הן, ולא בשגגת שבת — שהרי לשיטת רבן גמליאל אין ידיעה לחצי שיעור, ואינה מחלקת!","ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא: רבן גמליאל סבירא ליה\u0004 \u0005[סבור]\u0006 \u0003כר' אליעזר,\u0004 ש\u0003אמר:\u0004 לענין שגגת מלאכות \u0003שבתות כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות],\u0006 ולכן אין האותיות שבשתי השבתות מצטרפות, ופטור.","ומקשים, \u0003והא מדקתני\u0004 \u0005[והרי ממה שהוא שונה]\u0006 בברייתא זו: \u0003ומודה רבן גמליאל\u0004 לחכמים שאם כתב שתי אותיות בשתי שבתות שהוא פטור, \u0003מכלל\u0004 הדברים אתה למד \u0003דפליגי אאחרנייתא\u0004 \u0005[ש\u0006הוא וחכמים \u0005חולקים\u0006 בהלכה \u0005אחרת]\u0006 שבענין זה. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שרבן גמליאל כר' \u0003עקיבא סבירא ליה\u0004 \u0005[סבור הוא],\u0006 וכן אתה מניח שדעת חכמים היא דעת ר' עקיבא — \u0003היינו דפליגי\u0004 \u0005[זהו שהם חולקים]\u0006 בברייתא השניה \u0003בשגגת שבת וזדון מלאכות,\u0004 ש\u0003רבן גמליאל סבר\u0004 \u0005[סבור]:\u0006 למרות שימים שבינתיים נחשבים ידיעה לחלק — \u0003אין ידיעה לחצי שיעור,\u0004 ולכן חייב, \u0003ו\u0004מכל מקום \u0003מודה רבן גמליאל\u0004 לר' עקיבא \u0003בזדון שבת ושגגת מלאכות שהוא פטור, אלמא\u0004 \u0005[מכאן]\u0006 שלדעת ר' עקיבא \u0003שבתות כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות],\u0006 ולכן אין האותיות שבשתי השבתות מצטרפות. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003רבן גמליאל כר' אליעזר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 וממה שנאמר \"ומודה רבן גמליאל שפטור\", \u0003מכלל\u0004 הדברים אתה למד \u0003דפליגי\u0004 \u0005[שחלוקים]\u0006 הם בהלכה אחרת דומה לזו, יש לשאול: \u0003במאי\u0004 \u0005[במה]\u0006 הם חולקים, שרבן גמליאל מחייב ור' אליעזר פוטר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשגגת שבת וזדון מלאכות\u0004 — \u0003אפילו ר' אליעזר כרבן גמליאל סבירא ליה\u0004 \u0005[סבור]\u0006 ש\u0003אין ידיעה לחצי שיעור, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הכותב שתי אותיות בשתי שבתות, אות אחת בשבת זו ואות אחת בשבת זו\u0004 — \u0003ר' אליעזר מחייב!\u0004","","","\u0003ואלא\u0004 תאמר ש\"ומודה רבן גמליאל\" מתייחס להלכה אחרת שנחלקו בה, \u0003באחת על האריג,\u0004 ששיעור איסור אריגה הוא כשאורג שלושה חוטים, ואולם אם הוסיף אפילו חוט אחד על אריג קיים — רבן גמליאל מחייב ור' אליעזר פוטר. ועל כן נאמר בברייתא כי במקרה דומה לזה בכתיבה, שהוסיף אות לאות שנכתבה בשבת קודמת, מודה רבן גמליאל שהוא פטור — אין לומר כן, שהרי גם ר' אליעזר \u0003חיובי מחייב\u0004 בהלכה זו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005], ר'\u0006 \u0003אליעזר אומר: האורג שלשה חוטין בתחלה, ואחד על האריג\u0004 — \u0003חייב!\u0004","\u0003אמר רבא:\u0004 מה שנאמר \"ומודה רבן גמליאל\", כוונתו — \u0003מכלל דפליג בחדא דתניא\u0004 \u0005[ש\u0006הוא \u0005חולק בזו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003הוציא חצי גרוגרת\u0004 לרשות הרבים \u0003וחזר והוציא חצי גרוגרת, בהעלם אחת\u0004 — \u0003חייב, בשתי העלמות\u0004 — \u0003פטור. ר' יוסי אומר:\u0004 למרות שהיה זה \u0003בהעלם אחד,\u0004 אם היה זה \u0003ברשות אחד,\u0004 שהוציא לאותה רשות הרבים — \u0003חייב, בשתי רשויות\u0004 כלומר, לשתי רשויות רבים שמופרדות זו מזו — פטור; ש \u0003רבן גמליאל\u0004 סבור \u0003כתנא קמא\u0004 \u0005[הראשון],\u0006 שרשויות אינן מחלקות וחייב, \u0003ור' אליעזר\u0004 סבור כ\u0003ר' יוסי\u0004 שרשויות מחלקות. ועל כך נאמר כי אף שרבן גמליאל חולק על ר' אליעזר בענין רשויות, וסבור שאינן מחלקות, הריהו מודה לו ששבתות הן גופים מחולקים, ואם כתב שתי אותיות בשתי שבתות — פטור. ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לשיטת רב חסדא ממה ששנינו במשנתנו, \u0003אמר לו\u0004 ר' אליעזר לר' עקיבא: \u0003חייב על כל אחת ואחת מקל וחומר, ומה נדה שאין בה תוצאות הרבה\u0004 וחטאות הרבה חייב על כל אחת ואחת, שבת שיש בה תוצאות הרבה וחטאות הרבה — אינו דין שחייב על כל אחת ואחת.","","","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב חסדא דאמר\u0004 \u0005[שאומר]:\u0006 \u0003שגגת שבת וזדון מלאכות בעי מיניה\u0004 \u0005[שאל אותו],\u0006 ולענין \u0003ימים שבינתים מי הויין\u0004 \u0005[האם הם\u0006 נחשבים\u0005]\u0006 \u0003ידיעה לחלק\u0004 בין השבתות \u0003או לא\u0004 — \u0003היינו דקאמר ליה\u0004 \u0005[זהו שאומר לו]\u0006 ר' אליעזר: \u0003\"ומה נדה\"\u0004 בלשון יחיד, שכשם שבאשה חייב על כל ביאה בגלל הימים שבינתיים — כך בשבת נחשבים הימים שבינתיים ידיעה לחלק.","\u0003אלא לרבא דאמר\u0004 \u0005[שאומר]:\u0006 \u0003זדון שבת ושגגת מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו],\u0006 ולענין \u0003שבתות אי כגופין\u0004 נפרדים \u0003דמיין\u0004 \u0005[נחשבות]\u0006 \u0003ואי לא\u0004 \u0005[או לא]\u0006 — \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"נדות\",\u0004 בלשון רבים, שכשם שהבא על חמש נשים נדות, שהן גופים מחולקים — חייב על כל אחת ואחת, כך העושה מלאכה בשבתות הרבה בשגגת שבת — חייב על כל אחת ואחת, מפני שהן גופים מחולקים!","ומתרצים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רבא: תני\u0004 \u0005[שנה]\u0006 \u0003\"נדות\".\u0004 ומעירים, \u0003שמואל תני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 \u0003\"נדה\",\u0004 וכן \u0003רב אדא בר אהבה תני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 \u0003\"נדה\". רב נתן בר אושעיא אמר: תני\u0004 \u0005[שנה]\u0006 \u0003\"נדות\".\u0004","ושואלים, \u0003ולרב חסדא דאמר\u0004 \u0005[שאומר]:\u0006 \u0003שגגת שבת וזדון מלאכות הוא דבעי מיניה\u0004 \u0005[ששאל אותו],\u0006 ולענין \u0003ימים שבינתים מי הויין\u0004 \u0005[האם הם\u0006 נחשבים\u0005]\u0006 \u0003ידיעה לחלק\u0004 בין השבתות \u0003ואי לא\u0004 \u0005[או לא],\u0006 \u0003נדה מאי\u0004 \u0005[מה,\u0006 כיצד\u0005]\u0006 \u0003ימים שבינתים הויין\u0004 \u0005[הריהם\u0006 נחשבים\u0005]\u0006 \u0003ידיעה לחלק אית\u0004 \u0005[יש]\u0006 \u0003בה?\u0004","\u0003אמר רבא: כגון שבא עליה\u0004 בנדתה בשוגג \u0003וטבלה, וראתה\u0004 דם \u0003וחזר ובא עליה\u0004 בשוגג, \u0003וטבלה,\u0004 ושוב ראתה \u0003וחזר ובא עליה,\u0004 ש\u0003טבילות\u0004 שנטהרה בהן \u0003הויין\u0004 \u0005[הריהן]\u0006 \u0003כימים שבינתים.\u0004 ומביאים ראיה לצד השני, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בהמשך המשנה, שאמר לו ר' אליעזר: \u0003הבא על הקטנות יוכיח. בשלמא\u0004 \u0005[נניח]\u0006 \u0003לרבא, היינו דקתני\u0004 \u0005[זהו שהוא שונה]\u0006 \u0003\"קטנות\"\u0004 בלשון רבים, שכשם שחייב על קטנות בהעלם אחד משום שהן גופים מחולקים — כך חייב בשגגת שבת על כל שבת, משום שגופים מחולקים הן.","","\u0003אלא לרב חסדא,\u0004 ששאל אותו לגבי שגגת שבת, האם ימים שבינתיים נחשבים כידיעה לחלק, \u0003מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"קטנות\"?\u0004 ומשיבים: הכוונה היא ל\u0003קטנות דעלמא\u0004 \u0005[בכלל],\u0006 כאילו נאמר: הבאים על הקטנות יוכיחו.","ומעירים, \u0003מתניתין דלא כהדין תנא\u0004 \u0005[משנתנו שלא כ\u0006שיטתו של \u0005תנא זה]\u0006 היא שנויה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: לא כך שאלו ר' עקיבא לר' אלעזר,\u0004 כפי ששנינו במשנתנו, ששאל אותו על מלאכות שבת והשיב לו בקל וחומר מן הבא על הנדה, \u0003אלא כך שאלו,\u0004 להיפך: \u0003הבא\u0004 בשגגה \u0003על אשתו\u0004 כשהיתה \u0003נדה וחזר ובא על אשתו\u0004 זו כשהיתה \u0003נדה,\u0004 והיה זה \u0003בהעלם אחת, מהו? חייב אחת על כולן, או חייב על כל אחת ואחת?\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אליעזר: \u0003חייב על כל אחת ואחת מקל וחומר, ומה שבת שאין בה אלא אזהרה אחת, שהוא מוזהר על השבת והשבת אינה מוזהרת עליו\u0004 — \u0003חייב על כל אחת ואחת\u0004 מן השבתות, \u0003נדה שיש בה שתי אזהרות, שהוא מוזהר על הנדה ונדה מוזהרת עליו\u0004 — \u0003אינו דין שהוא חייב על כל אחת ואחת\u0004 מן הביאות? \u0003אמר ליה\u0004 ר' עקיבא: \u0003לא, אם אמרת בשבת\u0004 — \u0003שיש בה תוצאות הרבה\u0004 אבות ותולדות, שמביאות \u0003לחטאות הרבה, תאמר בנדה שאין בה תוצאות הרבה לחטאות הרבה,\u0004 אלא רק חטאת אחת יש בה, על הביאה!","\u0003אמרו לו\u0004 ר' אליעזר: \u0003הבא על הקטנות\u0004 בנידתן \u0003יוכיח, שאין בה\u0004 בקטנה הנדה \u0003תוצאות הרבה לחטאות הרבה, וחייב על כל אחת ואחת,\u0004 אם בא על חמש קטנות בנידתן בהעלם אחד! \u0003אמרו לו\u0004 ר' עקיבא: \u0003לא, אם אמרת בקטנות\u0004 שחייב על כל אחת \u0003שכן\u0004 הן \u0003גופין מוחלקין,\u0004 תאמר בבא חמש פעמים על אשתו נדה, שהיא גוף אחד? \u0003אמרו לו\u0004 ר' אליעזר: \u0003הבא על הבהמה\u0004 כמה פעמים בהעלם אחד \u0003יוכיח, שאין גופין מוחלקין וחייב על כל אחת ואחת! אמרו לו\u0004 ר' עקיבא: \u0003הבהמה כנדה,\u0004 ואף בה יש לומר שאינו חייב אלא חטאת אחת.","","","","\u0003ספק אכל חלב\u0004 בשגגה, וחייב על כך חטאת, \u0003ספק לא אכל, ואפילו אכל\u0004 בוודאי — \u0003ספק יש בו כשיעור וספק\u0004"],["\u0003אין בו\u0004 כשיעור;","וכן \u0003שומן וחלב לפניו, ואכל אחד מהן ואינו יודע איזה מהן אכל; אשתו ואחותו עמו בבית, שגג באחת מהן,\u0004 שבא על אחת מהן \u0003ואינו יודע באיזו מהן שגג; שבת ויום חול, ועשה מלאכה באחד מהן ואינו יודע באיזו מהן עשה\u0004 — \u0003מביא אשם תלוי.\u0004","ועוד בהגדרת החיוב של אשם תלוי: \u0003כשם שאם אכל חלב\u0004 וחזר \u0003ו\u0004אכל \u0003חלב בהעלם אחת,\u0004 שלא ידע על האיסור בינתיים — \u0003אינו חייב אלא חטאת אחת, כן על לא הודע שלהן,\u0004 שאכל חתיכה שסבור היה שהיא שומן, ולא נתעורר לו ספק, וחזר ואכל חתיכה נוספת, ורק לאחר כך נסתפק לגבי שתיהן שמא היו חלב — \u0003אינו מביא אלא אשם תלוי אחד.\u0004","\u0003אם היתה ידיעה בינתים,\u0004 בין שתי האכילות, \u0003כשם שהוא מביא חטאת על כל אחת ואחת,\u0004 אם נודע לו בין האכילות שאכל ודאי חלב, וחזר ואכל בשגגה, \u0003כך\u0004 אם לאחר שאכל חתיכה התעורר לו ספק שמא חלב אכל, וחזר ואכל, ושוב התעורר בלבו ספק שמא חלב אכל — \u0003מביא אשם תלוי על כל אחת ואחת.\u0004","\u0003כשם שאכל חלב ודם ופיגול ונותר בהעלם אחת\u0004 — \u0003חייב\u0004 חטאת \u0003על כל אחת ואחת, כך על לא הודע שלהן\u0004 אם נסתפק על כמה חתיכות שאכל, שמא אחת מהן היתה חלב, והאחרת דם וכו' — \u0003מביא אשם תלוי על כל אחת ואחת.\u0004","בענין ששנינו בתחילת המשנה: ספק אכל חלב ספק לא אכל — מביא אשם תלוי, \u0003איתמר\u0004 \u0005[נאמרה]\u0006 מחלוקת אמוראים, \u0003רב אסי אמר:\u0004 בספק על \u0003חתיכה אחת שנינו\u0004 שמביא אשם תלוי, שהיתה לפניו חתיכה שהיא \u0003ספק של חלב ספק של שומן. חייא בר רב אמר:\u0004 דווקא אם אכל \u0003חתיכה משתי חתיכות\u0004 שהיו לפניו, אחת של איסור ואחת של היתר, \u0003שנינו\u0004 שמביא אשם תלוי. אבל אם אכל חתיכה אחת, ספק חלב ספק שומן — פטור.","ומסבירים, \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 במה שנאמר: \"ואם נפש אחת תחטא אחת מכל מצות ה' אשר לא תעשינה ולא ידע...\" (ויקרא ה, יז). \u0003רב אסי סבר\u0004 \u0005[סבור]:\u0006 \u0003יש אם למסורת,\u0004 הולכים אנו אחר מסורת הכתיבה של התורה, והרי \u0003\"מצות\" כתיב\u0004 \u0005[נכתב],\u0006 בלשון יחיד;","\u0003וחייא בר רב אמר\u0004 \u0005[אומר]:\u0006 \u0003יש אם למקרא,\u0004 הולכים אנו אחר הקריאה, והרי \u0003\"מצוות\" קרינן\u0004 \u0005[קוראים אנו],\u0006 בלשון רבים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא לרב אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה \u0003חייא בר רב לרב אסי\u0004 ממה ששנינו בהמשך המשנה: \u0003חלב ושומן לפניו ואכל אחת מהן; מאי לאו מדסיפא\u0004 \u0005[האם לא מ\u0006תוך \u0005שבסוף]\u0006 מדובר ב\u0003שתי חתיכות, רישא נמי\u0004 \u0005[בתחילה גם כן],\u0006 כששנינו: ספק אכל חלב — הכוונה היא ל\u0003שתי חתיכות?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב\u0004 לרב הונא וחייא בנו של רב: \u0003לא תיזלא בתר איפכא\u0004 \u0005[אל תלכו אחר ההיפך],\u0006 אל תקשו מדבר שניתן להופכו לצד האחר, שהרי \u0003יכול\u0004 רב אסי \u0003לשנויי לכו\u0004 \u0005[לתרץ לכם]:\u0006 \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר \u0003בשתי חתיכות, רישא\u0004 \u0005[בתחילה]\u0006 מדובר \u0003בחתיכה אחת.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 היה מתרץ, מדוע לשנות את ההלכה השניה? והרי \u0003יש לומר\u0004 בקל וחומר: אם ב\u0003חתיכה אחת מחייב,\u0004 ב\u0003שתי חתיכות צריכא למימר\u0004 \u0005[צריך לומר]\u0006 שחייב? ומשיבים: התנא שונה הלכות בדרך של \u0003זו ואין צריך למימר\u0004 \u0005[לומר]\u0006 \u0003זו.\u0004","ושואלים, \u0003ולחייא בר רב דאמר\u0004 \u0005[שאומר]:\u0006 \u0003מדסיפא\u0004 \u0005[מ\u0006תוך \u0005שבסוף]\u0006 מדובר \u0003בשתי חתיכות, רישא נמי\u0004 \u0005[בתחילה גם כן]\u0006 מדובר \u0003בשתי חתיכות, מיתנא תרתי\u0004 \u0005[לשנות פעמיים]\u0006 את אותה הלכה \u0003למה לי?\u0004 ומשיבים: התנא \u0003פרושי קא מפרש\u0004 \u0005[לפרש הוא שמפרש]\u0006 את דבריו הראשונים: \u0003ספק אכל ספק לא אכל חלב\u0004 — \u0003מביא אשם תלוי, כיצד? כגון שהיה\u0004 שתי חתיכות של \u0003חלב ושומן לפניו,\u0004 ואכל אחת מהן.","כדרך שאמר חייא בר רב, שאין מביאים אשם תלוי אלא בשתי חתיכות, כך \u0003אמר רב יהודה אמר רב: היו לפניו שתי חתיכות, אחת של שומן ואחת של חלב, אכל אחת מהן ואינו יודע איזו מהן אכל\u0004 — \u0003חייב;\u0004 אבל היתה לפניו \u0003חתיכה אחת, ספק של חלב ספק של שומן ואכלה\u0004 — \u0003פטור.\u0004","\u0003אמר רבא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רב? דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בענין זה: \u0003\"ועשה אחת מכל מצו‍ת ה' בשגגה\"\u0004 (ראה ויקרא ה, יז) — אינו חייב \u0003עד שישגוג בשתים,\u0004 שכן אף ש\u0003\"מצות\" כתיב\u0004 \u0005[כתוב]\u0006 בלשון יחיד — \u0003\"מצוות\" קרינן\u0004 \u0005[קוראים אנו].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו, \u0003ר' אליעזר אומר:\u0004 חלבו של \u0003כוי,\u0004 שהוא ספק בהמה שחלבה אסור, ספק חיה שחלבה מותר — \u0003חייבין עליו אשם תלוי,\u0004 למרות שמדובר בחתיכה אחת!","\u0003אמר לו\u0004 רבא: \u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003יש אם למסורת,\u0004 מסורת הכתיבה היא העיקרית, והרי \u0003\"מצות\" כתיב\u0004 \u0005[כתוב],\u0006 בלשון יחיד.","\u0003איתיביה\u0004 \u0005[\u0006עוד \u0005הקשה לו]\u0006 אביי ממה ששנינו: מי שמת בעלה בלא זרע, ונתייבמה לאחיו, וילדה בן, והוא \u0003ספק בן תשעה\u0004 חדשים \u0003לראשון\u0004 (לבעלה) \u0003או בן שבעה לאחרון\u0004 (ליבם) — \u0003יוציא\u0004 אותה היבם, שמא היתה מעוברת מאחיו המת, והריהי אסורה עליו כאשת אח שיש לו בנים. \u0003ו\u0004אולם \u0003הולד כשר,\u0004","\u0003וחייב\u0004 היבם (והאשה) \u0003באשם תלוי.\u0004 והרי כאן הספק הוא באשה אחת, ולא באחת משתיים! תירץ רבא: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא,\u0004 והרי הוא סבור שיש אם למסורת.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו במשנה במסכת נדה: המשמש עם אשתו, ובדקו עצמם בסדינים המיועדים לכך, \u0003נמצא\u0004 דם \u0003על שלו\u0004 — \u0003טמאין\u0004 שניהם, היא משום נדה, והוא משום הבא על הנדה, \u0003וחייבין בקרבן\u0004 חטאת, שבא בשוגג על הנדה.","נמצא \u0003על שלה אתיום\u0004 (תיכף) לתשמיש — \u0003טמאין וחייבין בקרבן, נמצא על שלה לאחר זמן\u0004 — \u0003טמאין מספק,\u0004 שמא נטמאה רק לאחר מכן, \u0003ופטורין מן הקרבן; ותני עלה\u0004 \u0005[ושנה עליה]\u0006 בברייתא: אף שפטורים מן החטאת, \u0003חייב משום אשם תלוי,\u0004 למרות שמדובר באשה אחת! השיב לו רבא: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא.\u0004","כמו שאמר רב יהודה בשם רב, כך \u0003אמר ר' חייא אמר רב: היו לפניו שתי חתיכות, אחת של חלב ואחת של שומן, ואכל אחת מהן ואינו יודע איזה מהן אכל\u0004 — \u0003חייב\u0004 אשם תלוי; אבל אכל \u0003חתיכה\u0004 אחת, \u0003ספק של שומן ספק של חלב ואכלה\u0004 — \u0003פטור.\u0004","\u0003אמר ר' זירא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רב? קסבר\u0004 \u0005[סבור הוא]:\u0006 רק מה שניתן לברר את איסורו מביא עליו אשם תלוי. וכשאכל אחת מ\u0003שתי חתיכות\u0004 — \u0003אפשר לברר איסורו,\u0004 לפי החתיכה שנותרה, אם היא חלב או שומן. אבל \u0003חתיכה אחת אי אפשר לברר איסורו,\u0004 שהרי כבר אכלה.","ושואלים \u0003מאי איכא בין טעמא\u0004 \u0005[מה\u0006 הבדל \u0005יש בין טעמו]\u0006 של \u0003רבא,\u0004 שלמדים חיוב אשם תלוי בשתי חתיכות דווקא, ממה שנאמר \"מצוות\" בלשון רבים, \u0003לטעמא\u0004 \u0005[לטעמו]\u0006 של \u0003ר' זירא,\u0004 מפני שבשתי חתיכות אפשר לברר איסורו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 אם היו לפניו שתי חתיכות, אחת של חלב ואחת של שומן, אחת מהן יש בה \u0003כזית ו\u0004אחת מהן יש בה \u0003מחצה\u0004 של כזית, ואכל מאחת מהן כזית,","\u0003לרבא\u0004 — \u0003ליכא\u0004 \u0005[אין כאן]\u0006 \u0003\"מצוות\",\u0004 שחתיכה שהיא פחות מכזית אינה נחשבת, \u0003ופטור,\u0004 ואילו \u0003לר' זירא\u0004 הרי גם אם נותר רק חצי כזית — \u0003אפשר לברר איסורו,\u0004 וחייב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' ירמיה לר' זירא,\u0004 ממה ששנינו, \u0003ר' אליעזר אומר: כוי, חייבין על חלבו אשם תלוי,\u0004 והרי אי אפשר לברר האם הוא אסור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא, \u0003ר' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 \u0003לברר איסורו\u0004 כדי לחייב אשם תלוי."],["עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' ירמיה לר' זירא, ממה ששנינו: מי ששמעה שמת בעלה וייבמה אחיו, וילדה ולד, \u0003ספק בן תשעה לראשון\u0004 לבעלה שמת, \u0003או בן שבעה לאחרון\u0004 ליבם — \u0003יוציא,\u0004 יגרשנה היבם, \u0003והולד כשר, וחייב באשם תלוי.\u0004 והרי במקרה זה אי אפשר לברר את האיסור! השיב לו: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא,\u0004 שמביא אשם תלוי גם כשאי אפשר לברר את האיסור.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: אם לאחר ששימש עם אשתו \u0003נמצא\u0004 דם \u0003על\u0004 הבגד \u0003שלה,\u0004 שבדקה בו את עצמה, אם היה זה \u0003אתיום\u0004 (תיכף), סמוך לתשמיש — \u0003טמאין\u0004 שניהם, \u0003וחייבין בקרבן\u0004 חטאת, שבא בשוגג על הנדה. \u0003נמצא על שלה לאחר זמן\u0004 — \u0003טמאין מספק ופטורין מן הקרבן. ותני עלה\u0004 \u0005[ושנויה\u0006 בברייתא \u0005עליה]:\u0006 \u0003וחייבין באשם תלוי,\u0004 למרות שאי אפשר לברר את האיסור! השיב לו: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 גם היא שיטת \u0003ר' אליעזר היא.\u0004","ובדומה לרב יהודה בשם רב, ולר' זירא בשם רב, כך גם \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: היו לפניו שתי חתיכות, אחת של חלב ואחת של שומן, ואכל אחת מהן ואינו יודע איזו מהן אכל\u0004 — \u0003חייב\u0004 אשם תלוי. אבל היתה לפניו \u0003חתיכה\u0004 אחת, \u0003ספק של חלב ספק של שומן ואכלה\u0004 — \u0003פטור.\u0004","\u0003אמר רב נחמן: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003רב? קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003שתי חתיכות\u0004 — \u0003איקבע איסורא\u0004 \u0005[נקבע האיסור]\u0006 מתחילה, שאחת מן החתיכות שלפניו היתה איסור ודאי, ושמא אותה אכל, אבל ב\u0003חתיכה אחת לא קבעה איסורא\u0004 \u0005[לא נקבע איסור],\u0006 שמא אין כאן איסור כלל.","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש\u0006 הבדל\u0005]\u0006 \u0003בין\u0004 הטעם שנתן רב נחמן, שבשתי חתיכות \u0003איקבע איסורא\u0004 \u0005[נקבע איסור],\u0006 \u0003ל\u0004טעם שנתן ר' זירא, \u0003ש\u0004בחתיכה אחת \u0003אי אפשר לברר איסוריה\u0004 \u0005[איסורו],\u0006 לבין הסברו של רבא, שהדבר נלמד מלשון הכתוב \"מצוות\", בלשון רבים?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006\u0003 כגון שהיו לפניו שתי חתיכות, אחת של חלב ואחת של שומן, ובא גוי ואכל את הראשונה, ובא ישראל\u0004 אחריו \u0003ואכל את השניה, לרבא\u0004 — \u0003ליכא\u0004 \u0005[אין כאן]\u0006 \u0003\"מצוות\",\u0004 כי אין שתי חתיכות \u0003בעידנא דאכל\u0004 \u0005[בזמן שאוכל]\u0006 \u0003ישראל,\u0004 אלא רק חתיכה אחת, ופטור מאשם תלוי. וכן \u0003ל\u0004שיטת \u0003ר' זירא\u0004 — \u0003אי אפשר לברר איסוריה\u0004 \u0005[איסורו],\u0006 שכבר נאכלה החתיכה השניה, וגם לשיטתו פטור. אבל \u0003ל\u0004שיטת \u0003רב נחמן\u0004 — \u0003איקבע איסורא\u0004 \u0005[נקבע האיסור]\u0006 מתחילה, שהיתה שם חתיכת חלב, ולכן חייב.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו, ר' \u0003אליעזר אומר: כוי,\u0004 שספק אם הוא חיה שחלבה מותר, או בהמה שחלבה אסור, וחייבים על שגגתו חטאת — \u0003חייבין על חלבו אשם תלוי,\u0004 למרות שלא נקבע האיסור, שמתחילה אין בו איסור ודאי! השיב לו רב נחמן: \u0003ר' אליעזר לא בעי קביעותא לאיסורא\u0004 \u0005[אינו מצריך קביעות לאיסור]\u0006 כדי לחייב אשם תלוי.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא ממה ששנינו: אשה שמת בעלה בלא בנים ונתייבמה, וילדה ולד, \u0003ספק בן תשעה לראשון\u0004 לבעל, \u0003או בן שבעה לאחרון\u0004 ליבם — \u0003יוציא והולד כשר, וחייבין באשם תלוי,\u0004 והרי לא נקבע שם איסור מתחילה! השיב לו רב נחמן: \u0003הא מני\u0004 \u0005[זו\u0006 גם כן כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' אליעזר היא,\u0004 שאינו מצריך איסור קבוע כדי לחייב אשם תלוי.","עוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו במשנה: המשמש עם אשתו, \u0003נמצא\u0004 דם \u0003על\u0004 הבגד \u0003שלו\u0004 — \u0003טמאין וחייבין בקרבן, נמצא על שלה אתיום\u0004 (מיד) — \u0003טמאין וחייבין בקרבן,\u0004 אבל \u0003נמצא על שלה לאחר זמן\u0004 — \u0003טמאים מספק ופטורין מן הקרבן; ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]:\u0006 \u0003וחייבין באשם תלוי,\u0004 למרות שלא נקבע איסור!","\u0003אישתיק\u0004 \u0005[שתק]\u0006 רב נחמן. \u0003לבתר דנפק\u0004 \u0005[לאחר שיצא\u0006 מבית המדרש\u0005], אמר: מאי טעמא לא אמרי ליה דהא מני\u0006 \u0005[מה טעם לא אמרתי לו ש\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת ר' מאיר היא, \u0003דלא בעי קביעותא לאיסורא\u0004 \u0005[שאינו מצריך קביעות לאיסור]\u0006 כדי לחייב אשם תלוי,","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: השוחט\u0006 בשוגג \u0003אשם תלוי בחוץ\u0004 מחוץ למקדש — ר' \u0003מאיר מחייב\u0004 אשם תלוי, משום שחיטת קדשים בחוץ, ולא חטאת, שמא יתברר שלא חטא מתחילה, ואשם זה חולין הוא, \u0003וחכמים פוטרין,\u0004 שהרי מתחילה ספק הוא, ולא נקבע איסורו. ומכאן שלדעת ר' מאיר אין צורך בקביעת איסור מתחילה.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 היה אומר לו רב נחמן שמשנה זו לענין נדה, שיטת ר' מאיר היא? \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 ששיטת \u0003ר' אליעזר היא!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה\u0006 היה \u0005משמיע לנו],\u0006 שר' \u0003מאיר בשיטת ר' אליעזר קאי\u0004 \u0005[עומד],\u0006 הולך באותה שיטה.","\u0003אמר רבה בר אבוה אמר רב:\u0004 היתה \u0003חתיכה\u0004 אחת לפניו, \u0003ספק של חלב ספק של שומן, ואכלה\u0004 — \u0003באנו למחלוקת ר' אליעזר וחכמים,\u0004 לדעת חכמים — פטור (שלפעמים צריך שיהיו שם שתי חתיכות), ולדעת ר' אליעזר חייב.","ושואלים: לדעת ר' \u0003אליעזר מאי איריא כי אכלה\u0004 \u0005[מה שייך\u0006 מדוע מדובר דווקא \u0005כאשר אכלה]\u0006 כלומר, כאשר בא לידי ספק? \u0003אפילו לא אכלה נמי\u0004 \u0005[גם כן]\u0006 יכול להביא אשם תלוי, \u0003דהתנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006\u0003, ר' אליעזר אומר: מתנדב אדם אשם תלוי בכל יום!\u0004","\u0003אמר רב אשי:\u0004 כוונת רב היא לשיטת ר' \u0003אליעזר אליבא\u0004 \u0005[על פי]\u0006 שיטתו של \u0003בבא בן בוטא,\u0004 שאין מביאים אשם תלוי אלא אם בא לידי ספק, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 שבבא בן בוטא היה מביא אשם תלוי בכל יום, חוץ מן היום שלאחר יום הכיפורים, שרצה להביא גם באותו יום, \u0003אלא\u0004 שהיו \u0003אומרים לו\u0004 חכמים: \u0003המתן עד שתכנס לבית ספק,\u0004 שהרי יום הכיפורים עצמו מכפר על חייבי אשם תלוי, וכן היה נוהג.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003היו לפניו שתי חתיכות, אחת של שומן ואחת של חלב, בא ישראל ואכל את הראשונה, בא גוי ואכל את השניה\u0004 — אותו ישראל שאכל את הראשונה \u0003חייב\u0004 באשם תלוי, \u0003וכן\u0004 אם אכל את השניה \u0003כלב, וכן עורב.\u0004 אולם אם \u0003בא גוי ואכל את הראשונה,\u0004 ואחריו \u0003בא ישראל ואכל את השניה\u0004 — הרי הוא \u0003פטור,\u0004 מפני שלא היתה לפניו אלא חתיכה אחת. \u0003ורבי מחייב,\u0004 שלשיטתו אין צורך בשתי חתיכות.","אם \u0003אכל את הראשונה בשוגג,\u0004 ונודע לו שיש בה ספק, \u0003ו\u0004אכל את \u0003השניה במזיד,\u0004 שידע שהוא ספק ואכלה — \u0003חייב\u0004 אשם תלוי על הראשונה, שכשאכל בשגגה היו לפניו שתי חתיכות. אבל אם אכל את \u0003הראשונה במזיד, והשניה בשוגג\u0004 — \u0003פטור,\u0004 שבשעה שאכל בשגגה היתה לפניו רק חתיכה אחת, \u0003ורבי מחייב.\u0004 אם \u0003אכל שתיהן במזיד\u0004 — \u0003פטור מכלום,\u0004 שהרי המזיד אינו מביא קרבן.","אכלו שני אנשים את \u0003שתיהן בשוגג\u0004 — \u0003שניהן חייבין\u0004 אשם תלוי. והשני \u0003לא מן הדין\u0004 הוא חייב, שהרי בשעה ששגג היתה שם רק חתיכה אחת, \u0003אלא שאם אתה אומר פטור,\u0004 ומשמע מכאן שהוא זה שאכל את ההיתר — הרי \u0003קבעת את הראשונה בחטאת.\u0004","ומעתה נברר: \u0003ומנו\u0004 \u0005[ו\u0006שיטת \u0005מי היא],\u0006 שאין השני צריך להביא מן הדין? \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003רבי\u0004 היא — \u0003מן הדין ומן הדין הוא,\u0004 שהרי לשיטתו גם בחתיכה אחת מביא אשם תלוי! \u0003אי רבנן\u0004 \u0005[אם\u0006 שיטת \u0005חכמים],\u0006 שמביא אשם תלוי רק אם היו לפניו שתי חתיכות, וכי \u0003משום\u0004 הטעם ש\u0003לא נקבע\u0004 את ה\u0003ראשון ב\u0004חיוב \u0003חטאת, נימא ליה\u0004 \u0005[נאמר לו]\u0006 \u0003לשני: אייתי\u0004 \u0005[הבא]\u0006 \u0003חולין לעזרה?\u0004 שהרי אינו צריך להביא אשם תלוי! \u0003אמר רב אשי:\u0004"],["\u0003ר' אליעזר היא,\u0004 שאמר: \u0003מתנדב אדם אשם תלוי בכל יום. הילכך אמרינן ליה\u0004 \u0005[משום כך אומרים אנו לו]\u0006 לשני, \u0003אייתי\u0004 \u0005[הבא]\u0006\u0003 אשם תלוי ואתני\u0004 \u0005[והתנה]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אכל ראשון שומן,\u0004 ונמצא שהוא, השני, \u0003אכל חלב\u0004 — \u0003ליהוי\u0004 \u0005[שיהא זה]\u0006 \u0003כפרה, ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שהראשון אכל את החלב והוא אכל שומן — \u0003ליהוי\u0004 \u0005[שיהיה]\u0006 \u0003נדבה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אכל ספק חלב\u0004 בשגגה \u0003ונודע לו\u0004 שאכל ספק חלב, ושוב אכל \u0003ספק חלב ונודע לו\u0004 — \u0003רבי אומר, אומר אני: כשם שמביא חטאת על כל אחת ואחת,\u0004 אם היה מתברר שוודאי חלב אכל — \u0003כך מביא אשם תלוי על כל אחת ואחת\u0004 מחתיכות הספק שנודע לו שאכל.","\u0003ר' יוסי בר' יהודה ור' אלעזר ור' שמעון אומרים: אין מביא אלא אשם תלוי אחד, שנאמר:\u0004 \"והביא איל תמים... וכפר עליו הכהן \u0003על שגגתו אשר שגג\"\u0004 (ויקרא ה, יח), וכפל הלשון בא ללמד — \u0003אפילו על שגגות הרבה אינו חייב אלא אחת.\u0004","\u0003אמר ר' זירא, כאן שנה רבי,\u0004 כלומר, ממה ששנינו: אכל ספק חלב ונודע לו... כשם שמביא חטאת על כל אחת ואחת, יש ללמוד ש\u0003ידיעות ספק מחלקות לחטאות,\u0004 שלמרות שלא נודע לו בוודאות שחטא בין אכילה לאכילה, אלא ספק היה בידו, אם מתברר לו לבסוף שאכן חטא — מביא חטאת על כל שגגה ושגגה.","\u0003רבא אמר: אין ידיעות ספק מחלקות לחטאות,\u0004 אלא רק ידיעה ודאית. \u0003אלא הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003כשם שאם היתה לו ידיעה ודאי,\u0004 שנודע לו חטאו בין אכילה לאכילה — \u0003מביא חטאת על כל אחת ואחת, כך אם היתה לו ידיעת ספק,\u0004 שנודע לו שחטא בספק — \u0003מביא אשם תלוי על כל אחת ואחת.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ואת לא תסברא\u0004 \u0005[וכי אתה אינך סבור]\u0006 שידיעות \u0003ספק מחלקות לחטאות? דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003ידיעות ספק אין מחלקות לחטאות, וחטאת אחת מביא\u0004 על הכל, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מביא אשם תלוי על כל אחת ואחת?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003כללו של דבר: כל שחלוקין בחטאות\u0004 — \u0003חלוקין באשמות!\u0004 אלא מכאן אתה מסיק כי כשם שידיעות הספק מחלקות לאשמות — כך הן מחלקות לחטאות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר חנן לאביי, ולדידך דאמרת\u0004 \u0005[ולשיטתך שאתה אומר]\u0006 ומסיק כי \u0003ידיעות ספק,\u0004 מתוך שהן מחלקות לענין אשם תלוי הריהן \u0003מחלקות\u0004 גם \u0003לחטאות, אלא מעתה, אכל\u0004 בהעלם אחד \u0003כזית חלב לפני יום הכיפורים וכזית חלב אחר יום הכיפורים,\u0004 שיש ביניהם חילוק לענין אשם תלוי, שהואיל \u0003ויום הכפורים במקום אשם תלוי קאי\u0004 \u0005[עומד],\u0006 שמי שהיה בידו ספק עבירה ועבר עליו יום הכיפורים — פטור מלהביא אשם תלוי, אם כן, על מה שאכל קודם יום הכיפורים — כיפר יום הכיפורים, ועל מה שאכל לאחריו — מביא אשם תלוי, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שאם נודע לו שוודאי חלב אכל ש\u0003מביא שתי חטאות,\u0004 על מה שאכל קודם יום הכיפורים ועל מה שאכל אחריו?","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003בהעלם אחת אכלינון\u0004 \u0005[אכל אותם]!\u0006 אלא בהכרח, לא כל מה שמחלק לענין אשמות מחלק לענין חטאות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 שיום \u0003הכיפורים מכפר על\u0004 ספק עבירה \u0003דלא מתידע ליה\u0004 \u0005[שלא נודע לו],\u0006 שאתה מניח שהוא מחלק לענין אשם תלוי? \u0003דילמא והוא דמתידע ליה\u0004 \u0005[שמא\u0006 מכפר רק על ספק \u0005שנודע לו],\u0006 שקודם יום הכיפורים נודע לו שאכל ספק חלב! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אין אתה יכול לומר כן, שהרי יום הכיפורים מכפר על \u0003הודע ולא הודע תנן\u0004 \u0005[שנינו],\u0006 ופירושו: בין אם נודע לו ספקו, ובין אם לא נודע לו ספקו! ואם כן הקושיה על הוכחתו של אביי בעינה עומדת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר חנן לאביי:\u0004 לשיטתך שידיעות ספק מחלקות לחטאות מתוך שהן מחלקות לאשמות, \u0003מה אילו אכל\u0004 בהעלם אחד \u0003כזית חלב שחרית ביום הכיפורים וכזית חלב במנחה ביום הכפורים,\u0004 הואיל ויום הכיפורים במקום אשם תלוי עומד, וכאילו נודע לו ספיקו באמצע, \u0003הכי נמי דמיחייב\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שמחוייב]\u0006 \u0003שתי חטאות?\u0004 והלא בהעלם אחד אכל אותם! אלא מכאן שלא כל שמחלק לאשמות מחלק לחטאות, וגם לא ידיעת ספק.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בדחיה: \u0003ומאן לימא לן\u0004 \u0005[ומי יאמר לנו]\u0006 שיום \u0003הכפורים כל שעתא\u0004 \u0005[שעה\u0006 ושעה שבו\u0005] מכפר,\u0006 שאתה מחלק בו בין אכילה לאכילה? \u0003דילמא כוליה יומא מאורתא\u0004 \u0005[שמא כל היום\u0006 כולו מכפר, \u0005מן הערב]\u0006 ועד סופו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר בר חנה: תרדא\u0004 \u0005[שוטה],\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 משנה\u0005]\u0006 מפורשת: \u0003הרי שבא לידו ספק עבירה ביום הכפורים, אפילו\u0004 היה זה \u0003עם חשיכה\u0004 — \u0003פטור, שכל היום מכפר,\u0004 כלומר, כל שעה ושעה שבו מכפרת!","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אידי בר אבין\u0004 על שיטת ר' זירא, שידיעות ספק מחלקות לחטאות, ממה ששנינו במשנה: מי ש\u0003אכל ושתה\u0004 ביום הכפורים \u0003בהעלם אחת\u0004 — \u0003אינו חייב אלא חטאת אחת\u0004 על האכילה ועל השתייה, שאיסור אחד הוא. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בין אכילה לשתייה אי אפשר דלא הוה\u0004 \u0005[שלא היתה]\u0006 \u0003שהות ביום דמתיידע ליה וכפר ליה\u0004 \u0005[שיכול היה להיוודע לו ולכפר לו]\u0006 אילו היתה לו ידיעת ספק, שהרי \u0003יום הכפורים במקום אשם תלוי קאי\u0004 \u0005[עומד],\u0006 \u0003וקתני\u0004 \u0005[ו\u0006הרי \u0005הוא שונה]:\u0006 \u0003אינו חייב אלא חטאת אחת.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שידיעות \u0003ספק מחלקות לחטאות, ליחייב\u0004 \u0005[שיתחייב]\u0006 \u0003שתי חטאות!\u0004 בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' זירא,\u0004 שידיעות ספק מחלקות לחטאות — הרי זה לשיטת \u0003רבי,\u0004 ואילו \u0003הא רבנן\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 שיטת \u0005חכמים]\u0006 \u0003היא,\u0004 ר' יוסי בר' יהודה וחבריו, הסבורים לעיל כי ידיעת ספק אינה מחלקת גם לענין אשם תלוי.","ומקשים: \u0003והא מדסיפא\u0004 \u0005[והרי מ\u0006כיון \u0005שסופה]\u0006 של אותה משנה שיטת \u0003רבי היא, דקתני\u0004 \u0005[שהוא שונה\u0006 שם\u0005]:\u0006 \u0003שתה\u0004 ביום הכיפורים \u0003ציר\u0004 של דגים, \u0003או מורייס\u0004 (רוטב העשוי מדגים מלוחים), שטעמם מלוח מאד — \u0003פטור,\u0004 שאינם עשויים לשתיה, אלא לטיבול, ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם שתה \u0003חומץ\u0004 — \u0003חייב,\u0004","\u0003ומני\u0004 \u0005[ו\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003רבי היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חומץ אין משיב את הנפש,\u0004 ולכן אין חייבים על שתייתו ביום הכיפורים, \u0003רבי אומר, אומר אני: חומץ משיב את הנפש. ומדסיפא\u0004 \u0005[ומ\u0006תוך \u0005שבסופה]\u0006 שיטת \u0003רבי, רישא נמי\u0004 \u0005[ראשה גם כן]\u0006 שיטת \u0003רבי!\u0004 בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003סיפא\u0004 \u0005[סופה]\u0006 שיטת \u0003רבי, רישא רבנן\u0004 \u0005[ראשה\u0006 כשיטת \u0005חכמים].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא\u0004 לשיטת ר' זירא, שידיעת ספק מחלקת, ממה ששנינו לענין מעילה: \u0003אכל היום\u0004 משל הקדש בשגגה, וחזר ו\u0003אכל למחר,\u0004 או \u0003נהנה היום\u0004 משל הקדש (בדבר שאינו בר אכילה) ושוב \u0003נהנה למחר,\u0004 וכן \u0003אכל היום\u0004 ו\u0003נהנה למחר,\u0004 או \u0003נהנה היום\u0004 ו\u0003אכל למחר, ואפילו\u0004 נעשה הדבר \u0003מכאן ועד שלש שנים, מנין שהן מצטרפין זה עם זה\u0004 לשווה פרוטה, לחייבו בקרבן מעילה?","\u0003תלמוד לומר: \"תמעל מעל\"\u0004 (ויקרא ה, טו) — \u0003ריבה. ו\u0004אם ידיעת ספק מחלקת, \u0003אמאי\u0004 \u0005[מדוע]\u0006 הם מצטרפים? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיפר עליה\u0004 \u0005[עליו]\u0006 \u0003יום הכפורים,\u0004 שהיה בתוך שלוש השנים הללו, שהרי דינו של יום הכיפורים כאשם תלוי!","ובתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מכפר יום הכפורים\u0004 הרי זה \u0003על\u0004 דבר שהוא \u0003איסורא\u0004 \u0005[איסור]\u0006 בלבד, \u0003על ממונא\u0004 \u0005[ממון]\u0006 יום הכפורים \u0003לא מכפר,\u0004 והרי המעילה היא גם חיוב ממון.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מכפר יום הכפורים\u0004 הרי זה \u0003על כוליה שיעורא\u0004 \u0005[שיעור\u0006 שלם\u0005], על פלגא דשיעורא\u0006 \u0005[חצי שיעור]\u0006 \u0003לא מכפר.\u0004 ושבים לברייתא ששנינו בה: אכל ספק חלב ונודע לו, ושוב אכל ספק חלב ונודע לו, כשם שמביא חטאת על כל אחת ואחת — כך מביא אשם תלוי על כל אחת ואחת. \u0003ו\u0004כפי שאמר ר' זירא לעיל, \u0003כן\u0004","\u0003אמר ריש לקיש, כאן שנה רבי: ידיעות ספק מחלקות לחטאות. רבי יוחנן אמר: אין ידיעות ספק מחלקות לחטאות,\u0004","\u0003אלא הכי קתני\u0004 \u0005[כך הוא שונה]:\u0006 \u0003כשם שאם היתה לו ידיעה ודאי\u0004 ביניהן, שאכל חלב בשגגה — \u0003מביא\u0004 חטאת \u0003על כל אחת ואחת, כך אם היתה לו ידיעת ספק\u0004 — \u0003מביא אשם תלוי על כל אחת ואחת.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח] ל\u0006שיטת \u0003רבי יוחנן, היינו\u0004 \u0005[זהו]\u0006 \u0003דקא תלי\u0004 \u0005[שהוא תולה]\u0006 \u0003לאשם בחטאת,\u0004 שכשם שידיעה ודאית מחלקת בחטאת, כך ידיעת ספק מחלקת באשם. \u0003אלא ל\u0004דברי \u0003ריש לקיש, חטאת באשם מיבעיא ליה\u0004 \u0005[היה צריך לו\u0006 לתלות\u0005],\u0006 שכשם שידיעת ספק מחלקת לחיוב אשם תלוי — כך היא מחלקת לענין חיוב חטאת! ואומרים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי ר' \u0003יוחנן\u0004 על דברי ר' \u0003יוחנן, ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ריש לקיש\u0004 על דברי \u0003ריש לקיש. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 היו \u0003שני שבילין\u0004 בדרכו למקדש, \u0003אחד\u0004 מהם היה \u0003טמא,\u0004 שקבור שם מת, \u0003ואחד טהור,\u0004 ואינו יודע איזה מהם טמא ואיזה טהור, \u0003והלך בראשון ולא נכנס\u0004 למקדש, ואחר כך הלך \u0003בשני ונכנס\u0004 למקדש בשגגה — הרי זה \u0003חייב\u0004 קרבן חטאת, משום שבכל אופן בוודאי נטמא.","אם \u0003הלך בראשון ונכנס\u0004 — \u0003פטור,\u0004 הלך גם \u0003בשני ונכנס\u0004 — \u0003חייב,\u0004 שהרי בוודאי נטמא. \u0003הלך בראשון ונכנס, והזה,\u0004 שהיזו עליו ממי פרה אדומה ביום השלישי כדי להיטהר מטומאת המת, \u0003ושנה,\u0004 שהיזו עליו גם ביום השביעי, \u0003וטבל, והלך ב\u0004שביל השני \u0003ונכנס\u0004 שוב למקדש — הרי זה \u0003חייב.\u0004"],["\u0003ר' שמעון\u0004 היה \u0003פוטר בזו\u0004 במקרה האחרון, משום שבשתי הפעמים שנכנס למקדש לא נשכחה ממנו ידיעה ודאית שהוא טמא, שהרי נטהר באמצע. \u0003ר' שמעון בן יהודה פוטר בכולן משום\u0004 (משמו של) \u0003ר' שמעון.\u0004","ושואלים: \u0003ואפילו בקמייתא\u0004 \u0005[בראשונה]\u0006 הוא פוטר, כשהלך בשני השבילים ולא נטהר באמצע? והרי ודאי נטמא! \u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שהלך ב\u0004שביל ה\u0003ראשון,\u0004 ולא נטהר, \u0003ובשעת הילוכו בשני שכח שהלך בראשון,\u0004 ונמצא שלמרות שבוודאי נטמא, מכל מקום כשנכנס למקדש נעלמה ממנו רק מקצת ידיעה של הטומאה, \u0003ובהא פליגי\u0004 \u0005[ובזה הם חלוקים],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון\u0006 לדעת ר' שמעון \u0005סבור]:\u0006 \u0003מקצת ידיעה\u0004 שהוא טמא — \u0003כידיעה דמיא\u0004 \u0005[נחשבת],\u0006 שאם נשכחה ממנו ונכנס למקדש — חייב. \u0003ור' שמעון,\u0004 כפי שאמר ר' שמעון בן יהודה בשמו, \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003מקצת ידיעה לאו\u0004 \u0005[לא]\u0006 \u0003כידיעה דמיא\u0004 \u0005[נחשבת],\u0006 ופטור.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003הלך בראשון ונכנס, והיזה וטבל, והלך בשני ונכנס\u0004 — \u0003חייב.\u0004 ומקשים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003חייב? הא לא הוי ליה\u0004 \u0005[הרי\u0006 בשתי הפעמים \u0005לא היתה לו]\u0006 \u0003ידיעה\u0004 שהוא טמא, שנעלמה ממנו כשנכנס!","\u0003אמר ריש לקיש: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 שיטת \u0005מי היא]?\u0006 שיטת \u0003רבי ישמעאל היא, דלא בעי\u0004 \u0005[שאינו צריך]\u0006 \u0003ידיעה\u0004 שהוא טמא \u0003בתחלה\u0004 כדי להתחייב קרבן על כניסה למקדש בטומאה בשגגה, ודי שייוודע לו בסוף. \u0003ר' יוחנן אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים],\u0006 המצריכים ידיעה בתחילה, \u0003כאן עשו\u0004 חכמים דינו של \u0003ספק ידיעה כידיעה\u0004 גמורה.","\u0003סלקא דעתך\u0004 \u0005[עולה על דעתך,\u0006 מניחים אנו\u0005]\u0006 שכוונת ר' יוחנן לומר ש\u0003כאן עשו\u0004 ספק ידיעה כידיעה — \u0003והוא הדין לכל התורה כולה,\u0004 ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי ר' \u0003יוחנן\u0004 על דברי ר' \u0003יוחנן,\u0004 שאמר לעיל לענין אכילת חלב כי ידיעת ספק אין שמה ידיעה, ואינה מחלקת לחטאות לדעת הכל.","וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ריש לקיש\u0004 על דברי \u0003ריש לקיש,\u0004 שאמר לענין אכילת חלב, שלדעת רבי ידיעות ספק מחלקות לחטאות.","ומוסיפים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי ר' \u0003יוחנן\u0004 על דברי ר' \u0003יוחנן לא קשיא\u0004 \u0005[אינו קשה],\u0006 שאפשר לדייק מדבריו כך: \u0003כאן עשו\u0004 ספק ידיעה כידיעה, \u0003אבל בכל התורה כולה\u0004 — \u0003לא,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 החילוק בדברים? \u0003הכא\u0004 \u0005[כאן]\u0006 לגבי \u0003טומאה כתיב\u0004 \u0005[נאמר]: \"\u0006\u0003ונעלם ממנו והוא טמא\"\u0004 (ויקרא ה, ב), לומר שכל שנעלם ממנו שהוא טמא, ואפילו \u0003ידיעה דאית בה נמי\u0004 \u0005[שיש בה גם כן]\u0006 \u0003ספק\u0004 — \u0003חייב קרא\u0004 \u0005[הכתוב],\u0006 \u0003אבל בכל התורה כולה כתיב\u0004 \u0005[נאמר]: \"\u0006\u0003או הודע אליו חטאתו\"\u0004 (שם ד, כח), ומשם יש ללמוד: \u0003אי אית ליה\u0004 \u0005[אם יש לו]\u0006 \u0003ידיעה\u0004 ברורה מתחילה \u0003הוא דמחייב\u0004 \u0005[שהוא מתחייב],\u0006 ולא במקרה אחר.","\u0003אלא לריש לקיש קשיא\u0004 \u0005[קשה],\u0006 \u0003אדמוקים לה\u0004 \u0005[עד שהוא מעמיד אותה]\u0006 את הברייתא הזו, כשיטת \u0003ר' ישמעאל,\u0004 שאינו מצריך ידיעה בתחילה, \u0003לוקמה\u0004 \u0005[שיעמיד אותה]\u0006\u0003 כ\u0004שיטת \u0003רבי,\u0004 כפי שאמר לעיל: כאן שנה רבי ידיעות ספק מחלקות לחטאות! ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[דבר זה משמיע לנו]\u0006 בדבריו, שר' \u0003ישמעאל נמי לא בעי\u0004 \u0005[גם כן אינו צריך]\u0006 \u0003ידיעה בתחלה.\u0004","ומקשים: דבר זה אינו צריך לדיוק, \u0003הא מתניתין\u0004 \u0005[הרי משנה]\u0006 מפורשת \u0003היא! דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0005ר' ישמעאל\u0006 \u0003אומר:\u0004 מה שנאמר בענין טומאת מקדש וקדשיו \u0003\"ונעלם ממנו\" שתי פעמים\u0004 (ראה שם ה, ב—ג), בא \u0003לחייב\u0004 קרבן הן \u0003על העלם טומאה\u0004 שלא ידע שהוא טמא, \u0003ו\u0004הן \u0003על העלם מקדש,\u0004 כשלא ידע שנכנס למקדש. והרי למדו מכתוב זה שצריך שתהא לו ידיעה מתחילה, ומכאן שר' ישמעאל אינו סבור כן!","ומשיבים: מכל מקום \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 ריש לקיש לומר שכך סבור ר' ישמעאל, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003מקרא לית ליה\u0004 \u0005[מן המקרא אין לו\u0006 לר' ישמעאל\u0005]\u0006 מקור לכך, אבל \u0003מגמרא אית ליה\u0004 \u0005[ממסורת יש לו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ריש לקיש שלדעתו אין צורך בידיעה מתחילה.","היו \u0003חלב ונותר לפניו, ואכל אחד מהן\u0004 בשגגה \u0003ואינו יודע איזה מהן אכל,\u0004 ועל כל פנים אכל אכילה אסורה שחייבים עליה חטאת. וכן היו \u0003אשתו נדה ואחותו עמו בבית,\u0004 ושגג הוא \u0003באחת מהן\u0004 ובא עליה \u0003ואינו יודע באיזה מהן שגג,\u0004 או שהיו \u0003שבת ויום הכיפורים\u0004 סמוכים זה לזה, \u0003ועשה מלאכה בין השמשות ואינו יודע באיזה מהן עשה,\u0004 אם בשבת או ביום הכיפורים עשה — ר' \u0003אליעזר מחייב חטאת,\u0004 משום שבוודאי חטא, \u0003ור' יהושע פוטר,\u0004 שהרי אינו יודע במה חטא.","\u0003אמר ר' יוסי: לא נחלקו על העושה מלאכה בין השמשות שהוא פטור,\u0004 וגם ר' אליעזר סבור כן, מפני \u0003שאני אומר: מקצת\u0004 מלאכה \u0003עשה היום ומקצת\u0004 מלאכה \u0003עשה למחר,\u0004 ואין אדם מתחייב על מקצת מלאכה.","\u0003על מה נחלקו? על העושה מלאכה\u0004 גמורה \u0003בתוך היום ואינו יודע אם בשבת עשה אם ביום הכפורים עשה, או על העושה\u0004 מלאכה \u0003ואינו יודע מעין איזו מלאכה עשה,\u0004 כגון אם חרש או אם זרע, שר' אליעזר מחייב חטאת, ור' יהושע פוטר. \u0003אמר ר' יהודה: פוטרו היה ר' יהושע,\u0004 את מי שאינו יודע במה חטא, \u0003אף מאשם תלוי.\u0004","\u0003ר' שמעון ור' שמעון שזורי אומרים: לא נחלקו\u0004 ר' אליעזר ור' יהושע \u0003על דבר שהוא משם אחד, שהוא חייב,\u0004 וכגון שהיו לפניו שתי גפנים וליקט מאחת מהן בשבת בשגגה, ואינו יודע מאיזו מהן, שהרי הוא יודע שחטא ובאיזה דבר חטא, \u0003על מה נחלקו? על דבר שהוא משום שני שמות,\u0004 וכגון שהיו לפניו תאנה וגפן, וליקט מאחת מהן בשגגה, ואינו יודע מאיזו מהן ליקט, \u0003שר' אליעזר מחייב חטאת\u0004 במקרה זה, שהרי נודע לו שחטא, \u0003ור' יהושע פוטר,\u0004 שהרי לא נודע לו במה חטא.","\u0003אמר ר' יהודה: אפילו נתכוון ללקוט תאנים\u0004 בשגגה \u0003וליקט\u0004 במקום זה \u0003ענבים,\u0004 או נתכוון ללקט \u0003ענבים וליקט תאנים,\u0004 וכן אם נתכוון ללקט תאנים \u0003שחורות וליקט לבנות,\u0004 או נתכוון ללקט תאנים \u0003לבנות וליקט שחורות\u0004 — \u0003ר' אליעזר מחייב חטאת,\u0004 אם נעשה הדבר בשגגה, \u0003ור' יהושע פוטר.\u0004 והוסיף ר' יהודה: \u0003תמיהני אם פטר בה ר' יהושע,\u0004 כלומר, מדוע פטר ר' יהושע בכגון זה, שהרי גם לפי טענתו נתכוון לעשות מעשה שהוא אסור! ותמהים: \u0003אם כן,\u0004 שאינו פוטר, \u0003למה נאמר\u0004 בכתוב \"חטאתו \u0003אשר חטא בה\"\u0004 (ויקרא ד, כג), ללמד שצריך שיחטא במה שהתכוון אליו? ומשיבים: \u0003פרט למתעסק\u0004 בדבר אחר, שהוא מותר, ולא נתכוון כלל לעשות דבר אסור.","בענין ששנינו בתחילת המשנה, שמי שהיו לפניו חלב ונותר ואכל אחד מהם בשגגה ואינו יודע איזה מהם אכל, ר' אליעזר מחייב חטאת ור' יהושע פוטר, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר ר' אליעזר: מה נפשך\u0004 \u0005[רצונך]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003חלב אכל\u0004 — הרי הוא \u0003חייב\u0004 חטאת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003נותר אכל\u0004 — \u0003חייב!\u0004 וכן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אשתו נדה בעל\u0004 — \u0003חייב\u0004 חטאת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אחותו בעל\u0004 — \u0003חייב\u0004 חטאת! \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשבת עשה מלאכה\u0004 — \u0003חייב, אי\u0004 \u0005[אם]\u0006 \u0003ביום הכפורים עשה מלאכה\u0004 — \u0003חייב!\u0004","\u0003אמר לו ר' יהושע: הרי הוא אומר\u0004 בכתוב \"או הודע אליו חטאתו \u0003אשר חטא בה\"\u0004 (ויקרא ד, כג), לומר שאינו מביא חטאת \u0003עד שיודע לו במה\u0004 בדיוק \u0003חטא.\u0004 ושואלים: \u0003ור' אליעזר\u0004 שלדעתו אינו צריך לדעת במה חטא, \u0003האי\u0004 \u0005[זה]\u0006 הדיוק \"\u0003בה\" מאי עביד ליה\u0004 \u0005[מה עושה הוא בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך הוא לו]\u0006 ללמד: \u0003פרט למתעסק,\u0004 שאם עשה דבר שלא התכוון לעשותו הריהו פטור מחטאת."],["\u0003מתעסק דמאי\u0004 \u0005[של מה],\u0006 באיזה מתעסק מדובר? \u0003אי\u0004 \u0005[אם]\u0006 במתעסק בחלבים \u0003ועריות,\u0004 גם אם לא התכוון כלל לאכול חתיכה זו שאכל, או שלא נתכוון לבוא על אשה זו שבא עליה — הרי הוא \u0003חייב\u0004 חטאת, שאמר \u0003רב נחמן אמר שמואל: המתעסק בחלבים ועריות\u0004 — \u0003חייב, שכן נהנה!\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 היה זה \u0003מתעסק בשבת\u0004 — ודאי \u0003פטור מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006? \u0003מלאכת מחשבת אסרה\u0004 תורה, שחושב ומתכוון למלאכה שהוא עושה! ואם כן, איזה מתעסק הוצרך ר' אליעזר ללמוד מ\"אשר חטא בה\"?","ומשיבים: \u0003לרבא משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003כגון שנתכוון לחתוך\u0004 בשבת \u0003את\u0004 הדבר \u0003התלוש וחתך\u0004 בטעות \u0003את המחובר,\u0004 שאף שעשה פעולה שהתכוון לעשותה, לא עשה בדיוק לפי כוונתו; \u0003לאביי,\u0004 שמחייב במקרה זה, \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה],\u0006 כשנתכוון לעשות פעולה מותרת, \u0003כגון\u0004 ש\u0003נתכוון להגביה את התלוש ו\u0004בתוך כך \u0003חתך את המחובר.\u0004","\u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בענין זה: מי ש\u0003נתכוון להגביה את התלוש וחתך\u0004 בתוך כך \u0003את המחובר\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]? דהא לא איכוון\u0006 \u0005[שהרי לא התכוון]\u0006 \u0003לשום\u0004 (לשם) פעולת \u0003חתיכה.\u0004 אבל אם נתכוון \u0003לחתוך את התלוש וחתך את המחובר\u0004 — אביי אומר: חייב, \u0003דהא איכוון לשום\u0004 \u0005[שהרי התכוון לשם]\u0006 פעולת \u0003חתיכה. רבא אמר: פטור, דהא לא איכוון\u0004 \u0005[שהרי לא התכוון]\u0006 \u0003לחתיכה דאיסורא\u0004 \u0005[של איסור],\u0006 אלא התכוון לחתוך דבר שמותר לו לחתוך.","שנינו במשנה, \u0003ר' יוסי אומר: לא נחלקו\u0004 ר' אליעזר ור' יהושע על העושה מלאכה בין השמשות שבין שבת ויום הכיפורים, שגם ר' אליעזר פוטר, שמא מקצת מלאכה עשה ביום זה ומקצתה ביום האחר \u0003כו'. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן ר' יוסי: דקדקתם אחרי\u0004 והשבתם לי תשובה ניצחת.","ושואלים: \u0003מאי אמרי ליה דאמר להו\u0004 \u0005[מה אמרו לו\u0006 חכמים \u0005שאמר להם]\u0006 \u0003דקדקתם אחרי?\u0004 הרי במשנה לא נאמר דבר! ומשיבים: \u0003הכי אמרו ליה\u0004 \u0005[כך אמרו לו]:\u0006 אם \u0003הגביה\u0004 חפץ \u0003בין השמשות,\u0004 והוציאו מרשות לרשות, \u0003מהו?\u0004 שהרי פעולה זו אינה מתמשכת, שתוכל לומר שעשה מקצתה בשבת ומקצתה ביום הכיפורים. ואם כן ייתכן שנחלקו בעושה מלאכה בין השמשות! ועל כן \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דקדקתם אחרי,\u0004 והשבתם לי תשובה ניצחת.","ומקשים: \u0003ונימא להו\u0004 \u0005[ושיאמר להם]:\u0006 אף במקרה זה יש לומר: \u0003מקצת הגבהה היתה מהיום ומקצתה למחר!\u0004 ומשיבים: \u0003הכי נמי קאמר להו\u0004 \u0005[כך גם כן אמר להם],\u0006 זו באמת היתה כוונת דבריו: \u0003דקדקתם אחרי,\u0004 הקשיתם עלי \u0003ולא העליתם בידכם כלום.\u0004","ושואלים: ול\u0003ר' יוסי,\u0004 שמניח כי אם עשה מקצת מלאכה בשבת ומקצתה ביום הכיפורים פטור לדעת הכל, יש לתמוה: וכי על \u0003גמר מלאכה,\u0004 החלק שעשאו ביום השני \u0003ל\u0004דעת ר' \u0003אליעזר פטור? הא שמענא ליה דמחייב\u0004 \u0005[הרי שמענו אותו שהוא מחייב\u0006 בזה\u0005]! דתנן\u0006 \u0005[ששנינו\u0006 במשנה\u0005]\u0006\u0003, ר' אליעזר אומר: האורג שלשה חוטין בתחלה,\u0004 כלומר כשמתחיל את האריגה, וכן אם מוסיף \u0003ו\u0004אורג אפילו חוט \u0003אחד על האריג\u0004 הקיים — \u0003חייב,\u0004 למרות שעשה מקצת מלאכה!","\u0003אמר רב יוסף: ר' יוסי אליבא\u0004 \u0005[לפי שיטת]\u0006\u0003 ר' אליעזר הכי מתני\u0004 \u0005[כך הוא שונה]\u0006 באותה משנה, \u0003ר' אליעזר אומר: האורג שלשה חוטין בתחלה, ושנים על האריג\u0004 הקיים כבר — \u0003חייב,\u0004 שאינו חייב אלא אם כן הוסיף שיעור שלם של מלאכת אריגה.","בענין העושה אחת משתי עבירות ואינו יודע איזו מהן עשה, שר' אליעזר מחייב חטאת ור' יהושע פוטר, שנינו, \u0003אמר ר' יהודה: פוטרו היה ר' יהושע אף מאשם תלוי.\u0004 ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006\u0003, אמר ר' יהודה: פוטרו היה ר' יהושע אף מאשם תלוי, שנאמר\u0004 בו: \"נפש \u0003כי תחטא... ולא ידע\"\u0004 (ויקרא ה, יז) — דווקא מי שלא ידע אם חטא מביא אשם תלוי, \u0003פרט לזה שידע שחטא\u0004 אלא שאינו יודע במה חטא — שפטור. \u0003אמר לו ר' שמעון:\u0004 להיפך, דווקא מי שחטא ולא ידע במה חטא — \u0003זהו שמביא אשם תלוי, שנאמר\u0004 שם: \"נפש כי תחטא \u0003ועשה... ולא ידע\", ו\u0004הרי \u0003זה לא ידע במה עשה.\u0004","\u0003אבל\u0004 מי שאכל חתיכה, \u0003ספק אכל חלב ספק לא אכל,\u0004 שלא ידע אם חטא — \u0003צא ושאל עליו אם מביא אשם תלוי אם לאו\u0004 \u0005[לא].\u0006 ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 כיצד נפתרה לדעת ר' שמעון שאלה זו?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003חטא ולא ידע במה חטא, או ספק חטא ספק לא חטא\u0004 — \u0003מביא אשם תלוי. מאן שמענא ליה דאמר\u0004 \u0005[מי שמענו אותו שאומר]:\u0006 \u0003חטא ואין ידוע במאי\u0004 \u0005[במה]\u0006 \u0003חטא מביא אשם תלוי? ר' שמעון\u0004 הוא, כפי ששנינו בברייתא, \u0003וקא תני\u0004 \u0005[והוא שונה]:\u0006 \u0003ספק חטא ספק לא חטא\u0004 — \u0003מביא אשם תלוי, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003לר' שמעון: ספק חטא ספק לא חטא\u0004 — \u0003מביא אשם תלוי.\u0004","שנינו במשנה, ר' שמעון שזורי ור' שמעון אומר: לא נחלקו כו', \u0003אם כן, מה תלמוד לומר\u0004 \"או הודע אליו חטאתו \u0003אשר חטא בה\"\u0004 (שם ד, כג)? \u0003פרט למתעסק.\u0004","בענין זה מביאים, \u0003אמר רב נחמן אמר שמואל: מתעסק בחלבים ועריות,\u0004 כגון שאכל בלא שהתכוון לאכול מה שאכל, או שבא על אשה בלא שיתכוון לבוא עליה — \u0003חייב, שכן נהנה.\u0004 אבל \u0003מתעסק בשבת\u0004 וכגון שנתכוון ללקט תאנה וליקט תאנה אחרת — \u0003פטור,\u0004 כי \u0003מלאכת מחשבת אסרה תורה,\u0004 שחושב ומתכוון למה שהוא עושה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: והא\u0004 \u0005[והרי]\u0006 \u0003תינוקות,\u0004 שמל בשבת בטעות תינוק שלא הגיע יומו השמיני, \u0003דכי מתעסק דמי\u0004 \u0005[שכמו מתעסק הוא נחשב],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006\u0003: מי שהיו לו שני תינוקות\u0004 למול, \u0003אחד\u0004 היה צריך \u0003למול בשבת ואחד למול אחר השבת\u0004 (ביום ראשון), \u0003ושכח ומל את\u0004 זה \u0003של אחר השבת בשבת\u0004 — \u0003ר' אליעזר מחייב חטאת,\u0004 שלא ניתנה שבת להידחות אצלו, ונמצא שעשה בשוגג מלאכה האסורה בשבת, \u0003ור' יהושע פוטר.\u0004","והרי \u0003עד כאן לא\u0004 שמענו ש\u0003פטר ר' יהושע אלא משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 מי ש\u0003טעה בדבר מצוה,\u0004 שחשב שהוא עושה מצוה, \u0003ולא עשה מצוה\u0004 — \u0003פטור, אבל מתעסק בדבר דלאו\u0004 \u0005[שאינו]\u0006 \u0003מצוה,\u0004 כגון שנתכוון ללקוט תאנים שחורות וליקט לבנות — \u0003אפילו ר' יהושע מחייב!\u0004","\u0003אמר לו: הנח ל\u0004דין המל \u0003תינוקות,\u0004 שיש בו חומרה מיוחדת, \u0003הואיל ומקלקל בחבורה חייב\u0004 כלומר, מי שעושה חבורה בשבת חייב, למרות שמקלקל בשבת בדרך כלל פטור, לכן גם \u0003מתעסק בחבורה,\u0004 שלא נתכוון לעשות חבורה בתינוק זה אלא באחר — צריך להיות \u0003חייב\u0004 (אלא שהוא פטור משום שטעה בדבר מצוה).","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יהודה לשמואל,\u0004 שאמר כי מתעסק בשבת פטור, ממה ששנינו במשנתנו, ר' יהודה אומר: אפילו מתכוין ללקט תאנים וליקט ענבים, \u0003ענבים וליקט תאנים,\u0004 או התכוון ללקוט \u0003שחורות וליקט לבנות, לבנות וליקט שחורות\u0004 — \u0003ר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004","ויש לשאול: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003מתעסק הוא,\u0004 שלא עשה מה שהתכוון אליו, \u0003ור' יהושע נמי לא קא פטר\u0004 \u0005[גם כן אינו פוטר]\u0006 \u0003אלא\u0004 כשטעה \u0003מן מינא למינא\u0004 \u0005[בין מין למין],\u0006 בין תאנים לענבים, או בין תאנים שחורות ללבנות, \u0003אבל בחד מינא\u0004 \u0005[במין אחד],\u0006 כגון שנתכוון ללקט תאנה לבנה זו וליקט תאנה לבנה אחרת — \u0003אפילו\u0004 לדעת ר' \u0003יהושע מחייב\u0004 \u0005[מתחייב\u0006 חטאת\u0005]! אמר ליה\u0006","\u0005[לו]\u0006 שמואל לרב יהודה: \u0003שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003שבוק מתניתין ותא בתראי\u0004 \u0005[עזוב את המשנה ובוא אחרי],\u0006 כלומר, אין להבין משנה זו כפשוטה, אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שאבד מלקט מלבו,\u0004 כלומר, ששכח מה שרצה ללקט, ואחר כך הזדמן לו שליקט שלא בכוונה את שהתכוון אליו בתחילה, וכגון ש\u0003נתכוון ללקט ענבים, ושכח וסבור תאנים בעינא\u0004 \u0005[רוצה אני],\u0006 \u0003והלכה ידו על הענבים\u0004 ואותם ליקט, שר' \u0003אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003הרי נעשתה כוונתו,\u0004 שהרי מתחילה נתכוון ללקט ענבים ולכן חייב, \u0003ור' יהושע סבר\u0004 \u0005[סבור]:\u0006 \u0003הרי לא נעשתה כוונתו ומחשבתו\u0004 כלומר, אף על פי שנתכוון ללקט ענבים, ונעשתה כוונתו, מכל מקום באותה שעה לא חשב ללקוט תאנים, ואינו חייב חטאת אלא אם עשה דבר שהתכוון אליו וגם עכשיו הוא חושב עליו. אבל המתעסק, שעשה דבר שלא התכוון אליו מתחילה, וכגון שהתכוון ללקט תאנה אחת וליקט תאנה אחרת — פטור, לדעת הכל."],["\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא\u0004 על הסבר זה, ולפיו המתעסק פטור, ממה ששנינו מתחילה במשנה, ר' שמעון שזורי ור' שמעון אומרים: \u0003לא נחלקו על דבר שהוא משם אחד שהוא חייב, אלא על דבר שהוא משום שני שמות, שר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004","ויש לשאול: \u0003ור' יהודה מאי קאמר דפליגי\u0004 \u0005[מה הוא אומר שהם,\u0006 ר' אליעזר ור' יהושע, \u0005חולקים\u0006 בו\u0005]?\u0006 אם כפשוטו, \u0003בנתכוין ללקט ענבים ולקט תאנים, שחורות ולקט לבנות,\u0004 והלוא \u0003ענבים ותאנים,\u0004 וכן תאנים \u0003שחורות ולבנות, מאי ניהו\u0004 \u0005[מה הם]?\u0006 \u0003שני שמות\u0004 הם — \u0003היינו\u0004 \u0005[הרי זו]\u0006 שיטת ר' \u0003שמעון ור' שמעון שזורי,\u0004 ואם כן, \u0003ר' יהודה מאי אתא לאשמועינן\u0004 \u0005[מה בא להשמיע לנו]?\u0006","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 בענין \u0003מתעסק איכא בינייהו\u0004 \u0005[יש ביניהם הבדל],\u0006 שר' \u0003יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מתעסק\u0004 בשבת — \u0003חייב\u0004 גם לדעת ר' יהושע, ור' שמעון \u0003ור' שמעון שזורי סברי\u0004 \u0005[סבורים]:\u0006 \u0003מתעסק פטור?\u0004 והוא שלא כדברי שמואל, שאמר שמתעסק פטור לדעת הכל!","ודוחים: \u0003לא, מתעסק,\u0004 שעשה מעשה בדבר אחר ממה שנתכוון לו מתחילה — \u0003דברי הכל פטור,\u0004 וגם לשיטת ר' יהודה, \u0003והכא בהא קא מיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 שר' \u0003שמעון שזורי\u0004 (וכן ר' שמעון) \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003שכח מלקט מלבו\u0004 למה התכוון בתחילה, ועשה בו מעשה, אבל סבר שהוא עושה מעשה בדבר אחר. אם זה היה \u0003בשם אחד,\u0004 כגון שנתכוון מתחילה ללקט תאנה מסויימת, ושכח, וחשב שרצונו בתאנה אחרת, וליקט בטעות את הראשונה — \u0003דברי הכל חייב,\u0004 גם לדעת ר' אליעזר וגם לדעת ר' יהושע, הואיל ועשה מעשה במה שהתכוון אליו מתחילה.","\u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 הרי זה \u0003בשני שמות,\u0004 וכגון שנתכוון ללקט תאנים, ושכח וחשב שרצה ללקט ענבים, וליקט בטעות תאנים — בזה ר' אליעזר מחייב חטאת, שהרי לכן נתכוון מתחילה, ור' יהושע פוטר, מפני שאינו חוטא במין שהוא מתכוון אליו עכשיו. ואילו \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בשם אחד ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003בשני שמות\u0004 — \u0003פליגי\u0004 \u0005[חלוקים]\u0006 הם, ולדעת ר' יהושע, כל שלא עושה מעשה בדבר שמתכוון אליו עכשיו, גם אם נתכוון אליו מתחילה — פטור.","\u0003רבא אמר: ליקדם איכא בינייהו\u0004 \u0005[להקדים יש ביניהם]\u0006 כלומר, אם התכוון לעשות איסור בדבר אחד ואחר כך בדבר שני ולבסוף נתברר שעשה להיפך, האם הוא נחשב מתעסק ופטור. לדעת ר' שמעון ור' שמעון שזורי נחלקו אם הקדים ואיחר בשני שמות, כגון נתכוון ללקט ענבים ואחר כך תאנים, וליקט תאנים ואחר כך ענבים, ודווקא בזה ר' יהושע פוטר. אבל כשהקדים את המאוחר מאותו שם, כגון תאנה ותאנה — גם לדעת ר' יהושע חייב. ואילו לדעת ר' יהודה, גם אם הקדים את המאוחר מאותו שם, כגון תאנה לתאנה — פטור לדעת ר' יהושע, הואיל וכוונתו בשעת לקיטה היתה לתאנה אחרת.","ומעירים, \u0003והתניא\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היו לפניו שתי נרות דולקות ארוכות, ונתכוין לכבות את זו וכיבה\u0004 במקום זו \u0003את זו,\u0004 או שהיו לפניו שתי נרות כבויות, נתכוון \u0003להדליק את זו והדליק את זו\u0004 — הרי זה \u0003פטור,\u0004 לפי שמתעסק הוא, שלא חטא כלל בדבר שנתכוון אליו. היה נר אחד כבוי ונר אחד דולק, אם נתכוון \u0003להדליק\u0004 תחילה את הכבוי \u0003ו\u0004אחר כך \u0003לכבות\u0004 את הדולק, \u0003וכיבה והדליק בנשימה אחת,\u0004 וכגון שנשף בנר הדולק וכיבהו, ועל ידי נשיפתו אחזה האש בנר הכבוי — \u0003חייב.\u0004 אבל אם היה זה בשתי נשימות — פטור, שלא עשה כסדר שנתכוון אליו.","על מה שנאמר שאם כיבה והדליק בנשימה אחת חייב, תמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 גם כאן, הרי \u0003לא איתעבד מחשבתיה\u0004 \u0005[לא נעשתה מחשבתו],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003להדליק מעיקרא בעי\u0004 \u0005[מתחילה רצה]\u0006 \u0003ו\u0004רק \u0003לבסוף לכבות, וכי עבד\u0004 \u0005[וכאשר נעשה]\u0006 \u0003מעשה\u0004 בפועל — \u0003כיבה ובסוף הדליק הוא, ואימא\u0004 \u0005[ואמור]\u0006 שיהיה \u0003פטור,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דאקדומי נמי לא מקדים\u0004 \u0005[גם אם אמנם להקדים\u0006 את ההדלקה לכיבוי \u0005אינו מקדים],\u0006 מכל מקום \u0003אחורי נמי לא מאחר\u0004 \u0005[לאחר\u0006 את ההדלקה לכיבוי \u0005גם כן אינו מאחר],\u0006 ויש להחשיבו כמי שעושה מה שהתכוון לעשות, ואינו בכלל מתעסק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003החותה,\u0004 מהפך ב\u0003גחלים בשבת\u0004 בשוגג — \u0003חייב חטאת. ר' שמעון בן אלעזר אומר משום ר' אליעזר בר' צדוק: חייב שתים, מפני שהוא\u0004 גם \u0003מכבה\u0004 במעשה זה \u0003את העליונות\u0004 שנעשו תחתונות, מפני שהגחלים שהניח עליהן מכבידות עליהן, ואין להן אויר לבעירה, \u0003ומבעיר את התחתונות,\u0004 שהן עתה עליונות. ונברר: \u0003במאי עסקינן\u0004 \u0005[במה\u0006 בדיוק \u0005אנו עוסקים]?\u0006 \u0003אי דקא מיכוין\u0004 \u0005[אם\u0006 במקרה \u0005שהוא מתכוון]\u0006 \u0003לכבות\u0004 את העליונות \u0003ולהבעיר\u0004 את התחתונות — \u0003מאי טעמא דמאן דפטר\u0004 \u0005[מה טעמו של מי שפוטר]?\u0006 והרי לכך היתה כוונתו! \u0003אלא\u0004 תאמר שמדובר במקרה \u0003דלא קא מכוין\u0004 \u0005[שאינו מתכוון]\u0006 \u0003להבעיר\u0004 את התחתונות — \u0003מאי טעמא דמאן דמחייב תרתי\u0004 \u0005[מה טעמו של מי שמחייב שתים]?\u0006 הרי מתעסק הוא ואינו מתכוון לכך!","\u0003ר' אלעזר ור' חנינא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]\u0006 תירוץ לדבר: \u0003כגון שנתכוין\u0004 בחתיית הגחלים \u0003לכבות העליונות,\u0004 וכגון נפח שזקוק לפחמים, כלומר, לגחלים שכבו, לצורך עבודתו, והוא יודע בוודאות שיש בכך \u0003כדי להבעיר את התחתונות,\u0004 שאין לו צורך בהן, \u0003דתנא קמא קסבר\u0004 \u0005[שהתנא הראשון סבור]:\u0006 \u0003מקלקל בהבערה\u0004 בשבת — \u0003פטור,\u0004 לכן אינו חייב אלא חטאת אחת, על הכיבוי. \u0003ור' אליעזר בר' צדוק אמר\u0004 \u0005[אומר]:\u0006 מקלקל בהבערה \u0003חייב,\u0004 ולכן חייב שתיים. \u0003וכן אמר רבי יוחנן: בנפח שנו,\u0004 שנתכוון לכבות את הגחלים העליונות משום שרצה בהן לעבודתו, ואין לו צורך בגחלים התחתונות, ולכן התנא הראשון פוטר על הבערת התחתונות, משום שאינו אלא מקלקל. \u0003אמר ר' יוחנן: עד כאן,\u0004 עד שנתבאר ענין זה, שמדובר בנפח, \u0003לא נתגלתה טעמא של הלכה זו.\u0004","\u0003אמי בר אבין ורב חנניא בר אבין דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006"],["\u0003כגון שנתכוין\u0004 גם \u0003לכבות ו\u0004גם \u0003להבעיר, דתנא קמא סבר לה\u0004 \u0005[שהתנא הראשון סבור]\u0006\u0003 כ\u0004דעת ר' \u0003יוסי,\u0004 שאמר: \u0003הבערה,\u0004 שיצאה מכלל שאר מלאכות שבת, נאמר בה איסור מפורש בתורה: \"לא תבערו אש בכל מושבותיכם ביום השבת\" (שמות לה, ג), \u0003ללאו יצאת,\u0004 לומר שאינו חייב עליה סקילה או כרת, אלא רק משום לאו שעונשו מלקות, ואינו חייב על שגגתה חטאת, ולכן לדעתו חייב רק על הכיבוי. \u0003ור' אליעזר בר' צדוק סבר לה\u0004 \u0005[סבור] כ\u0006דעת ר' \u0003נתן,\u0004 שאמר: \u0003הבערה לחלק יצאת\u0004 כלומר, ללמד שעל כל מלאכה ומלאכה יש חיוב לעצמו, ולכן לדעתו חייב גם על ההבערה.","","\u0003רבא אמר: להקדים איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, כשנתכוון להדליק ואחר כך לכבות, והדליק וכיבה בחתייה אחת, לדעת התנא הראשון אינו חייב אלא חטאת אחת, וכדין מתעסק, שלא נתקיימה כוונתו, ואילו לדעת ר' אליעזר בר' צדוק אין משמעות לשינוי בסדר הדברים, וכל שנעשתה כוונתו חייב שתיים.","\u0003רב אשי אמר:\u0004 נחלקו \u0003כגון שנתכוין לכבות והובערו\u0004 הגחלים התחתונות \u0003מאיליהן\u0004 בלא שנתכוון לכך, \u0003ותנא קמא סבר לה\u0004 \u0005[והתנא הראשון סבור] כ\u0006דעת ר' \u0003שמעון,\u0004 שאמר: \u0003דבר שאין מתכוין פטור\u0004 עליו, ואילו ר' \u0003אליעזר בר' צדוק סבר לה\u0004 \u0005[סבור]\u0006 \u0003בר' יהודה,\u0004 ש\u0003אמר: דבר שאין מתכוין\u0004 — \u0003חייב.\u0004","בענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003החותה גחלים בשבת\u0004 כדי \u0003להתחמם בהם, והובערו\u0004 הגחלים \u0003מאיליהן\u0004 — \u0003תני חדא\u0004 \u0005[שנויה\u0006 בברייתא \u0005אחת]:\u0006 \u0003חייב, ותני אידך\u0004 \u0005[ושנויה אחרת]:\u0006 \u0003פטור.\u0004 ומסבירים, \u0003הדתניא\u0004 \u0005[זו ששנויה]:\u0006 \u0003חייב, קסבר\u0004 \u0005[סבור]:\u0006 העושה \u0003מלאכה שאינה צריכה לגופה,\u0004 שאינו צריך למלאכה עצמה, כגון זה שהוצרך להתחמם ולא להבערה — \u0003חייב עליה. והא דתנא\u0004 \u0005[וזה ששונה]:\u0006 \u0003פטור, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מלאכה שאינה צריכה לגופה פטור עליה.\u0004","\u0003אכל\u0004 כזית מ\u0003דם שחיטה\u0004 (דם שיצא בשחיטה), \u0003בבהמה בחיה ובעוף, בין טמאין בין טהורין,\u0004 וכן אכל \u0003דם נחירה,\u0004 שיצא כשהמית את הבהמה שלא בשחיטה, אלא בדקירה או באופן אחר, או \u0003דם עיקור,\u0004 שעקר את הסימנים (הקנה והוושט) וניתז הדם, וכן \u0003דם הקזה,\u0004 היוצא כשמקיזים דם מגוף הבהמה, \u0003שהנשמה יוצאה בו\u0004 (שעניינו יבואר בגמרא) — כל אחד מאלה \u0003חייבין עליו\u0004 כרת — אם אכלם במזיד, או חטאת — אם אכלם בשוגג.","","אבל \u0003דם הטחול,\u0004 או \u0003דם הלב,\u0004 וכן \u0003דם ביצים,\u0004 או \u0003דם חגבים,\u0004 או \u0003דם התמצית,\u0004 שמתמצה ושותת לאחר שיצאה נפשה של הבהמה — \u0003אין חייבין עליו\u0004 כרת, \u0003ר' יהודה מחייב בדם התמצית.\u0004 \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"\u0003כל דם לא תאכלו\"\u0004 (ויקרא ז, כו), \u0003שומע אני\u0004 מכאן כי \u0003אפילו דם\u0004 של \u0003מהלכי שתים\u0004 כלומר, בני אדם, או \u0003דם ביצים, דם חגבים, דם דגים, הכל בכלל\u0004 איסור דם? \u0003תלמוד לומר: \"לעוף ולבהמה\"\u0004 (שם),","","\u0003מה עוף ובהמה מיוחדין, שיש בהן\u0004 גם \u0003טומאה קלה\u0004 (טומאת אוכלים) \u0003ו\u0004גם \u0003טומאה חמורה,\u0004 שהם נעשים אב הטומאה, כגון נבילה (אם לא נשחטו כראוי), \u0003ויש בהן איסור והיתר, והן מין בשר\u0004 — \u0003אף כל שיש בהן טומאה קלה\u0004 וטומאה חמורה, ויש בהם איסור והיתר, והם מין בשר, הריהם בכלל זה;","\u0003אוציא דם מהלכי שתים\u0004 (בני אדם) — \u0003שיש בהן טומאה חמורה,\u0004 טומאת מת, אבל \u0003אין בהם טומאה קלה,\u0004 שאין לבשרם דין טומאת אוכלים."],["\u0003אוציא דם שרצים\u0004 — \u0003שאין בהם טומאה חמורה,\u0004 שאין השרצים מטמאים אדם לטמא בגדים שעליו, כמו נבלת הבהמה והעוף, \u0003אוציא דם ביצים\u0004 — משום \u0003שאין\u0004 הם \u0003מין בשר,\u0004 וכן אוציא \u0003דם דגים דם חגבים\u0004 — \u0003שכולו היתר,\u0004 כאשר יבואר להלן (עמוד ב). ועוד דנים במה שנאמר: \"כל דם לא תאכלו...","\u0003לעוף ולבהמה\"\u0004 (ויקרא ז, כו), מדוע הוצרכנו לשניהם כדי ללמוד במידת \"מעין הפרט\"? לפי שאם היה מוזכר רק עוף הייתי אומר כך: \u0003אי מה עוף\u0004 הוא דבר \u0003שאין בה כלאים,\u0004 כאשר יבואר להלן (עמוד ב), \u0003אף בהמה\u0004 — דווקא זו \u0003שאין בה כלאים\u0004 יהא דמה אסור, ולא כל בהמה! \u0003תלמוד לומר: \"ולבהמה\".\u0004","וכן אם היתה נזכרת רק בהמה הייתי אומר: \u0003אי מה בהמה שאינה ב\u0004מצות \u0003אם על הבנים\u0004 (שילוח הקן), \u0003אף עוף\u0004 שנאסר דמו הוא זה \u0003שאינו ב\u0004מצות \u0003אם על הבנים,\u0004 וכגון עוף טמא, אבל עוף טהור דמו מותר! לכן \u0003תלמוד לומר: \"לעוף ולבהמה\".\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש כתוב זה באופן אחר: \u0003\"כל דם\"\u0004 — הרי זה \u0003כלל, \"עוף ובהמה\"\u0004 — \u0003פרט,\u0004 הרי זה \u0003כלל ופרט,\u0004 ולפי כללי מדרש ההלכה \u0003אין בכלל אלא מה שבפרט, עוף ובהמה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","ומשיבים: מה שנאמר מיד אחר כך \u0003\"נפש אשר תאכל כל דם\u0004 ונכרתה\" (שם כז) \u0003חזר וכלל,\u0004 ונמצא שיש כאן \u0003כלל ופרט וכלל,\u0004 ובמקרה זה \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט,\u0004 וכפי ששנינו לעיל, כל שיש בו טומאה חמורה וטומאה קלה, ויש בו איסור והיתר, והוא מין בשר.","ומקשים: \u0003והא לא דמי כללא בתרא לכללא קמא\u0004 \u0005[והרי אינו דומה הכלל האחרון לכלל הראשון],\u0006 \u0003כללא קמא\u0004 \u0005[הכלל הראשון]\u0006 הוא \u0003לאו\u0004 \u0005[\u0006מצות \u0005לא תעשה]\u0006 \"כל דם לא תאכלו\", ואילו \u0003כללא בתרא\u0004 \u0005[הכלל האחרון]\u0006 הוא \u0003כרת!\u0004","ומשיבים: \u0003האי תנא דבי\u0004 \u0005[תנא זה הוא מבית\u0006 מדרשו\u0005]\u0006 של ר' \u0003ישמעאל,\u0004 שלשיטתו \u0003כללי ופרטי דרשינן מן הדין גוונא\u0004 \u0005[כללים ופרטים אנו דורשים כגון זה],\u0006 \u0003ואף על גב דלא דמי כללא בתרא לכללא קמא\u0004 \u0005[ואף על פי שלא דומה הכלל האחרון לכלל הראשון].\u0006","ומעתה מבררים את הברייתא לפרטיה. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כלל ופרט וכלל אי\u0004 \u0005[אין]\u0006 \u0003אתה דן אלא כעין הפרט, מה הפרט מפורש\u0004 — \u0003דבר שיש בו טומאה קלה וטומאה חמורה, ויש בה איסור והיתר ויש בהן מין בשר, אף כל דבר שיש בו טומאה קלה וטומאה חמורה וכו'.\u0004","ושואלים: \u0003\"אף כל\" דקתני\u0004 \u0005[שהוא שונה]\u0006 \u0003לאיתויי מאי\u0004 \u0005[להביא את מה]\u0006 הוא בא? והרי הוצאנו מכלל זה בני אדם, דגים וחגבים ושרצים!","\u0003אמר רב אדא בר אבין: לאתויי\u0004 \u0005[להביא]\u0006 את \u0003דמו של כוי,\u0004 בעל חיים שהוא ספק חיה ספק בהמה. ושואלים: \u0003מאי קסבר\u0004 \u0005[מה סבור הוא]\u0006 התנא? \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 שכוי \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא,\u0004 שלא ברור לנו מהו, האם חיה או בהמה, וכי איצטריך קרא למיסר ספיקא \u0005[הוצרך הכתוב לאסור\u0006 דבר שלנו הוא \u0005ספק]?\u0006 \u0003אלא\u0004 בהכרח \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שכוי \u0003בריה בפני עצמו הוא,\u0004 שאינו חיה ואינו בהמה, ולכן צריך כתוב לעצמו.","ואומרים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 שיש איסור בדמו של כוי, \u0003חלבו מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא אסור? ומשיבים: דבר זה למדים ממה שנאמר: \u0003מ\"כל חלב\"\u0004 (שם כג). ועוד שואלים: \u0003נבלתו מנלן\u0004 \u0005[מנין לנו]\u0006 שהיא אסורה? ומשיבים: \u0003מ\"כל נבלה\"\u0004 (דברים יד, כא).","ושואלים: \u0003גיד הנשה\u0004 של כוי \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שאסור? ומשיבים: \u0003בכף הירך תליה רחמנא\u0004 \u0005[תלה אותו הכתוב],\u0006 שנאמר \"אשר על כף הירך\" (בראשית לב, לג), \u0003והא אית ליה\u0004 \u0005[והרי יש לו]\u0006 \u0003כף הירך,\u0004 כלומר, הירך שלו מעוגלת כמין כף.","ועוד שואלים: \u0003טומאתו\u0004 כשהוא נעשה נבילה, \u0003ושחיטה,\u0004 ששחיטה מתירה אותו באכילה, \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003סברא\u0004 \u0005[סברה\u0006 היא\u0005], מדלכל מילי רבייה רחמנא\u0006 \u0005[מ\u0006כיון \u0005שלכל דבר ריבה אותו הכתוב]\u0006 \u0003כבהמה, טומאתו ושחיטתו נמי\u0004 \u0005[גם כן]\u0006 \u0003כבהמה.\u0004","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003אוציא דם מהלכי שתים\u0004 כלומר, בני אדם, \u0003שיש בהן טומאה חמורה\u0004 (טומאת מת) \u0003ואין בהן טומאה קלה,\u0004 טומאת אוכלים. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003החותך\u0004 בשר \u0003מן האדם\u0004 בחייו לשם אכילה — \u0003צריך\u0004 לאחר מכן \u0003מחשבה\u0004 לאוכלו או להאכילו, \u0003ו\u0004כן צריך \u0003הכשר,\u0004 שיבוא עליו משקה, כדי להכשירו לקבל טומאה, כדין אוכלים.","\u0003וקשיא לן\u0004 \u0005[ו\u0006היה \u0005קשה לנו]:\u0006 \u0003מחשבה למה לי? תעשה חתיכה שלו,\u0004 עצם העובדה שחתכו אותו לשם אכילה, \u0003מחשבה\u0004 להאכילו! \u0003ואמר ריש לקיש:\u0004 מדובר \u0003בחותכו\u0004 מתחילה כדי להאכילו \u0003לכלב, ומחשבה\u0004 להאכיל \u0003לכלב לאו\u0004 \u0005[לא]\u0006 \u0003מחשבה היא.\u0004","ושואלים: \u0003ולא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006, \u0003כלל אמרו בטומאה: כל\u0004 דבר \u0003המיוחד לאכול\u0004 (למאכל) \u0003אדם\u0004 — \u0003טמא,\u0004 כלומר, ראוי ליטמא טומאת אוכלים, \u0003עד שיפסל מאכילת כלב!\u0004","ומשיבים: \u0003ההוא\u0004 \u0005[אותו דבר]\u0006 נאמר \u0003לאסוקי טומאה מיניה\u0004 \u0005[להעלות,\u0006 להוציא \u0005טומאה ממנו],\u0006 שכיון \u0003דמעיקרא הוה חזי\u0004 \u0005[שמתחילה היה ראוי]\u0006 \u0003לאדם, לאסוקי\u0004 \u0005[להעלות אותו]\u0006 \u0003מטומאה\u0004 לא ניתן \u0003עד שיפסל מאכילת כלב. הכא\u0004 \u0005[כאן,\u0006 כשחותך בשר\u0005]\u0006 מדובר \u0003לאחותי ליה\u0004 \u0005[להוריד אותו]\u0006 לקבלת \u0003טומאה,\u0004 ובמקרה זה \u0003אי חזי\u0004 \u0005[אם\u0006 הוא \u0005ראוי]\u0006 \u0003לאדם,\u0004 שחישב להאכילו לאדם — \u0003חזי\u0004 \u0005[ראוי]\u0006 \u0003לכלב,\u0004 כלומר, נחשב כראוי לאכילת כלב לענין טומאת אוכלים, \u0003אי לא חזי\u0004 \u0005[אם אינו ראוי]\u0006 \u0003לאדם\u0004 — \u0003לא חזי\u0004 \u0005[אינו\u0006 נחשב כ\u0005ראוי]\u0006 \u0003לכלב.\u0004","\u0003מכל מקום קתני\u0004 \u0005[הריהו שונה\u0006 שם\u0005]\u0006 שבשר אדם צריך \u0003מחשבה, ומחשבה\u0004 — \u0003ל\u0004ענין \u0003טומאה קלה היא\u0004 כלומר, לענין טומאת אוכלים (אבל לטומאה חמורה אין צורך במחשבה). והוא שלא כפי ששנינו בברייתא שאין באדם טומאה קלה! ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים] \u0003מחיים,\u0004 בחייו של האדם, שאם נחתך ממנו בשר — ראוי הוא לטומאה קלה, \u0003אבל לאחר מיתה\u0004 — \u0003טמא הוא טומאה חמורה,\u0004 טומאת מת, ואין מקום להזכיר בו טומאת אוכלים, שהיא טומאה קלה. והוא מה ששנינו בברייתא: אוציא דם מהלכי שתים.","ושואלים: והרי הוא הדין \u0003דכוותה גבי\u0004 \u0005[כיוצא בה אצל]\u0006 \u0003בהמה לאחר מיתה, אי\u0004 \u0005[אם]\u0006 \u0003בשר\u0004 בהמה — הרי הוא \u0003מטמא טומאה חמורה,\u0004 טומאת נבילה, \u0003ו\u0004כן \u0003אם דם\u0004 בהמה הוא — \u0003מטמא\u0004 הוא \u0003טומאה חמורה,\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006\u0003: דם נבילות\u0004 — \u0003בית שמאי מטהרין, ובית הלל מטמאין,\u0004 כדין טומאת נבילה, ומדוע מבדילה הברייתא בין אדם לבהמה לענין זה?","ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו, שאין באדם טומאה קלה לאחר מיתה כמו שיש בבהמה, \u0003אלא לכדתנן\u0004 \u0005[לכמו ששנינו\u0006 במשנה\u0005]\u0006 בענין טומאת אוכלים: \u0003נבלת בהמה טמאה\u0004 (כגון סוסים וחמורים) \u0003בכל מקום\u0004 שהוא, וכן \u0003נבלת עוף הטהור בכפרים\u0004 — \u0003צריך מחשבה\u0004 מפורשת לאכילה, כדי ליטמא טומאת אוכלים, לפי שבסתם אינם עומדים לאכילה, \u0003ואין צריך הכשר\u0004 על ידי משקה, שכל שסופו לטמא טומאה חמורה אינו צריך הכשר כדי ליטמא בטומאת אוכלים, אבל","\u0003נבלת בהמה טהורה בכל מקום, ונבלת עוף טהור וחלב בשוקים\u0004 — \u0003אין צריכין לא מחשבה ולא הכשר.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0005רב לר' חייא:\u0006 \u0003מחשבה\u0004 בנבלת בהמה טמאה \u0003למה לי לטומאה קלה?\u0004 הלוא \u0003היא גופה\u0004 \u0005[עצמה]\u0006 \u0003טומאה\u0004 חמורה \u0003היא! אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003כגון דאיכא\u0004 \u0005[שיש\u0006 בה\u0005] פחות מכזית נבילה,\u0006 ולכן אינה מטמאת משום נבילה, \u0003וצרפה לפחות מכביצה אוכלין, דהאי והאי הוי\u0004 \u0005[שזה וזה\u0006 ביחד \u0005הם]\u0006 \u0003כביצה,\u0004 שהוא השיעור ליטמא טומאת אוכלים.","הקשה לו רב: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין בחתיכה זו כשלעצמה לטמא טומאה חמורה, \u0003ליבעי נמי\u0004 \u0005[שתצטרך גם כן]\u0006 \u0003הכשר,\u0004 שיבוא עליו משקה, \u0003דהא תנא דבי\u0004 \u0005[שהרי שנה החכם מבית\u0006 מדרשו\u0005]\u0006 של ר' \u0003ישמעאל:\u0004 נאמר בענין הכשר אוכלים לקבל טומאה \"על כל זרע זרוע \u0003אשר יזרע\"\u0004 (ויקרא יא, לז), ללמד: \u0003מה זרעים מיוחדין שאין סופן לטמא טומאה חמורה ו\u0004לכן \u0003צריך הכשר, אף כל שאין סופן לטמא טומאה חמורה צריך הכשר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005] באוכלין דעלמא\u0006 \u0005[בכלל]\u0006 סתם אוכל, \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בו פחות מכזית נבלה, אבל הכא דאיכא בגויה\u0004 \u0005[כאן שיש בו]\u0006 \u0003פחות מכזית נבילה, כיון\u0004 ש\u0003אילו\u0004 היה \u0003מצרף ליה\u0004 \u0005[לו]\u0006 עוד קצת נבילה לשיעור \u0003כזית\u0004 היה מטמא — \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003הכשר.\u0004 ומכל מקום, דין זה שפחות מכזית נבילה מצטרף לשיעור כביצה ליטמא טומאת אוכלים, נאמר דווקא בבהמה;"],["\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 פחות מכזית מן ה\u0003מת, אף על גב דממליא ליה\u0004 \u0005[אף על פי שהוא ממלא אותו,\u0006 משלים את שיעורו\u0005]\u0006 לכביצה — \u0003לא מטמא טומאת אוכלין, משום\u0004 שבטלה \u0003דעתו אצל כל אדם,\u0004 שאין בני אדם אוכלים מבשר המת. והוא מה שאמר התנא שיש בבהמה טומאה קלה במותה, מה שאין באדם.","\u0003רב חנניא אמר:\u0004 מה שנאמר שנבלת בהמה טמאה צריכה מחשבה ליטמא טומאת אוכלים, ניתן להבינו \u0003אפילו תימא דהוי כזית\u0004 \u0005[תאמר שהוא\u0006 בשיעור \u0005כזית]\u0006 שיש בו עצמו כדי לטמא טומאה חמורה, שכן \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003כגון שחיפהו\u0004 (כיסה אותו) \u0003בבצק,\u0004 ובמקרה זה אינו מטמא טומאה חמורה, שהרי אינו נוגע בו, ומכל מקום יחד עם הבצק יש שיעור כביצה ליטמא בטומאת אוכלים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שאין בו טומאת נבילה, \u0003הכשר נמי ניבעי\u0004 \u0005[גם כן יצטרך]!\u0006 ומשיבים: \u0003הני מילי באוכלין אחריני\u0004 \u0005[דברים אלה\u0006 אמורים באוכלים אחרים], \u0003דלא מטמו\u0004 \u0005[שאינם מטמאים]\u0006 \u0003לא במגע ולא במשא. אבל הכא\u0004 \u0005[כאן],\u0006 \u0003נהי\u0004 \u0005[אף על פי]\u0006 ש\u0003לא מטמא במגע, דקמחפי\u0004 \u0005[\u0006משום \u0005שהוא מחופה]\u0006 \u0003בבצק, במשא מיהת ליטמא\u0004 \u0005[על כל פנים ייטמא]\u0006 הנושא אותו, \u0003דהא טעון ליה\u0004 \u0005[שהרי\u0006 הוא \u0005נושא אותו].\u0006","ועל כך נאמר שיש בבהמה טומאה קלה, גם במותה, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מת, דאף על גב\u0004 \u0005[שאף על פי]\u0006 שחיפהו \u0003בבצק מטמא טומאה חמורה,\u0004 מפני ש\u0003טומאת\u0004 המת \u0003בוקעת ועולה בוקעת ויורדת,\u0004 למרות שיש עליה כיסוי.","ושבים לדון בפרטי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יצאו שרצים שאין בהן טומאה\u0004 חמורה. ושואלים: \u0003ולא,\u0004 ואין בהם טומאה? הלוא \u0003שרץ מטמא במגע!\u0004 ומשיבים: על כל פנים \u0003במשא,\u0004 כמו בהמה, \u0003לא מטמא.\u0004","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003יצא דם דגים ודם חגבים שכולן היתר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003כולו היתר? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003חלבו,\u0004 חלב דגים וחלב חגבים \u0003מותר\u0004 — \u0003הרי חיה\u0004 גם היא \u0003חלבה מותר, ו\u0004מכל מקום \u0003דמה אסור! ואלא\u0004 תאמר: \u0003משום דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003איסור גיד הנשה\u0004 — \u0003והרי עוף\u0004 יוכיח \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003איסור גיד הנשה, ודמו אסור!\u0004","\u0003אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003כולו היתר\u0004 — \u0003דלא בעי\u0004 \u0005[שאינם צריכים]\u0006 \u0003שחיטה\u0004 כדי להתירם באכילה.","ועוד \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: אילו היה נאמר רק עוף באיסור דם הייתי אומר: \u0003מה עוף שאין בו כלאים, אף בהמה,\u0004 רק בהמה שאין בה כלאים דמה אסור — \u0003תלמוד לומר: \"בהמה\"\u0004 (ויקרא ז, כו).","ושואלים: \u0003כלאים דמאי\u0004 \u0005[של מה],\u0006 איזה מיני כלאים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כלאים\u0004 של איסור \u0003הרבעה,\u0004 שאסור להרביע מין בשאינו מינו, או \u0003כלאים\u0004 של \u0003חרישה,\u0004 שאסור לחרוש בשני מינים יחד — \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]: חיה ועוף כיוצא בהן,\u0006 כמו שאסור לחרוש בשור וחמור ואסור לזווג אותם — כך אסור הדבר בחיה ועוף!","\u0003אלא אמר אביי: שצימרו\u0004 כלומר, נוצות העוף, \u0003אין חייבין עליו משום כלאים\u0004 של בגדים (שעטנז), אם עירב אותו עם פשתן, וכמותו אין חייבים על שער הפרה או הסוס, שאין חייבים אלא על צמר כבשים.","\u0003אמר רב יהודה אמר רב: דם שרצים לוקין עליו\u0004 על אכילתו \u0003בכזית. מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא \u0003דם הטחול, דם הלב, דם הכליות, דם אברים\u0004 — \u0003הרי אלו\u0004 כולם \u0003ב\u0004חיוב \u0003לא תעשה\u0004 (ולא בכרת). ואילו \u0003דם מהלכי שתים\u0004 כלומר, דם אדם, וכן \u0003דם שרצים ורמשים\u0004 — \u0003אסור, ואין חייבין עליו!\u0004","ומשיבים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003אין חייבין עליו?\u0004 כוונתו: שאין חייבים על אכילתו \u0003כרת,\u0004 אבל \u0003אלאו מחייב\u0004 \u0005[על\u0006 איסור \u0005לא תעשה הוא חייב].\u0006","ומקשים: אין אתה יכול לפרש כן, \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד],\u0006 \u0003דהיינו רישא\u0004 \u0005[שזהו\u0006 מה שנאמר \u0005בתחילה]\u0006 לגבי דם הטחול והלב וכו', שהם בלא תעשה אבל כרת אין בהם. \u0003ועוד, תנא מלאו נמי קא ממעט ליה\u0004 \u0005[התנא מאיסור לא תעשה גם כן ממעט אותו],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בברייתא אחרת, ששנינו בתחילת סוגיה זו: \u0003יצא דם שרצים,\u0004 שאין בהם איסור \"לא תאכלו כל דם\", מפני \u0003שאין בהן טומאה חמורה!\u0004","\u0003אמר ר' זירא:\u0004 מה שאמר רב שדם שרצים לוקים עליו, כוונתו שאם \u0003התרו בו משום\u0004 איסור \u0003שרץ\u0004 — \u0003לוקה,\u0004 שאיסור אכילת שרץ כולל גם את דמו. אבל אם התרו בו \u0003משום\u0004 איסור \u0003דם\u0004 — באמת \u0003אינו לוקה.\u0004","\u0003אמר רב: דם דגים שכינסו\u0004 (שאסף אותו) בכלי — \u0003אסור\u0004 באכילה, משום מראית עין, שנראה כאוכל דם בהמה או עוף. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בהמשך הברייתא שאנו עוסקים בה: \u0003דם דגים, דם חגבים\u0004 — \u0003מותר, ו\u0004משמע — \u0003אפילו לכתחלה!\u0004 ומשיבים: בברייתא \u0003ההיא\u0004 מדובר \u0003בשלא כינסו, כי קא אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שאסור — הרי זה \u0003בשכינסו.\u0004","ושואלים: \u0003דכוותה גבי\u0004 \u0005[כיוצא בה\u0006 צריך אתה לפרש \u0005אצל]\u0006 דם \u0003מהלכי שתים\u0004 (אדם) ששנינו בברייתא זו שאסור, שמדובר גם \u0003בשלא כינסו,\u0004 ואולם במקרה זה \u0003מי\u0004 \u0005[האם]\u0006 הוא \u0003אסור? והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006\u0003: דם שעל גבי ככר\u0004 שהיה בפיו — \u0003גוררו\u0004 את הדם \u0003ואוכלו\u0004 את הככר, אבל דם \u0003של בין השינים\u0004 — \u0003מוצצו ובולעו ואינו חושש!\u0004","\u0003אלא\u0004 ברייתא זו עוסקת גם בדם שכינסו, ויש לתרץ באופן אחר: \u0003כי תניא ההיא מתניתא\u0004 \u0005[כאשר שנויה אותה ברייתא]\u0006 שדם דגים מותר לכתחילה (ואפילו בשכינסו), הרי זה במקרה \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003קשקשים,\u0004 שניכר שהוא דם דגים, \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 ש\u0003אסור\u0004 כשכינסו — מדובר \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003קשקשים,\u0004 ולא ניכר שהוא דם דגים.","\u0003אמר רב ששת: דם מהלכי שתים\u0004 (בני אדם) — \u0003אפילו מצות פרוש אין בו\u0004 כלומר, אין מצוה אפילו לפרוש ממנו לכתחילה, שאין בו איסור כלל. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003דם הטחול, דם הלב, דם הכליות, דם אברים\u0004 — \u0003הרי אלו בלא תעשה. דם מהלכי שתים, דם שרצים ורמשים\u0004 — \u0003אסור ואין חייב עליו,\u0004 משמע שעל כל פנים יש בו איסור! ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 בברייתא\u0005]\u0006\u0003 אסור\u0004 — הרי זה במקרה"],["ש\u0003פירש\u0004 מן האדם, \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 ששת שאפילו מצות פרוש אין בו — הרי זה כש\u0003לא פירש\u0004 מן האדם, \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 בברייתא\u0005]: דם שעל גבי ככר\u0006 — \u0003גוררו\u0004 את הדם \u0003ואוכלו\u0004 את הכיכר, כיון שפירש מן האדם, אבל דם של בין השינים — \u0003מוצץ ובולע ואינו חושש.\u0004","\u0003איכא דמתני לה להא\u0004 \u0005[יש ששונים את זו]\u0006 שאמר \u0003רב ששת על הדא\u0004 \u0005[זו],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול חלב מהלכי שתים\u0004 כלומר, חלב אשה, \u0003יהא\u0004 ה\u0003אוכלו עובר ב\u0004איסור \u0003לאו\u0004 \u0005[לא\u0006 תעשה\u0005]?\u0006 \u0003ו\u0004לכאורה \u0003דין,\u0004 קל וחומר \u0003הוא: מה בהמה טמאה שהקלתה במגעה,\u0004 שאין בה טומאת מגע בחייה, ובכל זאת \u0003החמרתה בחלבה\u0004 שהוא אסור, \u0003מהלכי שתים שהחמרתה במגען,\u0004 שהם מטמאים בחייהם, כגון נדה — \u0003אינו דין שתחמיר בחלבן\u0004 לאוסרו?","\u0003תלמוד לומר: \"וזה לכם הטמא\"\u0004 (ויקרא יא, כט), להדגיש: \u0003זה\u0004 החיות הטמאות המנויות שם \u0003טמא\u0004 (הוא וחלבו), \u0003ואין חלב מהלכי שתים טמא אלא טהור.\u0004","ויש לשאול: אם ממיעוט זה \u0003אוציא\u0004 רק \u0003את החלב\u0004 של מהלכי שתים, ואתיר אותו, לפי \u0003שאין\u0004 איסור החלב \u0003שוה בכל,\u0004 שהרי אינו אסור אלא בבעלי חיים טמאים, ולא אוציא את \u0003הדם ששוה\u0004 איסורו \u0003בכל,\u0004 שהרי גם דמם של בעלי חיים טהורים אסור, ונאמר שדם בני אדם יש בו איסור! \u0003תלמוד לומר: \"וזה לכם הטמא\",\u0004 לומר: \u0003זה טמא, ואין דם מהלכי שתים טמא אלא טהור.\u0004 ועל כך \u0003אמר לה רב ששת: אפילו מצות פרוש אין בו\u0004 בדם האדם.","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003הלב\u0004 של בעל חיים שנשחט, \u0003קורעו ומוציא את דמו,\u0004 ואחר כך רשאי לאוכלו; \u0003לא קרעו,\u0004 ואכלו — \u0003אינו עובר עליו\u0004 משום איסור אכילת דם שבו. \u0003אמר ר' זירא אמר רב: לא שנו\u0004 שאינו עובר עליו \u0003אלא בלב עוף, הואיל ואין בו כזית\u0004 דם, \u0003אבל לב בהמה\u0004 שיש \u0003בו כזית\u0004 — \u0003אסור, וחייבין עליו כרת.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003דם הטחול, דם הלב, דם הכליות, דם אברים\u0004 — \u0003הרי אלו בלא תעשה,\u0004 ואין חייבים עליו כרת. \u0003דם מהלכי שתים, דם שקצים ורמשים\u0004 — \u0003אסור ואין חייבין עליו\u0004 כלל. משמע שאין חיוב כרת בדם הלב!","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר\u0006 התנא \u0005שונה]\u0006 \u0003אין חייבין עליו\u0004 הכוונה היא — \u0003על דם דיליה\u0004 \u0005[שלו],\u0006 שבלוע בבשר הלב עצמו, \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שחייב עליו כרת — הרי זה בדם \u0003דאתי ליה מעלמא\u0004 \u0005[שבא לו מבחוץ],\u0006 ומצוי בחלל הלב.","ומקשים: \u0003דם דיליה\u0004 \u0005[שלו]\u0006 \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003דם אברים,\u0004 שכבר שנינו באותה רשימה עצמה! ודוחים: \u0003וליטעמיך\u0004 \u0005[ולשיטתך],\u0006 \u0003מי לא קתני\u0004 \u0005[האם אינו שונה]\u0006 שם \u0003דם כליות וקתני\u0004 \u0005[ושונה]\u0006 גם \u0003דם אברים? אלא\u0004 בהכרח צריך אתה לומר כי התנא \u0003תני והדר תני\u0004 \u0005[שונה וחוזר\u0006 ו\u0005שונה]\u0006 בפרטות, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענין דם הלב, צריך לפרש שהוא הדם שלו, דם איברים, והתנא \u0003תני והדר תני\u0004 \u0005[שונה וחוזר\u0006 ו\u0005שונה].\u0006","ושואלים: \u0003מעלמא מהיכא אתי ליה\u0004 \u0005[מן החוץ מהיכן בא לו]\u0006 הדם ללב? \u0003אמר ר' זירא: בשעה שהנשמה יוצאה מישרף שריף\u0004 \u0005[\u0006הלב \u0005גומע,\u0006 שואב\u0005]\u0006 דם שהנפש יוצאה בו, ועליו חייבים כרת.","שנינו במשנה: \u0003דם\u0004 הקזה \u0003שהנשמה יוצאה בו\u0004 — \u0003חייבין עליו\u0004 כרת. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003איזהו דם הקזה שהנשמה תלויה בו\u0004 שיש באכילתו כרת? \u0003ר' יוחנן אמר: כל זמן שמקלח,\u0004 שיוצא בכוח ואינו שותת. \u0003ריש לקיש אמר: מטיפה המשחרת ואילך,\u0004 לאחר שכלו הטיפות השחורות שבתחילה, ומתחיל לצאת דם אדום, למרות שאינו מקלח עדיין.","\u0003מיתיבי\u0004 \u0005[מקשים על\u0006 ריש לקיש\u0005]\u0006 ממה ששנינו: \u0003איזהו דם הקזה שהנשמה יוצאה בו? כל זמן שמקלח, יצא\u0004 מכלל זה \u0003דם התמצית,\u0004 שמתמצה לאחר יציאת הנפש, \u0003מפני שהוא שותת. מאי לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 ש\u0003אפילו\u0004 דם \u0003ראשון ואחרון,\u0004 כל ש\u0003שותת הוא\u0004 (ואפילו הוא אדום) — \u0003כדם התמצית דמי\u0004 \u0005[נחשב]?\u0006 ואם כן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003ריש לקיש!\u0004","ודוחים: \u0003לא,\u0004 מה שנאמר \"יצא דם התמצית\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 רק \u0003דם המשחיר, אבל דם\u0004 אדום \u0003ראשון ואחרון,\u0004 שלפני הקילוח ושלאחריו, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שהוא \u0003שותת\u0004 — \u0003היינו\u0004 \u0005[הרי זה]\u0006 \u0003דם הנפש.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 מברייתא אחרת: \u0003איזהו דם (ראשון) [הנפש]? כל זמן שמקלח, יצא\u0004 דם \u0003ראשון ואחרון,\u0004 שאינו חייב עליו כרת, \u0003מפני שהוא שותת.\u0004 והרי זו \u0003תיובתיה\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ריש לקיש!\u0004 ומשיבים, \u0003אמר לך\u0004 \u0005[יכול\u0006 ריש לקיש \u0005לומר לך]:\u0006 \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]: איזהו דם הנפש? כל זמן שמקלח, דברי ר'\u0006 \u0003אלעזר. ר' שמעון אומר: מטיפה המשחרת ואילך,\u0004 ואני סבור כדעת ר' שמעון.","ועוד בענין דם, אבל לענין אחר, \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו] של ר' \u0003ישמעאל\u0004 על הכתוב: \"\u0003ודם חללים ישתה\"\u0004 (במדבר כג, כד), מכאן למדים שדווקא דם של מי שכבר יצאה נפשו (חלל) נחשב משקה, ומכשיר את הזרעים (ושאר אוכלים) לקבלת טומאה, \u0003פרט לדם קילוח שאינו מכשיר את הזרעים.\u0004","ושבים לדון באיסור דם, \u0003בעא מיניה\u0004 \u0005[שאל אותו] ר'\u0006 \u0003ירמיה מר' זירא:\u0004 אם \u0003הקיז דם לבהמה וקיבל דמה בשני כוסות,\u0004 ושתה ממנו \u0003מהו? על\u0004 הכוס \u0003הראשון\u0004 — \u0003דברי הכל חייב,\u0004 שהרי יש בו דם מקלח, \u0003על האחרון,\u0004 שיש בו דם רק לאחר שפסק הקילוח — \u0003מי מיחייב\u0004 \u0005[האם הוא חייב]\u0006 \u0003או לא?\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פלוגתא\u0004 \u0005[מחלוקת\u0006 היא\u0005]\u0006 של ר' \u0003יוחנן וריש לקיש, דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בענין זה: \u0003הקיז דם לבהמה וקיבל דמה בשני כוסות\u0004 — \u0003ריש לקיש אמר: חייב שתי חטאות,\u0004 אם אכלם בשני העלמות, שגם על הדם שלאחר קילוח חייב כרת. ו\u0003ר' יוחנן אמר: אינו חייב אלא אחת,\u0004 על הדם המקלח שבכוס הראשון.","שנינו במשנה שאין חייבים כרת על דם התמצית (המתמצה לאחר יציאת הנפש), ואילו \u0003ר' יהודה מחייב\u0004 כרת \u0003בדם התמצית. אמר ר' אלעזר: מודה ר' יהודה לענין כפרה\u0004 על המזבח, שאם זרק מדם התמצית של הקרבן על קרנות המזבח — אינו מכפר, \u0003שנאמר: \"כי הדם הוא בנפש יכפר\"\u0004 (ויקרא יז, יא), \u0003דם שהנפש יוצאה בו\u0004 הוא \u0003מכפר, ושאין הנפש יוצאה בו אינו מכפר.\u0004","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כיוצא בזה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בסיפרא (תורת כהנים, מדרש ההלכה לספר ויקרא): נאמר \"ואיש איש... אשר יאכל כל דם... והכרתי אותה מקרב עמה\" (שם י), ויכול היה לומר \u0003\"דם\", מה תלמוד לומר \"כל דם\"?\u0004","\u0003לפי שנאמר\u0004 בהמשך לכתוב זה: \u0003\"כי הדם הוא בנפש יכפר\"\u0004 (שם יא), יכול אתה לומר: \u0003אין לי\u0004 שחייב כרת \u0003אלא\u0004 על \u0003דם קדשים שהנפש יוצאה בו, שהוא מכפר, דם חולין ודם התמצית\u0004 (אפילו של קדשים) שאינו מכפר, \u0003מנין\u0004 שחייב עליו כרת? \u0003תלמוד לומר: \"כל דם\".\u0004 והרי \u0003סתם סיפרא מני\u0004 \u0005[\u0006שיטת \u0005מי היא]?\u0006 מקובל בידינו ששיטת ר' \u0003יהודה היא,\u0004 ואם כן אף ר' יהודה סבור שדם התמצית אינו מכפר.","ושבים לדיני אשם תלוי ששנינו בפרק הקודם. \u0003ר' עקיבא מחייב על ספק מעילה,\u0004 אם לא ברור לו אם מעל וחייב אשם מעילות (ראה ויקרא ה, טו) \u0003אשם תלוי, וחכמים פוטרים,\u0004 שאין מביאים אשם תלוי אלא על ספק חיוב חטאת, ולא על ספק אשם. \u0003ומודה ר' עקיבא, שאינו מביא את מעילתו\u0004 כלומר, את דמי המעילה, \u0003עד שיתודע לו\u0004 שמעל, \u0003ש\u0004אז \u0003יביא עמו אשם ודאי.\u0004","\u0003אמר ר' טרפון: מה לזה מביא שתי אשמות,\u0004 אשם תלוי בתחילה, ואשם ודאי לבסוף? \u0003אלא מביא\u0004 מתחילה דמי \u0003מעילה וחומשה\u0004 (כפי שחייבה התורה, ראה ויקרא שם), \u0003ויביא אשם ב\u0004שווי \u0003שני סלעים, ויאמר: אם ודאי מעלתי\u0004 — \u0003זו\u0004 כסף \u0003מעילתי\u0004 (וחומשו) \u0003וזו\u0004 האיל \u0003אשמי, ואם ספק מעלתי\u0004 — \u0003המעות\u0004 שאני נותן הם \u0003נדבה\u0004 לקרבנות ציבור, \u0003ואשם\u0004 יהיה \u0003תלוי.\u0004 ויכול להביא אשם אחד ולהתנות עליו, \u0003ש\u0004הרי \u0003ממין שהוא מביא\u0004 אשם \u0003על הודע\u0004 אם ידע בוודאות שחטא במעילה, \u0003מביא\u0004 גם \u0003על לא הודע,\u0004 כלומר, אשם תלוי, ששניהם באים איל בשווי שני סלעים.","\u0003אמר ר' עקיבא: נראין דבריו\u0004 של ר' טרפון, שיביא עכשיו מעילה וחומשה, ואשם על תנאי — \u0003במעילה מעוטה.\u0004 אבל \u0003הרי\u0004 במקרה \u0003שיבוא לידו ספק מעילה במאה מנה\u0004 (מנה = מאה דינרים), \u0003לא יפה\u0004 (מוטב) \u0003לו שיביא\u0004 עכשיו \u0003אשם\u0004 תלוי \u0003בשתי סלעים,\u0004 ורק אם ייוודע לו שאכן מעל — יביא מעילתו ואשם ודאי, \u0003ולא יביא\u0004 כבר עכשיו \u0003ספק מעילה במאה מנה?\u0004 ומעירים: מדברים אלו משמע כי \u0003מודה ר' עקיבא לר' טרפון במעילה מעוטה,\u0004 שיביא מתחילה מעילה וחומשה ואשם, ויעשה תנאי."],["בענין ששנינו במשנתנו, האם מביאים על ספק מעילה אשם תלוי, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש ההלכה: מה שנאמר בתחילת דין אשם תלוי, מיד לאחר פרשת המעילה: \u0003\"ואם נפש\"\u0004 (ויקרא ה, יז) בוי\"ו החיבור, בא \u0003לחייב על ספק מעילות אשם תלוי,\u0004 אלו \u0003דברי ר' עקיבא, וחכמים פוטרים.\u0004","ומציעים: \u0003לימא בהא קא מיפלגי\u0004 \u0005[האם נאמר שבכך הם חלוקים],\u0006 בדרכי מדרש ההלכה, ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 כאשר התורה מצרפת שני עניינים בוי\"ו החיבור, \u0003למדין\u0004 דין \u0003עליון מ\u0004דין \u0003תחתון\u0004 שכתוב אחריו, ולכן גם בספק מעילה מביא אשם תלוי, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין למדין עליון מתחתון?\u0004","\u0003אמר רב פפא: דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003למדין עליון מתחתון,\u0004 שאם \u0003כן,\u0004 אם אין אתה אומר כך, \u0003צפון בבן בקר,\u0004 מה שצריך לשחוט עולה מן הבקר בצד צפון של המזבח, \u0003לא משכחת להו\u0004 \u0005[אין אתה מוצא להם,\u0006 לשיטת חכמים\u0005],\u0006 שהרי לא למדנוהו אלא ממה שנאמר אחריו: \"ואם מן הצאן... ושחט אותו על ירך המזבח צפונה\" (שם א, י—יא).","\u0003אלא הכא היינו טעמא דרבנן דפטרי\u0004 \u0005[כאן זהו טעמם של חכמים שפוטרים]\u0006 ספק מעילות מאשם תלוי — מפני \u0003דגמירי\u0004 \u0005[שהם לומדים]\u0006 בגזירה שווה \"\u0003מצות\" \"מצות\" מחטאת:\u0004","\u0003מה להלן,\u0004 בחטאת שנאמר בה: \"בעשותה אחת ממצוות ה' אשר לא תעשנה\" (שם ד, כז) הרי זה ב\u0003דבר שחייבין על זדונו כרת ועל שגגתו חטאת, ו\u0004חייבים \u0003על ספקו אשם תלוי, אף כל שחייבין על זדונו כרת ועל (ספקו) [שגגתו] חטאת\u0004 — \u0003ועל (שגגתו) [ספקו]\u0004 חייבים \u0003אשם\u0004","\u0003תלוי; לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מעילה\u0004 ש\u0003אין חייבין על זדונו כרת, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003: הזיד במעילה\u0004 כלומר, מעל בקודש במזיד — \u0003רבי אומר:\u0004 עונשו \u0003במיתה\u0004 בידי שמים, \u0003וחכמים אומרים: באזהרה,\u0004 ככל מצות לא תעשה. הרי שהכל מודים שאין בכך כרת, ולכן אין מביאים על ספקו אשם תלוי.","\u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003כי ילפינן\u0004 \u0005[כאשר אנו למדים]\u0006 בגזירה שווה \u0003\"מצות\" \"מצות\" מחטאת חלב\u0004 לאשם תלוי — \u0003להכי הוא דילפינן\u0004 \u0005[ל\u0006ענין \u0005זה אנו למדים]:\u0006 \u0003מה להלן,\u0004 בחטאת שנאמר בה \"מצוות\", מדובר \u0003ב\u0004חטאת \u0003קבועה\u0004 שקרבנה קבוע, שמביא כבשה או שעירה — \u0003אף כאן,\u0004 באשם תלוי, מדובר \u0003ב\u0004מי שיש לו ספק בחטאת \u0003קבועה,\u0004","\u0003לאפוקי\u0004 \u0005[להוציא]\u0006 עבירות כגון על טומאת מקדש וקדשיו ושבועת העדות, שמביא עליהן קרבן \u0003עולה ויורד,\u0004 מן הצאן, מן העוף, או מן המנחה, בהתאם למצבו הכלכלי (ראה ויקרא ה, א—יד), שעל עבירות אלו \u0003לא\u0004 מביאים עליהן אשם תלוי.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 לעומתו: \u0003אין גזירה שוה למחצה,\u0004 ואם יש גזירה שווה הרי למדים ממנה את כל הפרטים, ובכלל זה, שאין אשם תלוי בא אלא על דבר שזדונו כרת. ותוהים: \u0003מכלל\u0004 הדברים אתה למד ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 ש\u0003יש גזירה שוה למחצה?\u0004 והלוא לא שמענו מי שסבור כן! \u0003אלא\u0004 כך צריך לומר, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין גזירה שוה למחצה.\u0004","\u0003אלא היינו טעמא\u0004 \u0005[זהו טעמו]\u0006 של ר' \u0003עקיבא, דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 בתחילת דינו של אשם תלוי: \u0003\"ואם נפש\"\u0004 — \u0003וי\"ו\u0004 של \"ואם\" \u0003מוסיף\u0004 את האמור בפרשה זו \u0003על ענין ראשון\u0004 של מעילה, \u0003ו\u0004כך \u0003ילמד עליון מתחתון,\u0004 שמביא אשם תלוי גם בספק מעילה, והיקש זה מוציא פרט זה מן הגזירה שווה לחטאת.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 בהיקש זה, דווקא \u0003תחתון\u0004 (אשם תלוי) \u0003הוא דגמר\u0004 \u0005[שלומד]\u0006 \u0003מעליון\u0004 (אשם מעילות) \u0003ל\u0004ענין זה שיביא \u0003אשם בכסף שקלים,\u0004 כלומר, בשווי שני שקלים לפחות, שנאמר באשם מעילות: \"והביא את אשמו לה' איל תמים מן הצאן בערכך כסף שקלים\" (שם טו), אבל אין למדים עליון מתחתון.","\u0003ו\u0004לעומתם \u0003ר' עקיבא סבר\u0004 \u0005[סבור]:\u0006 כיון שהתורה הסמיכה את שני הדינים זה לזה — \u0003אין היקש למחצה,\u0004 ויש ללמוד גם עליון מתחתון, ולחייב גם בספק מעילה אשם תלוי. ותוהים: \u0003מכלל\u0004 הדברים אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 שיש \u0003היקש למחצה? והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]\u0006 שאין \u0003היקש למחצה!\u0004","אלא יש להסביר אחרת: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 בדרך כלל \u0003אין היקש למחצה, והכא היינו טעמא דרבנן\u0004 \u0005[וכאן זהו טעמם של חכמים]\u0006 — \u0003דגמירי\u0004 \u0005[\u0006שמה \u0005שלומדים]\u0006 גזירה שווה \u0003\"מצות\" \"מצות\"\u0004 מחטאת, \u0003אפקיה מהקישא\u0004 \u0005[הוציא\u0006 דין \u0005זה מן ההיקש],\u0006 שאין למדים בהיקש זה עליון מתחתון, לחייב ספק מעילה באשם תלוי, אלא רק תחתון מעליון — שיביא אשם תלוי בכסף שקלים.","\u0003ור' עקיבא, אשם\u0004 שהוא \u0003בכסף שקלים נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 \u0003מ\"זאת תורת האשם\"\u0004 (שם ז, א) — \u0003תורה אחת לכל האשמות, ל\u0004הביא כל \u0003אשם בכסף שקלים,\u0004 והואיל ואין גזירה שווה יכולה לעקור היקש לגמרי הריהו למד ממנו לחייב ספק מעילות באשם תלוי.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? \u0003אף על גב דכתיב\u0004 \u0005[אף על פי שנאמר]\u0006\u0003: \"זאת תורת האשם\",\u0004 מכל מקום \u0003איצטריך למכתב\u0004 \u0005[הוצרך להיכתב]\u0006 \u0003\"ואם נפש\"\u0004 באשם תלוי, לומר: \u0003וי\"ו מוסיף על ענין ראשון וילמד תחתון מעליון,\u0004 שיביא אשם תלוי בכסף שקלים כמו אשם מעילות.","\u0003ו\u0004טעם הדבר, כי \u0003אי\u0004 \u0005[אם]\u0006 רק \u0003מ\"זאת תורת האשם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003כי אמינא\u0004 \u0005[כאשר אני אומר]\u0006 \u0003תורה אחת לכל אשמות\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003בשאר אשמות ודאין\u0004, כגון אשם גזילות,","\u0003אבל אשם תלוי, כיון\u0004 ש\u0003על ספק\u0004 חטאת \u0003חלב קאתי\u0004 \u0005[הוא בא],\u0006 \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003לא יהא ספיקו חמור מודאו, מה ודאו,\u0004 אם ברור לו שחטא — מביא \u0003חטאת בת דנקא\u0004 \u0005[שישית הדינר],\u0006 \u0003אף ספיקו\u0004 — די שיביא \u0003אשם בר דנקא\u0004 \u0005[בן שישית דינר],\u0006 \u0003אהכי כתב רחמנא\u0004 \u0005[משום כך כתבה תורה]\u0006\u0003 \"ואם נפש\", וי\"ו מוסיף על ענין ראשון,\u0004 ללמוד מאשם מעילה שצריך להביא בכסף שקלים. וכאמור, לדעת ר' עקיבא אין למדים דין זה מ\"ואם נפש\", ולכן למד מכאן לחייב ספק מעילה באשם תלוי.","ושואלים: \u0003הא ניחא למאן דדריש\u0004 \u0005[זה נוח למי שדורש] \"\u0006\u0003זאת תורת האשם\",\u0004 ומכאן למד ר' עקיבא לאשם בכסף שקלים. \u0003אלא למאן דלא דריש\u0004 \u0005[ל\u0006דעת \u0005מי שלא דורש]\u0006\u0003 \"זאת תורת האשם\", מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מהיכן הוא למד שכל אשמות באים בכסף שקלים? ומשיבים: \u0003יליף\u0004 \u0005[נלמד]\u0006 הוא בגזירה שווה \"\u0003בערכך\" \"בערכך\" מאשם מעילה\u0004 (ויקרא ה, טז) לשאר אשמות שנאמר בהם ביטוי זה (שם ה, יח. שם כז).","ושואלים: \u0003אשם שפחה חרופה\u0004 ש\u0003לא כתב בה \"בערכך\"\u0004 מהיכן למדים? ומשיבים: \u0003ילפינן\u0004 \u0005[למדים אנו] ב\u0006גזירה שווה אחרת \"\u0003איל\" \"איל\"\u0004 (ראה ויקרא ה, טו. שם יט, כא).","שנינו במשנה: \u0003מודה ר' עקיבא כו'\u0004 שמי שיש בידו ספק מעילה מביא אשם תלוי. ואם ייוודע לו שמעל יביא אשם ודאי יחד עם דמי המעילה וחומשה. אמר ר' טרפון: יביא מתחילה מעילה וחומשה ואשם, ויאמר: אם ודאי מעילתי — זו מעילתי וזו אשמי, \u0003ואם ספק\u0004 — המעות נדבה ואשם תלוי.","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה\u0006 הוא \u0005אומר]\u0006 לשם מה יאמר \"ואם ספק\"? והרי ברור שספק בידו! \u0003אמר רבא, תני\u0004 \u0005[שנה\u0006 כך\u0005]:\u0006 \u0003אם בספיקו עומד לעולם\u0004 — \u0003יהא אשם\u0004 זה \u0003תלוי.\u0004 ויכול להביא אשם כזה ולהתנות עליו, מפני \u0003שממין שהביא על הודע\u0004 (איל בשני שקלים) \u0003מביאו על שלא הודע.\u0004","ושואלים: \u0003סוף סוף,\u0004 גם לשיטת ר' טרפון אינו נפטר משני אשמות, שהרי הביא אשם רק על הספק, ואם כן \u0003כי מתידע ליה\u0004 \u0005[כאשר יתוודע לו]\u0006 שמעל \u0003בעי לאיתויי\u0004 \u0005[צריך להביא]\u0006 \u0003אשם ודאי!\u0004","\u0003אמר רבא, מדברי שניהם,\u0004 ר' טרפון, וגם ר' עקיבא שמודה לו במעילה מועטת, \u0003נלמד\u0004 שאשם \u0003ודאי לא בעי\u0004 \u0005[צריך]\u0006 \u0003ידיעה לכתחלה,\u0004 שאין צורך שידע בוודאות שחטא כדי לצאת ידי חובת קרבנו.","בהמשך למה ששנינו במשנה הקודמת בענין אשם, שממין שמביא על הודאי מביא על הספק, מוסיפים, \u0003האשה שהביאה חטאת העוף\u0004 מספק, שלא ברור לה אם ילדה וולד שחייבים להביא עליו קרבן לידה או לא, וחטאת זו אינה נאכלת לכהנים, אם \u0003עד שלא נמלקה\u0004 החטאת \u0003נודע לה שילדה ודאי\u0004 — \u0003תעשינה\u0004 את החטאת הזו לחטאת \u0003ודאי,\u0004 ותיאכל לכהנים, למרות שהביאה אותה על הספק, מפני \u0003שממין שהיא מביאה על הודע\u0004 על לידה ודאית (תור או בן יונה), \u0003מביאה על לא הודע.\u0004","ושבים לדון בדיני אשם תלוי. היו לפניו \u0003חתיכה של חולין וחתיכה של הקדש, אכל אחת מהן ואין יודע איזה מהן אכל\u0004 — הרי זה \u0003פטור, ר' עקיבא מחייב אשם תלוי,\u0004 לשיטתו במשנה הקודמת, שמביאים על ספק מעילה אשם תלוי. אם \u0003אכל את השניה\u0004 משתי החתיכות הללו — \u0003מביא אשם ודאי,\u0004 שהרי ודאי אכל משל הקדש.","\u0003אכל אחד את הראשונה ובא אחר ואכל את השניה\u0004 — \u0003זה מביא אשם תלוי\u0004 שמא מעל, \u0003וזה מביא אשם תלוי\u0004 שמא הוא מעל, אלו \u0003דברי ר' עקיבא. ר' שמעון אומר: שניהן מביאין אשם אחד\u0004 בשותפות, ומתנים שמי שאכל את ההקדש — השני מוחל לו על חלקו והאשם הקרב עבורו. ר' \u0003יוסי אומר:\u0004"],["\u0003אין שנים מביאין אשם אחד,\u0004 שאין עושים תנאי בקרבנות הבאים על חטא.","היו לפניו \u0003חתיכת חלב וחתיכת חולין, אכל אחת מהן ואינו יודע איזה מהן אכל\u0004 — \u0003מביא אשם תלוי,\u0004 שמא אכל את החלב. \u0003אכל\u0004 גם \u0003את השניה,\u0004 שאז ודאי לו שחלב אכל — \u0003מביא חטאת. אכל אחד את הראשונה ובא אחר ואכל את השניה\u0004 — \u0003זה מביא אשם תלוי וזה מביא אשם תלוי,\u0004 אלו \u0003דברי ר' עקיבא. ר' שמעון אומר: שניהם מביאין חטאת אחת,\u0004 ומתנים שאם זה אכל את החלב — החטאת שלו, ואם האחר — הריהי של האחר. \u0003ר' יוסי אומר: אין שנים מביאין חטאת אחת,\u0004 לפי שאין מביאים קרבן כזה על תנאי.","היו לפניו \u0003חתיכת חלב וחתיכת\u0004 שומן של \u0003קודש, אכל אחת מהן ואינו יודע איזה מהן אכל\u0004 — \u0003מביא אשם תלוי,\u0004 שמא אכל את החלב. \u0003אכל את השניה\u0004 — \u0003מביא חטאת\u0004 על החלב, \u0003ואשם ודאי\u0004 (אשם מעילות) על שאכל מן הקודש. \u0003אכל אחד את הראשונה ובא אחר ואכל את השניה\u0004 — \u0003זה מביא אשם תלוי וזה מביא אשם תלוי. ר' שמעון אומר: שניהן מביאין\u0004 יחד \u0003חטאת ואשם,\u0004 ומתנים. ר' \u0003יוסי אומר: אין שנים מביאין חטאת ואשם אחד,\u0004 שאין עושים תנאי בקרבן הבא על חטא.","היו לפניו \u0003חתיכת חלב וחתיכת חלב קודש, אכל אחת מהן ואין יודע איזו מהן אכל\u0004 — \u0003מביא חטאת,\u0004 שהרי בוודאי אכל חלב, ר' \u0003עקיבא אומר: אף אשם תלוי\u0004 מביא, שמא אכל מן הקודש, ולשיטתו מביא על ספק מעילות אשם תלוי. \u0003אכל\u0004 גם \u0003את השניה\u0004 — \u0003מביא שני חטאות,\u0004 משום שאכל שתי חתיכות חלב, \u0003ואשם ודאי,\u0004 משום שאכל קודש.","\u0003אכל אחד את הראשונה ובא אחר ואכל את השניה\u0004 — \u0003זה מביא חטאת וזה מביא חטאת. ר' עקיבא אומר: זה וזה מביאין\u0004 גם \u0003אשם תלוי,\u0004 שהרי אינם יודעים מי מהם אכל מן הקודש. ר' \u0003שמעון אומר: זה מביא חטאת וזה מביא חטאת,\u0004 ששניהם אכלו בוודאות חלב, \u0003ושניהן מביאין אשם אחד\u0004 בשותפות על המעילה, ומתנים. \u0003ר' יוסי אומר: אין שניהן מביאין אשם אחד.\u0004","היו שם \u0003חתיכת חלב וחתיכת חלב נותר,\u0004 מקרבן שעבר זמן אכילתו (שחייבים על זדונו כרת ועל שגגתו חטאת), \u0003אכל אחת מהן ואין יודע איזה מהן אכל\u0004 — \u0003מביא חטאת,\u0004 שהרי בוודאי אכל חלב, \u0003ואשם תלוי,\u0004 שמא אכל מן הנותר. \u0003אכל את השניה\u0004 — \u0003מביא שלש חטאות,\u0004 שתים משום חלב, ואחת משום נותר.","\u0003אכל אחד את הראשונה ובא אחר ואכל את השניה\u0004 — \u0003זה מביא חטאת ואשם תלוי,\u0004 שבוודאי אכל חלב, ושמא אכל נותר, \u0003וזה מביא חטאת ואשם תלוי. ר' שמעון אומר: זה מביא חטאת וזה מביא חטאת, ושניהן מביאין חטאת אחת\u0004 ומתנים ביניהם. \u0003ר' יוסי אומר\u0004 כלל הוא: \u0003כל חטאת שהיא באה על חטא\u0004 — \u0003אין שנים מביאין אותה.\u0004","שנינו כי במקרה של חתיכת חלב וחתיכת חולין, ואכל אחד את הראשונה ובא אחר ואכל את השניה, לדעת ר' שמעון מביאים שניהם חטאת אחת על תנאי, ואילו ר' יוסי אומר: אין שניים מביאים חטאת אחת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0005רבא לרב נחמן: לר' י\u0006 \u0003וסי חטאת הוא דלא מייתו\u0004 \u0005[שאין מביאים]\u0006 \u0003שניהן, הא\u0004 \u0005[אבל]\u0006 \u0003אשם תלוי מייתו\u0004 \u0005[מביאים]\u0006 \u0003שניהם?\u0004 אם כן, \u0003היינו תנא קמא\u0004 \u0005[הרי זו\u0006 שיטת \u0005התנא הראשון]\u0006 שאמר במפורש: זה מביא אשם תלוי וזה מביא אשם תלוי!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 בענין \u0003חתיכה משתי חתיכות איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, שלדעת ר' יוסי, רק הראשון, שיש לו ספק באחת משתי חתיכות — מביא אשם תלוי, אבל השני שעמדה לפניו חתיכה אחת שיש בה ספק — אינו מביא אשם תלוי, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006\u0003, ר' יוסי אומר: זה מביא אשם תלוי וזה מביא אשם תלוי! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא קא משמע לן\u0004 \u0005[זה משמיע לנו],\u0006 \u0003דמאן תנא קמא\u0004 \u0005[שמי הוא התנא הראשון]\u0006 — \u0003ר' יוסי.\u0004","שנינו במשנה: חתיכת חלב וחתיכת קודש כו', \u0003חתיכת חלב וחתיכת חלב קודש כו'.\u0004 ועוד שנינו: \u0003חתיכת חלב וחתיכת חלב נותר,\u0004 אכל אחת מהן וחזר ואכל את השניה — מביא שלוש חטאות, שתים משום חלב ואחת משום נותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: וליתי נמי\u0004 \u0005[ויביא גם כן]\u0006 \u0003אשם ודאי\u0004 של מעילה, שהרי \u0003נותר\u0004 של \u0003קדש הוא,\u0004 ואכל מן הקודש בשגגה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מדובר כאן \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003שוה פרוטה,\u0004 ואין מועלים בפחות משווה פרוטה.","הקשה לו רבא: \u0003והא מעיקרא\u0004 \u0005[מתחילה]\u0006 בדינים הקודמים במשנה זו, במקרה \u0003דאית ביה\u0004 \u0005[שיש בו]\u0006 \u0003שוה פרוטה עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 שאם אכל חתיכה של חלב וחתיכה של קודש מביא \u0003אשם ודאי\u0004 על אכילת הקודש! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההיא\u0004 \u0005[אותה]\u0006 \u0003חתיכה\u0004 של קודש ש\u0003לא נותר היא,\u0004 והיא \u0003שויא\u0004 \u0005[שווה]\u0006 \u0003פרוטה,\u0004 אבל חתיכת נותר אין בה שווה פרוטה, שכבר עבר עליה זמן, ואנשים נמנעים מלאוכלה.","הקשה לו רבא, \u0003והא\u0004 \u0005[והרי]\u0006 במשנה ששנינו לעיל: \u0003יש אוכל אכילה אחת, דקתני ביה\u0004 \u0005[שהוא שונה בו]\u0006 גם \u0003נותר, וקתני\u0004 \u0005[והוא שונה]:\u0006 \u0003מביא ארבע חטאות ואשם אחד\u0004 (משום מעילה) בנותר, משמע שיש בנותר כדי שווה פרוטה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003ההיא בגסה,\u0004 שאכל אכילה מרובה, שיש בה שווה פרוטה, \u0003וההיא\u0004 במשנה שלנו מדובר \u0003בדקה,\u0004 שאכל חתיכה קטנה, שאין בה שווה פרוטה, \u0003ולא קשיא\u0004 \u0005[ולא קשה]\u0006 הדבר. ועוד יש לומר: \u0003ההיא\u0004 שחייב על נותר, עוסקת בנותר \u0003בימות הגשמים,\u0004 שאינו מתקלקל מהר, ויש בו שווה פרוטה, \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003בימות החמה,\u0004 שהנותר מתקלקל, ואינו שווה פרוטה.","שנינו במשנה בענין חתיכה של חלב וחתיכה של חלב נותר, שאם \u0003אכל אחד את הראשונה\u0004 ובא אחר ואכל את השניה וכו' ר' שמעון אומר: זה מביא חטאת וזה מביא חטאת (על אכילת חלב) ושניהם מביאים חטאת אחת על הנותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 מכאן עולה שאיסור נותר חל על איסור החלב שכבר היה בחתיכה זו. ויש לשאול: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' שמעון איסור חל\u0004 על \u0003איסור?\u0004","\u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005], ר'\u0006 \u0003שמעון אומר: האוכל נבלה ביום הכיפורים\u0004 — \u0003פטור\u0004 משום אכילה ביום הכיפורים, משום שאין איסור יום הכיפורים חל על איסור נבילה!","\u0003אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 מדובר כאן \u0003כגון\u0004 שאכל \u0003כוליא בחלבה\u0004 \u0005[כליה עם החלב שלה],\u0006 שעל חלבה חייב משום חלב, ועל הכליה שלא נאסרה מתחילה — חייב משום נותר. ושואלים: \u0003וכוליא בחלבה נמי\u0004 \u0005[גם כן],\u0006 \u0003הא קאי עלה\u0004 \u0005[הרי עומד עליה]\u0006 \u0003באיסור עולין,\u0004 שחייב להעלותה למזבח, ומשום כך אסורה באכילה, ואם כן \u0003היכי אתי\u0004 \u0005[כיצד בא]\u0006 \u0003איסור נותר חייל עלה\u0004 \u0005[\u0006ו\u0005חל עליה]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003לר' שמעון\u0004 שאיסור \u0003נותר איסור חמור הוא, וחייל\u0004 \u0005[וחל]\u0006 \u0003על איסור קל\u0004 של \u0003עולין\u0004 — אין אתה יכול לומר כן, \u0003והא\u0004 \u0005[והרי]\u0006 איסור \u0003נבלה\u0004 שאיסור \u0003קל הוא\u0004 לפי הערך, שאינו אלא בעונש מלקות, \u0003ויום הכיפורים\u0004 ש\u0003איסור חמור הוא,\u0004 שעונשו כרת, \u0003ו\u0004מכל מקום, לדעת ר' שמעון \u0003לא קאתי\u0004 \u0005[בא]\u0006 \u0003איסור\u0004 אכילה ב\u0003יום כיפורים\u0004 ש\u0003חמור\u0004 הוא, \u0003וחייל\u0004 \u0005[וחל]\u0006 \u0003על נבלה\u0004 שאיסור \u0003קל הוא!\u0004","\u0003אלא\u0004 צריך לומר כך: דווקא \u0003בקדשים גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003איסור חל על איסור,\u0004"],["\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין איסור אכילת קדשים בטומאה, נאמר: \"והנפש אשר תאכל מבשר זבח השלמים אשר לה' וטומאתו עליו ונכרתה\" (ויקרא ז, כ), ומה שנאמר \u0003\"אשר לה'\"\u0004בא \u0003לרבות את האימורין,\u0004 החלקים הקרבים על המזבח, שאם אכלם בטומאת הגוף חייב כרת. \u0003ו\u0004הרי \u0003אימורין קאי עלייהו\u0004 \u0005[עומד עליהם]\u0006 \u0003באיסור עולין, וחלב\u0004 שהוא חלק מן האימורים \u0003קאי עלייהו\u0004 \u0005[עומד עליו]\u0006 \u0003באיסור כרת, ו\u0004בכל זאת \u0003קאתי\u0004 \u0005[בא]\u0006 \u0003איסור\u0004 אכילת קדשים ב\u0003טומאה חייל עליה\u0004 \u0005[\u0006ו\u0005חל עליו].\u0006 משמע שבקדשים יש דין מיוחד שאיסור חל על איסור.","","ומוכיחים: \u0003תדע שכן הוא, דהא\u0004 \u0005[שהרי]\u0006 \u0003רבי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שאיסור \u0003חל על איסור, (ואימא) והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 ב\u0003איסור חמור\u0004 שחל \u0003על איסור קל\u0004 ממנו, \u0003אבל איסור קל\u0004 ש\u0003חל על איסור\u0004 אחר \u0003והוא איסור חמור\u0004 ממנו — \u0003לא. ו\u0004אילו \u0003בקדשים שמעינן ליה דאמר\u0004 \u0005[שמענו אותו,\u0006 את רבי, \u0005שאומר]:\u0006 \u0003איסור קל על איסור חמור נמי חייל\u0004 \u0005[גם כן חל],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003איסור מעילה קל הוא,\u0004 שדינו לדעת רבי ב\u0003מיתה\u0004 בידי שמים, \u0003ואיסור\u0004 חלב \u0003קדשים איסור חמור\u0004 ממנו, שיש בו עונש \u0003כרת, ו\u0004בכל זאת \u0003אתי\u0004 \u0005[בא]\u0006 \u0003איסור מיתה חייל\u0004 \u0005[\u0006ו\u0005חל]\u0006 \u0003על איסור כרת.\u0004","","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005], רבי אומר\u0006 על הכתוב: האומר \"\u0003כל חלב לה'\"\u0004 (שם ג, טז) — הרי זה בא \u0003לרבות אימורי קדשים קלים למעילה.\u0004 \u0003ו\u0004הרי \u0003מעילה\u0004 לדעת רבי \u0003איסור מיתה\u0004 הוא, \u0003וקא חייל\u0004 \u0005[והוא חל]\u0006 \u0003על איסור חלב\u0004 של אימורי קדשים קלים, ש\u0003איסור כרת הוא, שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003בקדשים גלי קרא\u0004 \u0005[גילה המקרא]\u0006 שאיסור חל על איסור. וכאמור, מטעם זה מחייב ר' שמעון במשנתנו שתי חטאות על אכילת חלב נותר.","","ומקשים: \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005], ר'\u0006 \u0003שמעון אומר: אין\u0004 איסור אכילת \u0003פיגול בעולין\u0004 על המזבח \u0003ו\u0004גם \u0003אין\u0004 איסור אכילת \u0003נותר בעולין,\u0004 משום שגם בקדשים אין איסור חל על איסור! \u0003אלא יש לומר שתנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של ר' \u0003שמעון, דאיכא דאמרי\u0004 \u0005[שיש שאומרים]\u0006 לשיטתו \u0003בקדשים איסור חל על איסור,\u0004 והיא שיטת משנתנו, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003בקדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003אין איסור חל על איסור.\u0004 ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאמר]:\u0006 \u0003בקדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003אין איסור חל על איסור,\u0004 הכתוב \"\u0003כל חלב לה'\"\u0004 המלמד שאיסור מעילה חל גם על החלב, \u0003מאי עביד ליה\u0004 \u0005[מה עושה הוא בו]?\u0006","","","ומשיבים: \u0003מוקים ליה\u0004 \u0005[מעמיד אותו]\u0006 \u0003בולדי קדשים,\u0004 שדווקא בהם חל איסור מעילה, מפני \u0003דקסברי\u0004 \u0005[שסבורים]\u0006 בעלי שיטה זו שולדי \u0003קדשים בהוייתן יהו קדושים,\u0004 כלומר, בשעת לידתם הם נעשים קדושים, ולא קודם לכן, וכך נמצא \u0003דתרוייהו בהדדי אתו\u0004 \u0005[ששניהם בבת אחת באים],\u0006 איסור המעילה ואיסור החלב (שגם הוא אינו קיים בחלב העובר).","","\u0003המביא אשם תלוי,\u0004 שהיה ספק לו אם עבר עבירה, \u0003ונודע לו שלא חטא, אם עד שלא נשחט\u0004 האשם נודע לו — \u0003יצא\u0004 האיל \u0003וירעה בעדר\u0004 כשאר חולין, שהקדש טעות היה, אלו \u0003דברי ר' מאיר.\u0004","\u0003וחכמים אומרים:\u0004 אין דינו כבהמת חולין, אלא כאשם שנפסל מהקרבה, ולכן \u0003ירעה עד שיסתאב\u0004 (שיפול בו מום), ואז \u0003ימכר ויפלו דמיו לנדבה,\u0004 לקרבן עולה של ציבור. \u0003ר' אליעזר אומר: יקרב\u0004 האשם התלוי כמות שהוא, \u0003שאם אינו בא על חטא זה\u0004 — \u0003הרי הוא בא על חטא אחר\u0004 שחטא ולא נודע לו עליו.","\u0003אם משנשחט\u0004 כלומר, אם לאחר שנשחט האשם התלוי, וקיבל דמו בכוס כדי לזורקו על קרנות המזבח, \u0003נודע לו\u0004 שלא חטא — \u0003ישפך הדם\u0004 לאמה העוברת בעזרה, \u0003והבשר יצא לבית השריפה,\u0004 כדין קרבן פסול. אם \u0003נזרק הדם\u0004 על קרנות המזבח קודם שנודע לו \u0003והבשר קיים\u0004 — \u0003יאכל\u0004 הבשר לכהנים, כדינו, שמשעה שנזרק הדם נגמרה כפרתו, והותר הבשר לכהנים. \u0003ר' יוסי אומר: אפילו\u0004 היה \u0003הדם\u0004 עדיין \u0003בכוס\u0004 כשנודע לו שלא חטא — \u0003יזרק\u0004 הדם \u0003והבשר יאכל,\u0004 שכבר נתקדש הדם בכלי.","דין זה כולו אמור באשם תלוי, אבל אשם ודאי (כגון אשם מעילה, או אשם שפחה חרופה) \u0003אינו כן,\u0004 אלא אם \u0003עד שלא נשחט\u0004 נודע לו שאינו חייב בו — גם לדעת חכמים \u0003יצא וירעה בעדר,\u0004 כדין חולין. אם \u0003משנשחט\u0004 נודע לו — \u0003הרי זה יקבר,\u0004 כדין חולין שנשחטו בעזרה, ודמו יישפך. ואולם אם נודע לו מש \u0003נזרק הדם\u0004 — \u0003הבשר יצא לבית השריפה,\u0004 כדין קרבן פסול.","וכן \u0003שור הנסקל\u0004 (כגון שהרג אדם, ודנוהו לסקילה) — \u0003אינו כן,\u0004 אין דינו כאשם תלוי, אלא אם \u0003עד שלא נסקל\u0004 התברר שהעדות עליו היתה עדות שקר — \u0003יצא וירעה בעדר,\u0004 ואם נודע הדבר \u0003משנסקל\u0004 — הרי זה כאילו לא נידון, והוא \u0003מותר בהנאה.\u0004","וכן דין \u0003עגלה ערופה,\u0004 שמביאים על חלל שלא נודע מי היכהו, \u0003אינו כן,\u0004 אלא אם נודע הרוצח \u0003עד שלא נערפה\u0004 — \u0003תצא ותרעה בעדר,\u0004 ואולם, אם נודע מיהו הרוצח \u0003משנערפה\u0004 — \u0003תקבר במקומה,\u0004 כפי הראוי לעגלה ערופה, בהנאה. וטעם הדבר — \u0003שעל ספק באה מתחלה,\u0004 כדי לכפר על הספק, וכשנערפה קודם שנודע הרוצח — הרי כבר \u0003כיפרה ספקה והלכה לה,\u0004 שנעשתה מצוותה ותיקבר כדינה.","שנינו במשנה כי המביא אשם תלוי וקודם שנשחט נודע לו שלא חטא — ר' מאיר אומר: יצא וירעה בעדר, שחולין גמורים הוא, וחכמים אומרים שדינו כדין קדשים שנפסלו. ומסבירים: \u0003במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עיקרון הם חלוקים]? ר' \u0003מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דלא צריך ליה\u0004 \u0005[שאינו צריך אותו]\u0006 \u0003לא מקדיש ליה\u0004 \u0005[אינו מקדיש אותו],\u0006 כלומר, מתחילה לא הקדיש אותו אלא מתוך שסבור היה שהוא צריך אותו, וכיון שנתברר שלא היה צריך לו, בטלה קדושתו לגמרי מעיקרה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003מתוך שלבו נוקפו,\u0004 ודואג שמא חטא, הריהו \u0003גומר\u0004 בליבו \u0003ומקדיש\u0004 בשלמות, ולכן ההקדש הזה אינו בטל.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם]: \u0003בין שנודע לו שחטא ובין נודע לו שלא חטא פליגי\u0004 \u0005[חלוקים\u0006 בכך\u0005] ר'\u0006 \u0003מאיר ורבנן\u0004 \u0005[וחכמים]\u0006 האם האשם יוצא לחולין או לא. ומפרטים: מה שנחלקו \u0003בנודע לו שחטא\u0004 — \u0003להודיעך כחו\u0004 של ר' \u0003מאיר\u0004 עד כמה הוא מיקל, \u0003דאף על גב דידע\u0004 \u0005[שאף על פי שהוא יודע]\u0006 עכשיו ש\u0003חטא, כיון דבעידנא דאפרשיה\u0004 \u0005[שבזמן שהפרישו]\u0006 \u0003[לא ידע\u0004 שחטא, ונתברר שאינו צריך להקריב קרבן זה (אלא חייב חטאת) — \u0003תצא ותרעה בעדר.\u0004 \u0003ו\u0004מה שנחלקו \u0003בנודע לו שלא חטא\u0004 — בא \u0003להודיעך כחן דרבנן\u0004 \u0005[של חכמים],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 שלא \u0003חטא, כיון דבעידנא דאפרשיה\u0004 \u0005[שבזמן שהפרישו]\u0006 \u0003לא ידע]\u0004 — \u0003לבו נוקפו הוה\u0004 \u0005[היה],\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 \u0003גמר ומקדיש.\u0004 \u0003אמר רב ששת: מודה ר' מאיר לחכמים\u0004","",""],["\u0003במפריש שני אשמות\u0004 תלויים \u0003לאחריות,\u0004 שאם יאבד האחד יקריב את השני, \u0003ונתכפר באחת מהן,\u0004 שה\u0003שני\u0004 אינו חולין, אלא \u0003ירעה עד שיסתאב\u0004 (שיפול בו מום), \u0003וימכר ויפלו דמיו לנדבה.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן \u0003עד כאן לא פליגי\u0004 \u0005[חולק]\u0006\u0003 ר' מאיר עליהון דרבנן\u0004 \u0005[על חכמים],\u0006 וסבור כי המביא אשם תלוי ונודע לו שלא חטא יצא לחולין, \u0003אלא משום דלא גלי דעתיה\u0004 \u0005[שלא גילה\u0006 המקדיש \u0005דעתו]\u0006 מתחילה ש\u0003לבו נוקפו,\u0004 ולכן סבורים אנו שלא הקדישו אלא על דעת שיצטרך לו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כשהפריש שנים, \u0003מכדי חד הוא דאיבעי ליה לאפרושי\u0004 \u0005[הואיל\u0006 ומעיקר הדין \u0005אחד הוא ש\u0006היה \u0005צריך להפריש],\u0006 \u0003מאי טעמא אפריש תרי\u0004 \u0005[מה טעם הפריש שנים]?\u0006 מפני \u0003דסבר\u0004 \u0005[שסבור\u0006 היה\u0005]:\u0006 \u0003אי מירכס חדא מיכפרנא באידך חבריה\u0004 \u0005[אם יאבד אחד אתכפר באחר, חבירו],\u0006 \u0003וכיון דגלי דעתיה\u0004 \u0005[שגילה את דעתו]\u0006 שלבו \u0003נוקפו היה, הואיל וכך היה\u0004 אומרים אנו ש\u0003גמר והקדישו.\u0004","כיוצא בזה \u0003אמר רב יהודה אמר רב\u0004 לצד השני: \u0003מודים חכמים לר' מאיר, באשם תלוי שהוזמו עדיו,\u0004 שהעידו עליו עדים שעשה דבר שהיה ספק חטא (כגון שאכל חתיכה שהיא ספק חלב ספק שומן), ונתברר שעדי שקר הם, שלא היו כלל במקום — שיצא האשם \u0003וירעה בעדר\u0004 כחולין גמורים,","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]? עד כאן לא פליגי רבנן עליה\u0006 \u0005[לא\u0006 שמענו ש\u0005חלוקים חכמים עליו]\u0006 \u0003אלא היכא דאפרשיה\u0004 \u0005[במקום שהפרישו]\u0006 \u0003על פי עצמו, ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 \u0003לבו נוקפו\u0004 ולכן גמר והקדיש, \u0003אבל היכא\u0004 \u0005[במקום]\u0006 שעל \u0003פי עדים אפרשיה\u0004 \u0005[הפרישו]\u0006 — \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003סמוך\u0004 בדעתו \u0003עילוי\u0004 \u0005[עליהם]\u0006 על העדים, \u0003דסבר\u0004 \u0005[שסבור\u0006 היה\u0005]: דלמא אתו\u0006 \u0005[שמא יבואו]\u0006 עדים \u0003אחרים ומזמי להו\u0004 \u0005[ויזימו אותם].\u0006","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבא\u0004 ממה ששנינו במשנתנו: \u0003שור הנסקל\u0004 שנגמר דינו למיתה אינו כן, אין דינו כאשם תלוי, אלא גם לדעת חכמים, \u0003אם עד שלא נסקל\u0004 נודע שלא הרג — \u0003יצא וירעה בעדר.\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דאתו בי תרי אמרי\u0004 \u0005[אם תאמר שבאו שנים\u0006 מתחילה \u0005ואמרו]\u0006 שהרג השור, ודנוהו לסקילה, \u0003ובי תרי אמרי\u0004 \u0005[ושנים אומרים]\u0006 עכשיו שלא \u0003הרג\u0004 — \u0003מאי חזית דציית לבתראי\u0004 \u0005[מה רואה אתה שאתה שומע לאחרונים]?\u0006 \u0003ציית להו לקמאי\u0004 \u0005[שמע לראשונים]!\u0006","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003בעדי הזמה,\u0004 שהזימו את העדים הראשונים, שהעידו שלא היו כלל במקום, ועל כן האמינה התורה את האחרונים. \u0003ודכוותיה\u0004 \u0005[וכיוצא בו]\u0006 ל\u0003גבי אשם תלוי\u0004 שאליו השוותה המשנה דין זה, גם כן מדובר \u0003בעדי הזמה,\u0004 שהעידו בו עדים והפריש אשם תלוי על פיהם והוזמו, \u0003ופליגי\u0004 \u0005[ו\u0006בכל זאת \u0005חלוקים]\u0006 חכמים על ר' מאיר, וסבורים שאין האשם שהקדיש על פי עדים יוצא לחולין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 מכאן אין להוכיח, \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003שור הנסקל\u0004 שיצא וירעה בעדר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 לא בעדי הזמה, אלא \u0003כגון שבא הרוג ברגליו\u0004 כלומר, מי שהעידו שהשור הרגו בא לפנינו, והתברר ממילא שהעדות היתה שקר.","\u0003ודכוותיה\u0004 \u0005[וכיוצא בו]\u0006 ל\u0003גבי אשם תלוי,\u0004 מדובר שהפריש אשם תלוי על פי עצמו, וכיצד נודע לו שאינו חייב — \u0003כגון דהוכרה חתיכה,\u0004 שנודע לו שאכל היתר. \u0003אבל היכא דאפרשיה\u0004 \u0005[במקום שהפריש]\u0006 את האשם \u0003תלוי על פי עדים\u0004 — \u0003לא\u0004 גמר והקדיש, ולכן אם נודע לו — יצא וירעה בעדר.","ומעירים: מחלוקת זו, במי שהפריש אשם תלוי על פי עדים, והוזמו, מצויה גם \u0003בפלוגתא\u0004 \u0005[במחלוקת\u0006 אמוראים\u0005]\u0006 אחרים: \u0003אשם תלוי שהוזמו עדיו\u0004 — \u0003ר' אלעזר אומר: הרי היא כמנחת קנאות\u0004 של אשה סוטה שיש ספק אם נטמאה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006\u0003: נמצאו עדיה\u0004 של הסוטה, שהעידו שנסתרה עם פלוני, \u0003זוממין\u0004 — \u0003מנחתה תצא לחולין,\u0004 וכן דינו של אשם תלוי שהוזמו עדיו. ואילו ר' \u0003יוחנן\u0004","\u0003אמר:\u0004 אשם זה \u0003ירעה עד שיסתאב וימכר ויפלו דמיו לנדבה.\u0004 ושואלים: ור' \u0003יוחנן\u0004 גם כן, \u0003נדמייה\u0004 \u0005[שיידמה אותו]\u0006 \u0003למנחת קנאות!\u0004 ודוחים: \u0003לא דמי\u0004 \u0005[אין\u0006 הדבר \u0005דומה],\u0006 \u0003מנחת קנאות לא ל\u0004צורך \u0003כפרה קאתייא\u0004 \u0005[באה]\u0006 \u0003אלא לברר עון,\u0004 כדי שתיבדק האשה אם נטמאה, וכיון שנתברר שאין בה צורך — תצא לחולין. \u0003אבל אשם תלוי\u0004 שלכפרה \u0003אתי\u0004 \u0005[בא],\u0006 \u0003מתוך שלבו נוקפו גומר ומקדישו,\u0004 ולכן אינו יוצא לחולין.","\u0003אמר ר' כרוספדאי אמר ר' יוחנן: שור הנסקל שהוזמו עדיו, כל המחזיק בו זכה בו,\u0004 שהרי בעל השור, אחרי שהעידו בו ודנו אותו למיתה, כבר נתייאש ממנו והפקירו.","\u0003אמר רבא: מסתברא טעמא\u0004 \u0005[מסתבר טעמו]\u0006 של ר' \u0003יוחנן, כגון דאמרי ליה\u0004 \u0005[שאמרו לו]\u0006 ש\u0003נרבע שורו,\u0004 שמתוך שהוא סבור שהם עדי אמת, על כן הוא מפקיר את השור. \u0003אבל אמרו\u0004 שהוא עצמו \u0003רבע שורו,\u0004 הרי \u0003הוא בעצמו מידע ידיע\u0004 \u0005[יודע]\u0006 ש\u0003לא רבע\u0004 את שורו, \u0003ולא מפקר ליה\u0004 \u0005[ואינו מפקיר אותו],\u0006 \u0003וטרח ומייתי\u0004 \u0005[ו\u0006הוא \u0005טורח ומביא]\u0006 \u0003עדים\u0004 להזים את העדים הללו.","ושואלים: \u0003ומאי שנא מהא דאמר\u0004 \u0005[ובמה שונה\u0006 הדבר \u0005מזו שאמר]\u0006 \u0003רבה בר איתי אמר ריש לקיש: עיר הנדחת,\u0004 שכל רכושה נדון לשריפה, \u0003שהוזמו עדיה\u0004 כלומר, העדים שהעידו באנשי העיר שעבדו עבודה זרה — \u0003כל המחזיק בה\u0004 ברכוש שבה \u0003זכה בה,\u0004 למרות שהאנשים שבתוכה יודעים שלא הודחו לעבודה זרה?","ומשיבים: \u0003עיר הנדחת\u0004 — \u0003רבים נינהו\u0004 \u0005[הם],\u0006 \u0003כל חד אמר בדעתיה\u0004 \u0005[כל אחד אומר בדעתו]:\u0006 \u0003אנא לא חטאי\u0004 \u0005[\u0006גם אם \u0005אני לא חטאתי]\u0006 \u0003אחרינא\u0004 \u0005[\u0006אדם \u0005אחר]\u0006 \u0003חטא,\u0004 וסבור שהעיר עומדת כולה לשריפה, \u0003ומפקר ממוניה\u0004 \u0005[ומפקיר את ממונו].\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בשור הנסקל, \u0003דבדידיה תליא מילתא\u0004 \u0005[שבו\u0006 בלבד \u0005תלוי הדבר],\u0006 \u0003הוא בעצמו מידע ידע\u0004 \u0005[יודע]\u0006 שלא \u0003רבע, ולא מפקר ליה\u0004 \u0005[ואינו מפקיר אותו]\u0006 את השור, \u0003וטרח ומייתי\u0004 \u0005[וטורח ומביא]\u0006 \u0003עדים\u0004 להזים את עדותם, ולכן אם הוזמו עדיו — הרי הוא שלו, ואין אחר יכול לזכות בו.","אגב ההלכות שהוזכר בהן כי כל המחזיק בדבר זוכה בו, מביאים, \u0003אמר ריש לקיש: הנותן מתנה לחבירו, ואמר הלה\u0004 המקבל: \u0003\"אי אפשי\u0004 \u0005[אין רצוני]\u0006 \u0003בה\"\u0004 — \u0003כל המחזיק בה זכה בה,\u0004 שהפקירה.","ושואלים: \u0003ומאי שנא מהא\u0004 \u0005[ובמה שונה\u0006 הדבר מזו] ש\u0003אמר רבה בר אבוה אמר רב ששת, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר ר' אבהו אמר רב ששת: מקבל מתנה שאמר לאחר שבאת מתנה לידו: \"מתנה זו תיבטל\"\u0004 או: \"מתנה זו \u0003מבוטלת\",\u0004 או: \u0003\"אי אפשי\u0004 \u0005[אין רצוני]\u0006 \u0003בה\"\u0004 — \u0003דבריו קיימין.\u0004 אבל אם אמר: \u0003\"בטילה\u0004 היא\", או: \u0003\"אינה מתנה\"\u0004 — \u0003לא אמר כלום,\u0004"],["\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 כוונת \u0003דבריו קיימין\u0004 כשאומר \"אי אפשי בה\" — \u0003דהדרא למרה\u0004 \u0005[ש\u0006היא \u0005חוזרת לבעליה],\u0006 שלא כדברי ריש לקיש, שאמר שכל המחזיק בה זכה בה? ודוחים: \u0003לא, דבריו קיימין\u0004 כוונתו — \u0003והוא נמי לא קני לה\u0004 \u0005[והוא גם כן,\u0006 נותן המתנה, \u0005לא קונה אותה],\u0006 \u0003וכל המחזיק בה זכה בה,\u0004 שאינה שייכת לא לנותן ולא למקבל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ריש לקיש ממה ששנינו: \u0003האומר לחבירו,\u0004 שהיה שותף עמו בשדה: \u0003\"דין ודברים אין לי על שדה זו\",\u0004 או \u0003\"אין לי עסק בה\",\u0004 או \"ידי \u0003מסולקת הימנה\"\u0004 — \u0003לא אמר כלום,\u0004 לא איבד את זכותו בשדה. \u0003והא\u0004 \u0005[והרי]\u0006 הביטוי \u0003\"ידי מסולקת הימנה\" כ\"אי אפשי\" דמי\u0004 \u0005[נחשב],\u0006 \u0003וקתני\u0004 \u0005[והוא שונה]:\u0006 \u0003לא אמר כלום,\u0004 שלא כדברי ריש לקיש שאמר שכשאומר \"אי אפשי בה\" — כל שהחזיק בה זכה בה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003דאמר\u0004 \u0005[שאומרים\u0006 אנו\u0005]:\u0006 \u0003כי סליק נפשיה\u0004 \u0005[כאשר סילק עצמו]\u0006 הרי זה \u0003מדין ודברים,\u0004 שאומר שאינו רוצה להתדיין על שדה זו, אבל \u0003מגופה דשדה לא סליק נפשיה\u0004 \u0005[מגוף השדה לא סילק את עצמו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: שכיב מרע \u0003הכותב נכסיו לאחרים\u0004 במתנה \u0003והיו בהן\u0004 בתוך הנכסים \u0003עבדים, ואמר הלה\u0004 המקבל: \u0003\"אי אפשי בהן\"\u0004 בעבדים אלה, \u0003אם היה רבו שני\u0004 של העבד, כלומר, מקבל המתנה \u0003כהן\u0004 — \u0003אוכלין\u0004 אותם עבדים \u0003בתרומה,\u0004 כדין עבדי כהן, שאמירתו \"אי אפשי\" אינה מועילה. \u0003רבן שמעון בן גמליאל אומר: כיון שאמר \"אי אפשי בהן\"\u0004 — \u0003כבר זכו בהן יורשין\u0004 של הראשון, ולכן אינם נחשבים כעבדי הכהן אלא כעבדיו של ראשון.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבן שמעון בן גמליאל,\u0004 צריכים לומר כך: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003כי יהיב איניש\u0004 \u0005[כאשר נותן אדם]\u0006 \u0003מתנה\u0004 הרי זה \u0003אדעתא דמקבלין לה מיניה\u0004 \u0005[על דעת שיקבלו אותה ממנו],\u0006 ולפיכך \u0003כי לא מקבלין לה מיניה הדרא למרה\u0004 \u0005[כאשר אין מקבלים אותה ממנו היא חוזרת לבעליה],\u0006 שלא על דעת כן נתנה.","\u0003אלא ל\u0004שיטת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 נאמר כדברי ריש לקיש, \u0003כי אמר\u0004 \u0005[\u0006ש\u0005כאשר\u0006 אדם \u0005אומר]\u0006 \u0003\"אי אפשי בהן\" כל המחזיק בהן זכה בהן,\u0004 מפני שהם הפקר, אם כן \u0003הכא\u0004 \u0005[כאן]\u0006 שאמר \u0003שני \"אי אפשי בהן\"\u0004 — נמצא שהעבדים \u0003הוו להו\u0004 \u0005[הם]\u0006 \u0003זרים, וקאכלי\u0004 \u0005[ו\u0006נמצא ש\u0005אוכלים]\u0006 \u0003זרים תרומה!\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא הראשון ש\u0003המפקיר עבדו\u0004 — \u0003יצא לחירות, ו\u0004אולם עדיין \u0003צריך גט\u0004 (שטר) \u0003שחרור מרבו, וקסבר\u0004 \u0005[וסבור\u0006 גם כן\u0005]\u0006 שמעוכב \u0003לגט שחרור\u0004 כלומר, עבד שמשתחרר אבל עדיין אין בידו שטר שחרור, אם עבד כהן הוא — \u0003אוכל בתרומה.\u0004","שנינו במשנה בענין המביא אשם תלוי, וקודם שנשחט נודע לו שלא חטא, \u0003ר' אליעזר אומר: יקרב,\u0004 שאם אינו בא על חטא זה הרי הוא בא על חטא אחר. ושואלים: \u0003לר' אליעזר למה לי חטא\u0004 אחר? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר ר' אליעזר: אשם תלוי בנדבה אתי\u0004 \u0005[בא],\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: מתנדב אדם אשם תלוי בכל יום!\u0004","\u0003אמר רב אשי: ר' אליעזר\u0004 לשיטת אלו ש\u0003אמרו לו\u0004 לבבא בן בוטא \u0003הוא\u0004 ששונה כאן, \u0003דתנן\u0004 \u0005[ששנינו\u0006 בהמשך אותה משנה\u0005]:\u0006 שסיפר ר' אליעזר שבבא בן בוטא היה מביא אשם תלוי בכל יום, ורצה להביא גם מיד לאחר יום הכיפורים. \u0003אלא\u0004 שהיו \u0003אומרים לו: המתן עד שתכנס לבית הספק,\u0004 שעל כל פנים צריך שיהיה איזה ספק חטא בדבר, ואינו יכול להקריב אותו כנדבה גמורה.","בענין המביא אשם תלוי, \u0003אם משנשחט נודע\u0004 לו שלא חטא, \u0003קתני\u0004 \u0005[שונה]\u0006 התנא במשנתנו כי \u0003הבשר יצא לבית השרפה.\u0004 ומדייקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 שלדעת התנא \u0003חולין שנשחטו בעזרה,\u0004 כאשם תלוי זה, שנתברר שהוקדש בטעות — דינם \u0003בשריפה.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בהמשך המשנה: \u0003אשם ודאי אינו כן, אם עד שלא נשחט\u0004 נודע לו שלא חטא — \u0003יצא וירעה בעדר,\u0004 אם \u0003משנשחט\u0004 נודע לו — \u0003הרי זה יקבר,\u0004 משמע שחולין שנשחטו בעזרה דינם בקבורה! \u0003אמר ר' אלעזר: תברא\u0004 \u0005[שבורה]\u0006 המשנה, שאינה כשיטת חכם אחד, \u0003מי ששנה זו לא שנה זו.\u0004","\u0003אמר רבה\u0004 בתמיהה: \u0003אשם ודאי על אשם תלוי קרמית\u0004 \u0005[משליך אתה]?\u0006 \u0003אשם ודאי,\u0004 הרי הקדיש אותו על דעת שהוא חייב, \u0003כיון\u0004 ש\u0003לא צריך ליה\u0004 \u0005[אותו]\u0006 — \u0003לא מקדיש ליה\u0004 \u0005[אותו],\u0006 כלומר, הקדש טעות היה, והוא חולין. אבל \u0003אשם תלוי, מתוך שלבו נוקפו\u0004 שמא חטא — \u0003גומר\u0004 בלבו \u0003ומקדשו,\u0004 ואם כן, גם אם התברר שלא חטא — עדיין שם קרבן עליו, אלא שנפסל, ולכן דינו בשריפה.","\u0003אלא אי קשיא\u0004 \u0005[אם קשה]\u0006 במשנתנו, מ\u0003אשם ודאי על אשם ודאי קשיא\u0004 \u0005[קשה],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 בתחילה: אם משנשחט נודע שלא חטא — \u0003הרי זה יקבר,\u0004 ואולם \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של הלכה זו: נזרק הדם — \u0003והבשר יצא לבית השריפה!\u0004 ועל כך יש לומר \u0003הא ודאי תברא\u0004 \u0005[זו ודאי שבורה],\u0006 \u0003מי ששנה זו לא שנה זו.\u0004","\u0003רב אשי אמר: רישא דקתני\u0004 \u0005[\u0006ב\u0005תחילה שהוא שונה]\u0006 \u0003באשם תלוי: והבשר יצא לבית השריפה\u0004 — \u0003לא קשיא\u0004 \u0005[קשה]\u0006 מדוע אין נוהגים בו כחולין שנשחטו בעזרה, שייקברו — \u0003משום דמיתחזי\u0004 \u0005[ש\u0006הוא \u0005נראה]\u0006 \u0003כזבח פסול,\u0004 שדינו בשריפה.","שנינו במשנה, כי המביא אשם תלוי, ונודע לו שלא חטא לאחר ש\u0003נזרק הדם\u0004 — \u0003הבשר יאכל\u0004 לכהנים. ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא הויא ליה\u0004 \u0005[הרי\u0006 כבר \u0005היתה לו]\u0006 \u0003ידיעה,\u0004 ואין אשם תלוי בא אלא למי שלא נודע חטאו! \u0003אמר רבא, אמר קרא\u0004 \u0005[המקרא]: \"\u0006\u0003והוא לא ידע ונסלח לו\"\u0004 (ויקרא ה, יח), \u0003והא לא הויא ליה\u0004 \u0005[וזה לא היתה לו]\u0006 \u0003ידיעה בשעת סליחה,\u0004 כלומר בשעת זריקת הדם, שהיא עיקר הכפרה.","ועוד שנינו, \u0003ר' יוסי אומר: אפילו\u0004 היה \u0003הדם\u0004 של האשם התלוי \u0003בכוס\u0004 ולא נזרק עדיין, ונודע לו — ייזרק הדם, והבשר ייאכל. ושואלים: ל\u0003ר' יוסי אמאי\u0004 \u0005[מדוע]\u0006 \u0003יזרק? הא הויא ליה\u0004 \u0005[הרי היתה לו]\u0006 \u0003ידיעה בשעת סליחה! אמר רבא: ר' יוסי סבר לה\u0004 \u0005[סבור]\u0006\u0003 כ\u0004דעת ר' \u0003שמעון,\u0004 שאמר: \u0003כל\u0004 דם \u0003העומד ליזרק,\u0004 שנתקבל בכלי — \u0003כזרוק דמי\u0004 \u0005[נחשב].\u0006","ומקשים: \u0003אימר דאמר\u0004 \u0005[אמור שאמר]\u0006\u0003 ר' שמעון\u0004 דבר זה \u0003במידי\u0004 \u0005[בדבר]\u0006 שעומד בוודאות \u0003ליזרק, אבל האי\u0004 \u0005[זה]\u0006 שבא על הספק, מתחילתו \u0003אין עומד ליזרק! אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל],\u0006 \u0003קסבר\u0004 \u0005[סבור]\u0006\u0003 ר' יוסי: כלי שרת מקדשין בו את הפסול בתחלה ליקרב\u0004 כלומר, דבר שהוכנס לכלי שרת, אפילו הוא פסול — הרי הוא מתקדש עד כדי הקרבה.","שנינו במשנה: \u0003אשם ודאי אינו כן כו'.\u0004 וכן עגלה ערופה אינה כן, אם עד שלא נערפה נודע הרוצח — תצא ותרעה בעדר, כבהמת חולין, ואם משנערפה נודע הרוצח — תיקבר במקומה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בשאלה: \u0003עגלה ערופה אימתי נאסרת\u0004 מתי חל עליה איסור הנאה? \u0003רב המנונא אמר: מחיים\u0004 היא נאסרת, \u0003רבא אמר: לאחר עריפה.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006\u0003 ל\u0004שיטת \u0003רבא,\u0004 שהיא נאסרת \u0003מעידנא דאיתעביד\u0004 \u0005[מהזמן שנעשה]\u0006 \u0003בה מעשה,\u0004 משנערפה, \u0003אלא ל\u0004שיטת \u0003רב המנונא,\u0004 שאמר שמחיים היא נאסרת, \u0003מאימתי\u0004 בדיוק היא נאסרת?"],["\u0003אמר ר' ינאי: גבול שמעתי בה\u0004 ממתי נאסרת \u0003ושכחתי\u0004 מתי, \u0003ונסבין חברייא למימר\u0004 \u0005[ומציעים החברים לומר]\u0006 שירידתה \u0003לנחל איתן\u0004 היא \u0003אוסרתה.\u0004","\u0003אמר רב המנונא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 שמחיים היא נאסרת? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]: השוחט פרת חטאת\u0006 כלומר, פרה אדומה, \u0003ושור הנסקל, ועגלה ערופה,\u0004 ביום ששחט את אמם — ר' \u0003שמעון פוטר\u0004 על שחיטתם מאיסור שחיטת אותו ואת בנו, \u0003וחכמים מחייבין.\u0004","\u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח לשיטתי שאני אומר]\u0006 שעגלה ערופה \u0003מחיים\u0004 נאסרת, \u0003בהא פליגי\u0004 \u0005[בזה חלוקים]\u0006\u0003 ר' שמעון ורבנן\u0004 \u0005[וחכמים],\u0006 שר' \u0003שמעון\u0004 שפוטר \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003שחיטה שאינה ראויה\u0004 שאינה מכשירה את הבהמה לאכילה — \u0003לא שמה\u0004 \u0005[אינה קרויה]\u0006 \u0003שחיטה,\u0004 וכיוון ששחיטת העגלה אינה מכשירתה לאכילה, מפני שהיא כבר אסורה בהנאה, לכן פטור על כך משום אותו ואת בנו.","\u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]:\u0006 \u0003שחיטה שאינה ראויה שמה שחיטה,\u0004 ולכן חייב על כך. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שרק \u0003לאחר עריפה\u0004 היא נאסרת, \u0003אמאי פטר\u0004 \u0005[מדוע פוטר] ר'\u0006 \u0003שמעון?\u0004 הלוא \u0003שחיטה ראויה היא!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי טעם הדבר הוא ש\u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' שמעון\u0004 ש\u0003עגלה\u0004 ערופה גם \u0003בשחיטה כשרה,\u0004 ולאו דווקא בעריפה, ומפני כן שחיטה שאינה ראויה היא, שהרי בכך נאסרת העגלה בהנאה, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מה שכשר \u0003בפרה\u0004 אדומה \u0003פסול בעגלה ערופה,\u0004 ומה ש\u0003פסול בפרה כשר בעגלה ערופה.\u0004 כיצד? \u0003פרה\u0004 — דינה \u0003בשחיטה\u0004 דווקא, ובזה היא \u0003כשרה,\u0004 אבל \u0003בעריפה\u0004 היא \u0003פסולה,\u0004 ואילו \u0003עגלה\u0004 — דווקא \u0003בעריפה כשרה, בשחיטה פסולה!\u0004","\u0003אישתיק\u0004 \u0005[שתק]\u0006 רבא, שאמר שלאחר עריפה היא נאסרת, שלא מצא תשובה לדבר. \u0003לבתר דנפק\u0004 \u0005[אחרי שיצא],\u0006 \u0003אמר: מאי טעמא לא אמינא ליה\u0004 \u0005[מה טעם לא אמרתי לו]\u0006 לרב המנונא, ש\u0003ר' שמעון סבר\u0004 \u0005[סבור]\u0006 כי \u0003עגלה בשחיטה כשירה,\u0004 והוא חולק על מה ששנינו שהכשר בפרה פסול בעגלה!","ומעירים: \u0003ורב המנונא אמר לך\u0004 \u0005[היה אומר לך]\u0006 כנגד זה: \u0003לא נשתמיט תנא דנשמעינן\u0004 \u0005[לא נשמט\u0006 \u0005תנא שישמיע לנו]\u0006 ש\u0003עגלה בשחיטה כשרה,\u0004 אין מי ששונה דעה כזו, \u0003דתימא\u0004 \u0005[שתאמר]\u0006 ששיטת ר' \u0003שמעון היא.\u0004","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה]\u0006 את שיטתי, שעגלה ערופה נאסרת רק לאחר עריפה? \u0003מדתנן\u0004 \u0005[ממה ששנינו]\u0006 במשנתנו: \u0003עגלה ערופה אינה כן,\u0004 אם \u0003עד שלא נערפה\u0004 נודע מי הרוצח — \u0003תצא ותרעה בעדר\u0004 ככל בהמה. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שנאסרת \u0003מחיים, אמאי\u0004 \u0005[מדוע]\u0006 \u0003תצא ותרעה בעדר? הא איתסרא לה\u0004 \u0005[הרי\u0006 כבר \u0005נאסרה לה]\u0006 \u0003מחיים!\u0004","ודוחים, \u0003תני\u0004 \u0005[שנה\u0006 במשנה\u0005]:\u0006 \u0003עד שלא נראית לעריפה,\u0004 כלומר, אם קודם שהורידוה לנחל נודע הרוצח — תצא ותרעה בעדר, אבל לאחר מכן — אסורה בהנאה. מוסיף עוד רבא להוכיח, \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של המשנה: אם \u0003משנערפה\u0004 נודע ההורג — \u0003תקבר במקומה,\u0004 משמע שרק משנערפה נאסרה! ודוחים: \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003משנראית לעריפה\u0004 תיקבר.","מקשה על כך רבא: \u0003אם כן,\u0004 שמכאן אתה מוכיח, \u0003אימא סיפא\u0004 \u0005[אמור את סופה],\u0006 את הנימוק להלכה זו: מדוע תיקבר? מפני \u0003שעל הספק באה מתחלה, כיפרה ספיקה והלכה לה. ואי\u0004 \u0005[ואם]\u0006 כבר \u0003מחיים\u0004 מדובר, הרי \u0003עדיין לא כיפרה ספיקתה!\u0004 אלא מוכח ממשנתנו כי רק לאחר עריפה היא נאסרת.","ומעירים: אף שכך מוכח ממשנתנו, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 כשיטת רב המנונא: \u0003נאמר מכשיר\u0004 בפנים (במקדש), כלומר, אשם מצורע, שמכשיר ומטהר את המצורע לאכול קדשים, \u0003ו\u0004נאמר \u0003מכפר בפנים,\u0004 שאר חטאות ואשמות. \u0003ו\u0004כן \u0003נאמר מכשיר\u0004 בחוץ, שתי הציפורים שמטהרים על ידן את המצורע, \u0003ו\u0004נאמר \u0003מכפר בחוץ,\u0004 עגלה ערופה, שמכפרת מחוץ למקדש.","\u0003מה מכשיר ומכפר האמור בפנים עשה בו מכשיר כמכפר,\u0004 שדינו של אשם מצורע כדין שאר קרבנות — \u0003אף מכשיר [ומכפר] האמור בחוץ עשה\u0004 בו \u0003מכשיר כמכפר,\u0004 שכשם שעגלה ערופה נאסרת מחיים — כך ציפורי מצורע נאסרות מחיים. הרי שלדעת תנא זה עגלה ערופה אסורה מחיים.","גם אם אין לו ספק ידוע של עבירה. \u0003הוא היה נקרא אשם חסידים,\u0004 שחסידים ויראי חטא היו מביאים אשם זה בכל עת, שמא חטאו. \u0003אמרו עליו על בבא בן בוטא שהיה מתנדב אשם תלוי בכל יום, חוץ מאחר יום כיפורים יום אחד\u0004 שלא היה מביא.","\u0003אמר\u0004 בבא בן בוטא בלשון שבועה: \u0003המעון\u0004 (המקדש) \u0003הזה! אילו היו מניחין לי הייתי מביא\u0004 גם ביום זה, \u0003אלא אומרים לי: המתין עד שתכנס לספק,\u0004 שהרי ביום הכפורים התכפרו כל עוונותיו, ואין על מה להביא מיד קרבן למחרת. \u0003וחכמים אומרים: אין מביא אשם תלוי אלא על\u0004 ספק בדבר \u0003ש\u0004על \u0003זדונו\u0004 חייב \u0003כרת ו\u0004על \u0003שגגתו\u0004 מביא \u0003חטאת.\u0004","\u0003חייבי חטאות ואשמות ודאין שעבר עליהן יום הכיפורים\u0004 — \u0003חייבין להביא\u0004 קרבנם \u0003לאחר יום הכיפורים, וחייבי אשמות תלויין\u0004 שעבר עליהם יום הכיפורים — \u0003פטורין. מי שבא בידו ספק עבירה ביום הכפורים אפילו עם חשיכה\u0004 כלומר, סמוך לסוף היום — הרי זה \u0003פטור\u0004 מלהביא אשם תלוי, לפי \u0003שכל היום מכפר.\u0004","\u0003האשה שיש עליה\u0004 חובה להביא \u0003חטאת העוף\u0004 מספק, כגון שספק אם נתחייבה בקרבן יולדת, שמא לא הפילה ולד, \u0003ועבר עליה יום הכפורים\u0004 — \u0003חייבת להביא\u0004 חטאת זו \u0003לאחר יום הכיפורים, מפני ש\u0004אינה באה לכפרת עוונות אלא \u0003היא מכשרת\u0004 את האשה \u0003לאכול בזבחים. חטאת העוף הבאה על הספק, אם משנמלקה\u0004 החטאת \u0003נודע\u0004 לה שהיתה פטורה מקרבן — הרי זו \u0003תקבר.\u0004","שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של ר' \u0003אליעזר,\u0004 שהוא סבור שיכול אדם להביא אשם תלוי בנדבה? ומסבירים: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך לומר]\u0006 שאשם תלוי \u0003חובה\u0004 גמורה \u0003היא,\u0004 כאשר \u0003מתיידע ליה\u0004 \u0005[נודע לו]\u0006 שאכן חטא \u0003אמאי מייתי\u0004 \u0005[מדוע מביא]\u0006 \u0003חטאת?\u0004 הרי כבר נתכפר לו באשם שהביא מתחילה! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שנדבה \u0003היא.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים: \u0003עולה ושלמים הוא דאתו\u0004 \u0005[שבאים]\u0006 \u0003בנדר ונדבה, אבל חטאת ואשם\u0004 — \u0003חובה נינהו\u0004 \u0005[הם],\u0006 ובכלל זה גם אשם תלוי. \u0003ואשם תלוי היינו טעמא דמייתי מקמי דמתיידע ליה\u0004 \u0005[זהו הטעם שמביא לפני שנודע לו]\u0006 אם חטא — לא כדי להתכפר, אלא כדי \u0003להגן עליו\u0004 מן היסורים עד שייתוודע לו, מפני ש\u0003התורה חסה על גופן של ישראל,\u0004 ולכן חייבה אותם להביאו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 לשיטת חכמים, מהו ההכרח לומר שאשם תלוי בא אך ורק כחובה? \u0003דילמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003אשם תלוי\u0004 דינו \u0003כעולה ושלמים, מה עולה ושלמים\u0004 יש \u0003דאתו\u0004 \u0005[שבאים]\u0006 \u0003בחובה,\u0004 וכגון עולת ראיה ושלמי חגיגה, \u0003ואתו\u0004 \u0005[ו\u0006יש \u0005שבאים]\u0006 גם \u0003בנדבה, אשם תלוי נמי\u0004 \u0005[גם כן]\u0006 \u0003דאתי\u0004 \u0005[שבא]\u0006 \u0003בחובה\u0004 נאמר כי הוא \u0003אתי נמי\u0004 \u0005[בא גם כן]\u0006 \u0003בנדבה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עולה ושלמים עיקר\u0004 ענייניהם \u0003בנדבה כתיבי\u0004 \u0005[כתובים],\u0006 אלא שהם באים גם כחובה במקרים מיוחדים שציוותה התורה, ואילו \u0003אשם תלוי עיקר\u0004 עניינו \u0003בחובה כתיב\u0004 \u0005[כתוב],\u0006 יחד עם החטאות והאשמות, ובהתאם לכך יש לדון עליו.","\u0003תני\u0004 \u0005[שנה] ר'\u0006 \u0003חייא קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא:\u0004"],["\u0003אשם תלוי בא על הנבלה\u0004 כלומר, גם על ספק של אכילת נבילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו], \u0003וחכמים אומרים: אינו מביא אשם תלוי אלא על דבר שזדונו כרת ושגגתו חטאת,\u0004 ובנבילה יש רק איסור לא תעשה! \u0003ואי\u0004 \u0005[ואם]\u0006 אומר אתה שזו היא שיטת ר' \u0003אליעזר,\u0004 אם כן לאו דווקא על ספק איסור, אלא \u0003בנדבה נמי אתי\u0004 \u0005[גם כן בא]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא: \u0003מאי טעמא לא מתנית\u0004 \u0005[מה הטעם לא שנית]\u0006 ולמדת? \u0003זימנין סגיאין תניתה קמי מר\u0004 \u0005[פעמים רבות שניתי\u0006 ברייתא \u0005זו לפני האדון],\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003רבה, ואמר לי: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת ר' \u0003אליעזר היא,\u0004 ואולם לא לדעת עצמו, שמביאים אשם תלוי בנדבה, אלא לפי הטענה שהביא בשם אלו ש\u0003אמרו לו\u0004 לבבא בן בוטא, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005]: אלא אומרים ל\u0006\u0003ו המתן עד שתכנס לבית הספק.\u0004 ומכאן שבכל מקרה של ספק עבירה יכול אדם להביא אשם תלוי. \u0003אמר\u0004","\u0003רבא: מאי טעמא\u0004 \u0005[מה טעמם]\u0006 של אלה שאמרו \u0003לו\u0004 לבבא בן בוטא? \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין אשם תלוי: \"ועשתה אחת מכל מצות ה' \u0003אשר לא תעשינה\u0004 ולא ידע \u0003ואשם\"\u0004 (ויקרא ה, יז), כלומר, כל דבר שאסרה התורה לעשותו.","\u0003אמר רבא: מאי טעמא דרבנן דאמרי\u0004 \u0005[מה טעמם של חכמים\u0006 במשנתנו \u0005שאומרים]:\u0006 \u0003אין מביאין אשם תלוי אלא על דבר שזדונו כרת ושגגתו חטאת? ילפי\u0004 \u0005[לומדים הם]\u0006 בגזירה שווה \"\u0003מצו‍ת\" \"מצו‍ת\" מחטאת חלב,\u0004 כלומר, חטאת רגילה,","\u0003מה להלן\u0004 בחטאת שנאמר בה \"אחת ממצוות ה'\" (שם ד, כז), הרי זה דבר \u0003שזדונו כרת ושגגתו חטאת, אף כאן\u0004 באשם תלוי, שנאמר בו \"מצוות\" (שם ה, יד), מביא על ספק \u0003דבר שזדונו כרת ושגגתו חטאת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003חמשה אשמות מכפרין, אשם תלוי אין מכפר כפרה גמורה.\u0004 ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 מה פירוש הדברים הללו? \u0003אמר רב יוסף, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003חמשה אשמות מכפרין כפרה גמורה,\u0004 שאין עוד כפרה אחריהם, \u0003ואשם תלוי אין מכפר כפרה גמורה,\u0004 כי כשייוודע לו שחטא צריך להביא חטאת.","\u0003ו\u0004הוא ש\u0003לא כ\u0004שיטת ר' \u0003אליעזר\u0004 (לשיטת \"אמרו לו\", כמבואר לעיל) שאמר: \u0003אשם תלוי בא על הנבלה,\u0004 והרי במקרה זה, גם אם ייוודע לו שאכל נבילה — אינו צריך כפרה נוספת, שאין מביאים על כך חטאת.","\u0003רבינא אמר, הכי קתני\u0004 \u0005[כך הוא שונה],\u0006 לכך הכוונה: \u0003חמשה אשמות אין\u0004 דבר \u0003אחר מכפר כפרתן, דכי מתיידע ליה מייתי\u0004 \u0005[שכאשר נודע לו\u0006 שחטא \u0005מביא\u0006 קרבן\u0005],\u0006 ואילו \u0003אשם תלוי\u0004 — דבר \u0003אחר מכפר כפרתו, דלכי מתיידע לא מייתי\u0004 \u0005[שכאשר נודע לו\u0006 שספק חטא יש ש\u0005אינו מביא\u0006 אשם תלוי\u0005],\u0006 \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003חייבי חטאות ואשמות ודאין שעבר עליהן יום הכפורים\u0004 — \u0003חייבין להביא אחר יום הכפורים, חייבי אשמות תלויין\u0004 שעבר עליהם יום הכיפורים — \u0003פטורין\u0004 מלהביא אשם תלוי.","שנינו במשנה: \u0003חייבי חטאות ואשמות ודאין\u0004 וכו'. וכך \u0003קתני\u0004 \u0005[שונה]\u0006 התנא: \u0003חייבי חטאות ואשמות ודאין שעבר עליהן יום הכפורים\u0004 — \u0003חייבין להביא לאחר יום הכפורים, חייבי אשמות תלויין\u0004 — \u0003פטורין.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שיום הכיפורים אינו מכפר על חייבי חטאות ואשמות ודאים?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם ר' \u0003אמי אמר ר' חנינא, אמר קרא\u0004 \u0005[המקרא]\u0006 ביום הכיפורים: \u0003\"וכפר על הקדש מטומאת בני ישראל ומפשעיהם לכל חטאתם\"\u0004 (שם טז, טז), \u0003חטאים\u0004 שנזכרו שם, שנעשו בשגגה, הריהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 לפשעים, כלומר, דברים שנעשים במזיד, \u0003מה פשעים\u0004 הם עוונות \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן,\u0004 שאין מביאים קרבן על הזדון — \u0003אף חטאים דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן מכפר\u0004 עליהם יום הכיפורים, \u0003אבל חטאים\u0004 שהם \u0003בני קרבן,\u0004 שמביאים עליהן קרבן חטאת — יום הכיפורים \u0003לא מכפר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 כיצד אתה מוכיח מכאן? \u0003והא כי כתיב הדין קרא\u0004 \u0005[והרי כאשר נאמר כתוב זה]\u0006 \u0003בשעיר הנעשה\u0004 ביום הכיפורים \u0003בפנים הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שכפרתו מועטת, שהוא \u0003לא מכפר על עבירות מצוה\u0004 שידועה לו, אלא רק על מה שלא נודע לו. ושמא דווקא קרבן זה אינו מכפר על חטא שהוא בן קרבן, \u0003אבל שעיר המשתלח\u0004 לעזאזל, שמכפר גם \u0003על עבירות\u0004 של \u0003מצוה ידועה,\u0004 שהרי הוא מכפר גם על הזדונות — \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003לך: אפילו על חטאים\u0004 שבני \u0003קרבן נינהו\u0004 \u0005[הם]\u0006 \u0003מכפר!\u0004","\u0003אלא אמר אביי, מהכא\u0004 \u0005[מכאן]\u0006 נלמד הדבר, שנאמר בשעיר המשתלח: \u0003\"והתודה עליו את כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם\"\u0004 (ויקרא טז כא), \u0003חטאים\u0004 האמורים כאן הריהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 לפשעים, \u0003מה פשעים\u0004 הם דברים \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן,\u0004 שאין קרבן על המזיד — \u0003אף חטאים\u0004 האמורים כאן הריהם אלו \u0003דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן, אבל חטאים\u0004 שבני \u0003קרבן נינהו\u0004 \u0005[הם]\u0006 — \u0003לא מכפר\u0004 שעיר המשתלח. \u0003ומיעטיה קרא\u0004 \u0005[ומיעט אותו הכתוב]\u0006 \u0003בשעיר המשתלח למימרא\u0004 \u0005[לומר]\u0006 שלמרות שכפרתו מרובה, \u0003על חטאים\u0004 שבני \u0003קרבן נינהו\u0004 \u0005[הם]\u0006 \u0003לא מכפר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב דימי: ממאי\u0004 \u0005[ממה,\u0006 מניין לך\u0005]\u0006 \u0003דהני\u0004 \u0005[שאותם]\u0006 \u0003פשעים\u0004 שכתובים בפסוק זה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני קרבן נינהו\u0004 \u0005[הם]?\u0006 \u0003דלמא הני\u0004 \u0005[שמא\u0006 מדובר גם ב\u0005אלה]\u0006 שבני \u0003קרבן נינהו\u0004 \u0005[הם],\u0006 \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005],\u0006 \u0003ארבעה מביאין על הזדון כשגגה:\u0004 הבא על השפחה, ונזיר שנטמא, ושבועת העדות, ושבועת הפקדון! לקושיה זו לא ניתנה תשובה בשם אביי.","ועוד \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בענין זה: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל הביא עמו שמועה זו, ש\u0003אמר ר' יוסי אמר ריש לקיש:\u0004 מנין שיום הכיפורים אינו מכפר על חייבי חטאות ואשמות ודאים? שנאמר בשעיר המשתלח \u0003\"והתודה עליו את כל עונות בני ישראל ואת כל פשעיהם לכל חטאתם\"\u0004 (שם), \u0003חטאים\u0004 האמורים כאן הריהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 לפשעים, \u0003מה פשעים דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן מכפר\u0004 עליהם השעיר המשתלח, \u0003אף חטאים דלאו\u0004 \u0005[שלא]\u0006 \u0003בני קרבן מכפר\u0004 הוא, \u0003אבל חטאים\u0004 שבני \u0003קרבן לא מכפר. אמר\u0004","\u0003אביי: אנא נמי מהדין קרא אמרי\u0004 \u0005[אני גם כן מאותו מקרא אמרתי],\u0006 כפי שנאמר לעיל, \u0003ואקשי\u0004 \u0005[והקשה]\u0006 \u0003לי רב דימי: ממאי\u0004 \u0005[מנין]\u0006 יודע אתה \u0003דהני\u0004 \u0005[שאותם]\u0006 \u0003פשעים דלאו\u0004 \u0005[שלא]\u0006 \u0003בני קרבן נינהו\u0004 \u0005[הם]?\u0006 \u0003דלמא הנך\u0004 \u0005[שמא\u0006 מדובר ב\u0005אלה]\u0006 שבני \u0003קרבן נינהו\u0004 \u0005[הם],\u0006 \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]: ארבעה מביאין על הזדון כשגגה! אמר ליה\u0006 \u0005[לו]\u0006 \u0003רבין\u0004 לאביי, אפשר לתרץ: \u0003רוב\u0004 ה\u0003פשעים\u0004 הרי \u0003לאו\u0004 \u0005[אינם]\u0006 \u0003בני קרבן. אמר ליה\u0004 \u0005[לו]\u0006 אביי: אין בכך תשובה, \u0003מידי\u0004 \u0005[כלום] \"\u0006\u0003רוב\u0004 פשעיהם\" \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק זה?","\u0003אלא אמר אביי,\u0004 יש להביא ראיה \u0003מרישיה דקרא\u0004 \u0005[מתחילתו של הכתוב]:\u0006 שנאמר \"\u0003והתודה עליו את כל עונות בני ישראל\", ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006\u0003: \"עונות\"\u0004 — \u0003אלו זדונות, וכן הוא אומר:\u0004 \"כי דבר ה' בזה... \u0003עונה בה\"\u0004 (במדבר טו, לא), ואם כן","\u0003\"ואת כל פשעיהם לכל חטאתם\" כל למה לי?\u0004 לשם מה הוצרך לחזור ולהזכיר פשעים, שגם הם זדונות? אלא \u0003לאקשויי\u0004 \u0005[להקיש]\u0006 את החטאים \u0003לפשעים, מה פשעים דלאו\u0004 \u0005[שרובם אינם]\u0006 \u0003בני קרבן, אף חטאים דלאו\u0004 \u0005[שאינם]\u0006 \u0003בני קרבן, אבל חטאים\u0004 שבני \u0003קרבן נינהו\u0004 \u0005[הם]\u0006 \u0003לא מכפר\u0004 שעיר המשתלח.","שנינו במשנה: \u0003חייבי אשמות תלויין\u0004 שעבר עליהם יום הכיפורים — פטורים מלהביא אשם תלוי. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' אלעזר, אמר קרא\u0004 \u0005[המקרא]\u0006 ביום הכיפורים: \"כי ביום הזה... \u0003מכל חטאתיכם לפני ה'\u0004 תטהרו\" (ויקרא טז, ל), לומר: \u0003חטא שאין מכיר בו אלא המקום\u0004 (\"לפני ה'\") שהוא חטא שאינו ידוע, ועליו מביאים אשם תלוי — עליו \u0003יום הכפורים מכפר.\u0004","\u0003אמר רב תחליפא אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: קדמייתא נמי\u0004 \u0005[הראשונה גם כן],\u0006 הדין הקודם במשנה, שחייבי חטאות ואשמות ודאים אינם נפטרים ביום הכיפורים, \u0003לא תיתי\u0004 \u0005[אין אתה יכול להביא,\u0006 ללמוד\u0005]\u0006"]]};
